local Library = (function()
local LeakDUI = (function()
    -- ===================================================================
    --  LeakD UI  -  Teddy-style layout, gold theme
    --  API tuong thich voi lop boc UIX (Tab:Toggle/Slider/Dropdown/Button/Paragraph/Input)
    -- ===================================================================
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local UIS = game:GetService("UserInputService")
    local CoreGui = game:GetService("CoreGui")
    local V2, U2, UD, C3 = Vector2.new, UDim2.new, UDim.new, Color3.fromRGB
    local FONT_B, FONT_M = Enum.Font.GothamBold, Enum.Font.GothamMedium
    local LEFT, CENTER = Enum.TextXAlignment.Left, Enum.TextXAlignment.Center
    local AUTO_Y = Enum.AutomaticSize.Y
    local ORDER = Enum.SortOrder.LayoutOrder

    local M = {}
    M.Destroyed = false

    -- ------------------------------------------------------------ theme
    local THEMES = {
        Gold = { C3(255, 196, 46), C3(168, 120, 12), C3(255, 230, 150) },
        Amber = { C3(255, 150, 30), C3(160, 84, 8), C3(255, 208, 140) },
        Emerald = { C3(60, 220, 150), C3(20, 120, 84), C3(170, 255, 220) },
        Sky = { C3(80, 170, 255), C3(30, 90, 160), C3(180, 220, 255) },
        Violet = { C3(170, 110, 255), C3(90, 50, 160), C3(220, 195, 255) },
        Rose = { C3(255, 110, 160), C3(150, 40, 80), C3(255, 200, 220) },
        Crimson = { C3(240, 70, 70), C3(130, 24, 24), C3(255, 170, 170) },
        Silver = { C3(210, 214, 224), C3(110, 114, 128), C3(245, 247, 252) },
    }
    local T = { Name = "Gold" }
    local function setThemeColors(name)
        local th = THEMES[name]
        T.Name = name
        T.Accent, T.Dark, T.Soft = th[1], th[2], th[3]
    end
    setThemeColors("Gold")

    local BG = C3(14, 15, 22)
    local PANEL = C3(28, 28, 36)
    local FIELD = C3(20, 20, 27)
    local TXT = C3(236, 236, 240)
    local DESC = C3(168, 168, 180)
    local IDLE = C3(92, 92, 104)

    local binds, themeCbs = {}, {}
    local function bind(obj, prop, key)
        obj[prop] = T[key]
        binds[#binds + 1] = { obj, prop, key }
    end
    local function themed(obj, fn)
        pcall(fn)
        themeCbs[#themeCbs + 1] = { obj = obj, fn = fn }
    end
    local tabRefresh = nil
    local function applyTheme()
        local keep = {}
        for _, b in ipairs(binds) do
            if b[1].Parent ~= nil then
                b[1][b[2]] = T[b[3]]
                keep[#keep + 1] = b
            end
        end
        binds = keep
        local keep2 = {}
        for _, c in ipairs(themeCbs) do
            if c.obj.Parent ~= nil then
                pcall(c.fn)
                keep2[#keep2 + 1] = c
            end
        end
        themeCbs = keep2
        if tabRefresh then
            pcall(tabRefresh)
        end
    end

    -- ------------------------------------------------------------ helpers
    local function new(class, props, kids)
        local o = Instance.new(class)
        local parent
        for k, v in pairs(props or {}) do
            if k == "Parent" then
                parent = v
            else
                o[k] = v
            end
        end
        for _, c in ipairs(kids or {}) do
            c.Parent = o
        end
        if parent then
            o.Parent = parent
        end
        return o
    end
    local function corner(p, r)
        return new("UICorner", { CornerRadius = UD(0, r or 6), Parent = p })
    end
    local function stroke(p, key, thick, transp)
        local s = new("UIStroke", { Thickness = thick or 1, Transparency = transp or 0.5, Parent = p })
        bind(s, "Color", key or "Dark")
        return s
    end
    local function tween(o, t, props, style)
        local ok, tw = pcall(function()
            return TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
        end)
        if ok and tw then
            tw:Play()
            return tw
        end
        for k, v in pairs(props) do
            pcall(function() o[k] = v end)
        end
    end
    local function label(parent, p)
        p.BackgroundTransparency = 1
        p.Font = p.Font or FONT_M
        p.TextColor3 = p.TextColor3 or TXT
        p.TextSize = p.TextSize or 13
        p.TextXAlignment = p.TextXAlignment or LEFT
        p.Parent = parent
        return new("TextLabel", p)
    end
    local function isBlank(s)
        if s == nil then
            return true
        end
        return (tostring(s):gsub("%s", "")) == ""
    end
    local function plain(s)
        return (tostring(s or ""):gsub("<[^>]+>", ""))
    end
    local function safeCall(fn, ...)
        if not fn then
            return
        end
        local args = { ... }
        task.spawn(function()
            local ok, err = pcall(fn, table.unpack(args))
            if not ok then
                warn("[LeakD UI] " .. tostring(err))
            end
        end)
    end
    local function isPointer(i)
        return i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch
    end
    local ICONS = {
        info = "ℹ", settings = "⚙", zap = "⚡", anchor = "⚓", list = "📋", flag = "🏁", ship = "🚢",
        flame = "🔥", ghost = "👻", ["bar-chart-3"] = "📊", swords = "⚔", ["map-pin"] = "📍",
        ["shopping-cart"] = "🛒", shield = "🛡", ["more-horizontal"] = "⋯", music = "🎵",
    }

    -- ------------------------------------------------------------ gui root + toasts
    local Gui, NotiHolder
    local notiOrder = 0
    local function ensureGui()
        if Gui and Gui.Parent then
            return Gui
        end
        local parent
        local ok, h = pcall(function()
            return gethui and gethui()
        end)
        if ok and h then
            parent = h
        else
            parent = CoreGui
        end
        pcall(function()
            for _, c in ipairs(parent:GetChildren()) do
                if c.Name == "LeakDHub2UI" then
                    c:Destroy()
                end
            end
        end)
        Gui = new("ScreenGui", {
            Name = "LeakDHub2UI", ResetOnSpawn = false, DisplayOrder = 999, IgnoreGuiInset = true,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        })
        local ok2 = pcall(function() Gui.Parent = parent end)
        if not ok2 then
            Gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
        end
        NotiHolder = new("Frame", {
            Name = "Toasts", BackgroundTransparency = 1, AnchorPoint = V2(1, 0), Position = U2(1, -12, 0, 44),
            Size = U2(0, 270, 1, -64), ZIndex = 100, Parent = Gui,
        })
        new("UIListLayout", {
            Padding = UD(0, 6), SortOrder = ORDER, HorizontalAlignment = Enum.HorizontalAlignment.Right,
            VerticalAlignment = Enum.VerticalAlignment.Top, Parent = NotiHolder,
        })
        return Gui
    end

    local function toast(title, content, duration, dot)
        ensureGui()
        duration = tonumber(duration) or 4
        notiOrder = notiOrder + 1
        local kids = NotiHolder:GetChildren()
        local count = 0
        for _, c in ipairs(kids) do
            if c:IsA("Frame") then
                count = count + 1
            end
        end
        if count >= 5 then
            for _, c in ipairs(kids) do
                if c:IsA("Frame") then
                    c:Destroy()
                    break
                end
            end
        end
        local card = new("Frame", {
            BackgroundColor3 = C3(22, 22, 29), BackgroundTransparency = 1, Size = U2(1, 0, 0, 0),
            AutomaticSize = AUTO_Y, BorderSizePixel = 0, LayoutOrder = notiOrder, Parent = NotiHolder,
        })
        corner(card, 7)
        local st = new("UIStroke", { Thickness = 1, Transparency = 1, Parent = card })
        bind(st, "Color", "Accent")
        local bar = new("Frame", { Size = U2(0, 3, 1, -10), Position = U2(0, 5, 0, 5), BorderSizePixel = 0, Parent = card })
        if dot then
            bar.BackgroundColor3 = dot
        else
            bind(bar, "BackgroundColor3", "Accent")
        end
        corner(bar, 2)
        local inner = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, Parent = card })
        new("UIPadding", { PaddingLeft = UD(0, 16), PaddingRight = UD(0, 10), PaddingTop = UD(0, 7), PaddingBottom = UD(0, 8), Parent = inner })
        new("UIListLayout", { Padding = UD(0, 2), SortOrder = ORDER, Parent = inner })
        local tl, cl
        if not isBlank(title) then
            tl = label(inner, {
                Text = tostring(title), Font = FONT_B, TextSize = 14, TextWrapped = true, RichText = true, TextTransparency = 1,
                Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 1,
            })
            bind(tl, "TextColor3", "Accent")
        end
        if not isBlank(content) then
            cl = label(inner, {
                Text = tostring(content), TextSize = 12, TextWrapped = true, RichText = true, TextColor3 = C3(215, 215, 224),
                TextTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 2,
            })
        end
        tween(card, 0.25, { BackgroundTransparency = 0.04 })
        tween(st, 0.25, { Transparency = 0.45 })
        if tl then tween(tl, 0.25, { TextTransparency = 0 }) end
        if cl then tween(cl, 0.25, { TextTransparency = 0 }) end
        task.delay(duration, function()
            if card.Parent then
                tween(card, 0.3, { BackgroundTransparency = 1 })
                tween(st, 0.3, { Transparency = 1 })
                if tl then tween(tl, 0.3, { TextTransparency = 1 }) end
                if cl then tween(cl, 0.3, { TextTransparency = 1 }) end
                task.wait(0.32)
                if card.Parent then
                    card:Destroy()
                end
            end
        end)
    end
    function M:Notify(d)
        d = d or {}
        toast(d.Title, d.Content or d.Description, d.Duration)
    end
    local DOT = { r = C3(240, 70, 70), y = C3(255, 200, 59), g = C3(80, 228, 130) }
    function M:NotifyDot(kind, text, duration)
        local c = DOT[string.lower(tostring(kind or "g")):sub(1, 1)] or DOT.g
        toast("", tostring(text or ""), duration, c)
    end
    function M:NotifyColor(kind, d)
        d = d or {}
        local c = DOT[kind] or DOT.g
        toast(d.Text or d.Title or "", d.Description or d.Content or "", d.Duration, c)
    end

    -- themes api
    function M:GetThemes()
        local o = {}
        for k in pairs(THEMES) do
            o[k] = true
        end
        return o
    end
    function M:GetCurrentTheme()
        return T.Name
    end
    function M:SetTheme(name)
        if not THEMES[name] then
            return nil
        end
        setThemeColors(name)
        applyTheme()
        if M.OnThemeChangeFunction then
            pcall(M.OnThemeChangeFunction, name)
        end
        return THEMES[name]
    end

    -- ------------------------------------------------------------ window
    function M:CreateWindow(cfg)
        cfg = cfg or {}
        ensureGui()
        local W, H = 629, 359
        if typeof(cfg.Size) == "UDim2" then
            W, H = cfg.Size.X.Offset, cfg.Size.Y.Offset
        end
        local Win = { Title = cfg.Title, Closed = false, Destroyed = false, IsFullscreen = false, Tabs = {} }
        local registry = {}

        local Holder = new("Frame", {
            Name = "Holder", BackgroundTransparency = 1, AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0, 0.5, 0),
            Size = U2(0, 0, 0, 0), Parent = Gui,
        })
        local Main = new("Frame", {
            Name = "Main", AnchorPoint = V2(0.5, 0.5), Position = U2(0, 0, 0, 0), Size = U2(0, W, 0, H),
            BackgroundColor3 = BG, BorderSizePixel = 0, ClipsDescendants = false, Parent = Holder,
        })
        corner(Main, 8)
        local scale = new("UIScale", { Scale = 1, Parent = Main })
        local shadow = new("ImageLabel", {
            Name = "Shadow", BackgroundTransparency = 1, AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0, 0.5, 0),
            Size = U2(1, 44, 1, 44), ZIndex = 0, Image = "rbxassetid://5028857084", ImageColor3 = C3(0, 0, 0),
            ImageTransparency = 0.35, ScaleType = Enum.ScaleType.Slice, SliceCenter = Rect.new(24, 24, 276, 276), Parent = Main,
        })
        local mst = new("UIStroke", { Thickness = 1.5, Transparency = 0.1, Parent = Main })
        local grad = new("UIGradient", { Rotation = 0, Parent = mst })
        themed(Main, function()
            grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, T.Accent),
                ColorSequenceKeypoint.new(0.5, T.Dark),
                ColorSequenceKeypoint.new(1, T.Accent),
            })
        end)
        pcall(function()
            TweenService:Create(grad, TweenInfo.new(7, Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1), { Rotation = 360 }):Play()
        end)

        -- topbar
        local Top = new("Frame", { Name = "Topbar", BackgroundTransparency = 1, Size = U2(1, 0, 0, 34), Parent = Main })
        local line = new("Frame", { Position = U2(0, 0, 1, -1), Size = U2(1, 0, 0, 1), BorderSizePixel = 0, BackgroundTransparency = 0.55, Parent = Top })
        bind(line, "BackgroundColor3", "Dark")
        local logo = new("Frame", { Position = U2(0, 8, 0.5, 0), AnchorPoint = V2(0, 0.5), Size = U2(0, 22, 0, 22), BorderSizePixel = 0, Parent = Top })
        bind(logo, "BackgroundColor3", "Accent")
        corner(logo, 6)
        label(logo, { Text = "L", Font = FONT_B, TextSize = 15, TextColor3 = C3(30, 22, 4), TextXAlignment = CENTER, Size = U2(1, 0, 1, 0) })
        local titleL = label(Top, {
            Text = tostring(cfg.Title or "LeakD Hub 2.0"), Font = FONT_B, TextSize = 16, Position = U2(0, 38, 0, 0),
            Size = U2(0, 150, 1, 0),
        })
        local tg = new("UIGradient", { Parent = titleL })
        themed(titleL, function()
            tg.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, T.Dark),
                ColorSequenceKeypoint.new(0.5, T.Soft),
                ColorSequenceKeypoint.new(1, T.Dark),
            })
        end)
        tg.Offset = V2(-1, 0)
        pcall(function()
            TweenService:Create(tg, TweenInfo.new(2.6, Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1), { Offset = V2(1, 0) }):Play()
        end)
        titleL.TextColor3 = C3(255, 255, 255)
        label(Top, {
            Text = tostring(cfg.Author or ""), TextSize = 12, TextColor3 = DESC, Position = U2(0, 188, 0, 0),
            Size = U2(0, 180, 1, 0),
        })

        local function topBtn(txt, xoff, color)
            local b = new("TextButton", {
                Text = txt, Font = FONT_B, TextSize = 14, TextColor3 = color or TXT, BackgroundColor3 = PANEL, BackgroundTransparency = 0.3,
                AutoButtonColor = false, AnchorPoint = V2(1, 0.5), Position = U2(1, xoff, 0.5, 0), Size = U2(0, 26, 0, 22), Parent = Top,
            })
            corner(b, 5)
            return b
        end
        local bClose = topBtn("✕", -8, C3(255, 110, 110))
        local bMin = topBtn("—", -40)
        local bFull = topBtn("⤢", -72)

        -- dragging
        do
            local dragging, startPos, startHolder = false, nil, nil
            Top.InputBegan:Connect(function(i)
                if isPointer(i) then
                    dragging = true
                    startPos = i.Position
                    startHolder = Holder.Position
                    i.Changed:Connect(function()
                        if i.UserInputState == Enum.UserInputState.End then
                            dragging = false
                        end
                    end)
                end
            end)
            UIS.InputChanged:Connect(function(i)
                if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                    local d = i.Position - startPos
                    Holder.Position = U2(startHolder.X.Scale, startHolder.X.Offset + d.X, startHolder.Y.Scale, startHolder.Y.Offset + d.Y)
                end
            end)
        end

        -- sidebar
        local Side = new("Frame", {
            Name = "Sidebar", BackgroundColor3 = PANEL, BackgroundTransparency = 0.25, Position = U2(0, 6, 0, 40),
            Size = U2(0, 164, 1, -46), BorderSizePixel = 0, Parent = Main,
        })
        corner(Side, 6)
        stroke(Side, "Dark", 1, 0.6)
        local searchBox = new("TextBox", {
            Name = "Search", BackgroundColor3 = FIELD, Position = U2(0, 6, 0, 6), Size = U2(1, -12, 0, 26),
            Text = "", PlaceholderText = "🔍 Search function", PlaceholderColor3 = C3(120, 120, 132), TextColor3 = TXT,
            Font = FONT_M, TextSize = 12, TextXAlignment = LEFT, ClearTextOnFocus = false, BorderSizePixel = 0, Parent = Side,
        })
        corner(searchBox, 5)
        new("UIPadding", { PaddingLeft = UD(0, 8), PaddingRight = UD(0, 8), Parent = searchBox })
        local sst = stroke(searchBox, "Dark", 1, 0.55)
        local TabList = new("ScrollingFrame", {
            Name = "TabList", BackgroundTransparency = 1, Position = U2(0, 0, 0, 38), Size = U2(1, 0, 1, -42),
            CanvasSize = U2(0, 0, 0, 0), AutomaticCanvasSize = AUTO_Y, ScrollBarThickness = 3, BorderSizePixel = 0,
            ScrollingDirection = Enum.ScrollingDirection.Y, Parent = Side,
        })
        bind(TabList, "ScrollBarImageColor3", "Accent")
        new("UIListLayout", { Padding = UD(0, 4), SortOrder = ORDER, Parent = TabList })
        new("UIPadding", { PaddingLeft = UD(0, 6), PaddingRight = UD(0, 8), PaddingTop = UD(0, 2), PaddingBottom = UD(0, 6), Parent = TabList })

        local Pages = new("Frame", {
            Name = "Pages", BackgroundTransparency = 1, Position = U2(0, 176, 0, 40), Size = U2(1, -182, 1, -46),
            ClipsDescendants = true, Parent = Main,
        })

        local function newPage()
            local p = new("ScrollingFrame", {
                BackgroundTransparency = 1, Size = U2(1, 0, 1, 0), CanvasSize = U2(0, 0, 0, 0), AutomaticCanvasSize = AUTO_Y,
                ScrollBarThickness = 3, BorderSizePixel = 0, Visible = false, ScrollingDirection = Enum.ScrollingDirection.Y,
                Parent = Pages,
            })
            bind(p, "ScrollBarImageColor3", "Accent")
            new("UIListLayout", { Padding = UD(0, 5), SortOrder = ORDER, Parent = p })
            new("UIPadding", { PaddingLeft = UD(0, 2), PaddingRight = UD(0, 8), PaddingTop = UD(0, 2), PaddingBottom = UD(0, 10), Parent = p })
            return p
        end
        local ResultsPage = newPage()
        local currentTab = nil
        local function showPage(p)
            for _, t in ipairs(Win.Tabs) do
                t._page.Visible = false
            end
            ResultsPage.Visible = false
            if p then
                p.Visible = true
            end
        end

        -- tabs --------------------------------------------------------
        local tabOrder = 0
        local function refreshTabs()
            for _, t in ipairs(Win.Tabs) do
                local on = (t == currentTab)
                t._bg.BackgroundTransparency = on and 0.05 or 0.45
                t._bar.Visible = on
                t._text.TextColor3 = on and T.Accent or TXT
            end
        end
        tabRefresh = refreshTabs

        local TabMT = {}
        TabMT.__index = TabMT

        function Win:Group(title)
            tabOrder = tabOrder + 1
            local l = label(TabList, {
                Text = string.upper(tostring(title or "")), Font = FONT_B, TextSize = 11, TextColor3 = DESC,
                Size = U2(1, 0, 0, 20), LayoutOrder = tabOrder,
            })
            new("UIPadding", { PaddingLeft = UD(0, 6), PaddingTop = UD(0, 4), Parent = l })
            return l
        end

        function Win:Tab(c)
            c = c or {}
            tabOrder = tabOrder + 1
            local tab = setmetatable({ Title = tostring(c.Title or "Tab"), Name = tostring(c.Title or "Tab"), Icon = c.Icon }, TabMT)
            tab._page = newPage()
            local btn = new("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = PANEL, BackgroundTransparency = 0.45,
                Size = U2(1, 0, 0, 32), LayoutOrder = tabOrder, Parent = TabList,
            })
            corner(btn, 6)
            tab._bg = btn
            local bar = new("Frame", { Position = U2(0, 0, 0.5, 0), AnchorPoint = V2(0, 0.5), Size = U2(0, 3, 0, 18), BorderSizePixel = 0, Visible = false, Parent = btn })
            bind(bar, "BackgroundColor3", "Accent")
            corner(bar, 2)
            tab._bar = bar
            label(btn, {
                Text = ICONS[c.Icon] or "•", TextSize = 14, TextXAlignment = CENTER, Position = U2(0, 6, 0, 0), Size = U2(0, 24, 1, 0),
            })
            tab._text = label(btn, {
                Text = tab.Title, Font = FONT_B, TextSize = 13, Position = U2(0, 34, 0, 0), Size = U2(1, -38, 1, 0),
                TextTruncate = Enum.TextTruncate.AtEnd,
            })
            btn.MouseButton1Click:Connect(function()
                tab:Select()
            end)
            Win.Tabs[#Win.Tabs + 1] = tab
            if not currentTab then
                tab:Select()
            end
            return tab
        end

        function TabMT:Select()
            currentTab = self
            searchBox.Text = ""
            showPage(self._page)
            refreshTabs()
        end

        -- element rows ---------------------------------------------------
        local function register(tab, row, getTitle)
            registry[#registry + 1] = { tab = tab, row = row, title = getTitle }
        end

        local function makeRow(tab, o)
            local R = {}
            local row = new("Frame", {
                BackgroundColor3 = PANEL, BackgroundTransparency = 0.2, Size = U2(1, 0, 0, o.minH or 38), AutomaticSize = AUTO_Y,
                BorderSizePixel = 0, LayoutOrder = 0, Parent = tab._page,
            })
            corner(row, 6)
            R.stroke = stroke(row, "Dark", 1, 0.6)
            local body = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, Parent = row })
            new("UIListLayout", { SortOrder = ORDER, Parent = body })
            local info = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 1, Parent = body })
            new("UIPadding", {
                PaddingTop = UD(0, 9), PaddingBottom = UD(0, 9), PaddingLeft = UD(0, 11), PaddingRight = UD(0, o.right or 10), Parent = info,
            })
            new("UIListLayout", { Padding = UD(0, 2), SortOrder = ORDER, Parent = info })
            R.row, R.body, R.info = row, body, info
            R.titleText = tostring(o.title or "")
            R.title = label(info, {
                Text = R.titleText, Font = FONT_B, TextSize = 14, TextWrapped = true, RichText = true,
                Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 1,
            })
            R.descText = nil
            function R.setDesc(t)
                t = (t == nil) and "" or tostring(t)
                if R.descText == t then
                    return
                end
                R.descText = t
                if isBlank(t) then
                    if R.desc then
                        R.desc.Visible = false
                    end
                else
                    if not R.desc then
                        R.desc = label(info, {
                            Text = t, TextSize = 12, TextColor3 = DESC, TextWrapped = true, RichText = true,
                            Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 2,
                        })
                    end
                    R.desc.Visible = true
                    R.desc.Text = t
                end
                if R.onDesc then
                    R.onDesc()
                end
            end
            function R.setTitle(t)
                t = tostring(t or "")
                if R.titleText == t then
                    return
                end
                R.titleText = t
                R.title.Text = t
            end
            R.setDesc(o.desc)
            register(tab, row, function()
                return R.titleText
            end)
            return R
        end

        local function hoverRow(row, click)
            if UIS.TouchEnabled then
                return
            end
            click.MouseEnter:Connect(function()
                tween(row, 0.12, { BackgroundTransparency = 0.05 })
            end)
            click.MouseLeave:Connect(function()
                tween(row, 0.12, { BackgroundTransparency = 0.2 })
            end)
        end
        local function clickArea(row)
            return new("TextButton", {
                Text = "", BackgroundTransparency = 1, Size = U2(1, 0, 1, 0), ZIndex = 5, AutoButtonColor = false, Parent = row,
            })
        end

        -- Paragraph / section ---------------------------------------------
        function TabMT:Paragraph(c)
            c = c or {}
            local R = makeRow(self, { title = c.Title, desc = c.Desc, minH = 26 })
            local ul = new("Frame", { Position = U2(0, 10, 1, -1), Size = U2(1, -20, 0, 1), BorderSizePixel = 0, BackgroundTransparency = 0.45, Parent = R.row })
            bind(ul, "BackgroundColor3", "Accent")
            local function restyle()
                local header = isBlank(R.descText)
                R.row.BackgroundTransparency = header and 1 or 0.2
                R.stroke.Enabled = not header
                ul.Visible = header
                R.title.TextSize = header and 15 or 14
                if header then
                    R.title.TextColor3 = T.Accent
                else
                    R.title.TextColor3 = T.Soft
                end
            end
            R.onDesc = restyle
            themed(R.row, restyle)
            local el = { Type = "Paragraph" }
            function el:SetDesc(t) R.setDesc(t) end
            el.SetContent = el.SetDesc
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- Button --------------------------------------------------------------
        function TabMT:Button(c)
            c = c or {}
            local R = makeRow(self, { title = c.Title, desc = c.Desc, right = 40 })
            local arrow = label(R.row, {
                Text = "▶", Font = FONT_B, TextSize = 13, TextXAlignment = CENTER, AnchorPoint = V2(1, 0.5),
                Position = U2(1, -10, 0.5, 0), Size = U2(0, 22, 0, 22),
            })
            bind(arrow, "TextColor3", "Accent")
            local click = clickArea(R.row)
            hoverRow(R.row, click)
            click.MouseButton1Click:Connect(function()
                R.row.BackgroundColor3 = T.Dark
                tween(R.row, 0.25, { BackgroundColor3 = PANEL })
                safeCall(c.Callback)
            end)
            local el = { Type = "Button" }
            function el:SetDesc(t) R.setDesc(t) end
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- Toggle --------------------------------------------------------------
        function TabMT:Toggle(c)
            c = c or {}
            local R = makeRow(self, { title = c.Title, desc = c.Desc, right = 50 })
            local box = new("Frame", {
                AnchorPoint = V2(1, 0.5), Position = U2(1, -12, 0.5, 0), Size = U2(0, 24, 0, 24), BackgroundColor3 = FIELD,
                BorderSizePixel = 0, Parent = R.row,
            })
            corner(box, 6)
            local bst = new("UIStroke", { Thickness = 1.6, Parent = box })
            local fill = new("Frame", {
                AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0, 0.5, 0), Size = U2(0, 0, 0, 0), BorderSizePixel = 0, Parent = box,
            })
            corner(fill, 4)
            local state = c.Value == true
            local el = { Type = "Toggle", Value = state }
            local function render(anim)
                local sz = state and U2(0, 14, 0, 14) or U2(0, 0, 0, 0)
                if anim then
                    tween(fill, 0.15, { Size = sz })
                else
                    fill.Size = sz
                end
                fill.BackgroundColor3 = T.Accent
                bst.Color = state and T.Accent or IDLE
            end
            themed(R.row, function() render(false) end)
            local click = clickArea(R.row)
            hoverRow(R.row, click)
            click.MouseButton1Click:Connect(function()
                state = not state
                el.Value = state
                render(true)
                safeCall(c.Callback, state)
            end)
            function el:Set(v, fire)
                v = v and true or false
                state = v
                el.Value = v
                render(true)
                if fire == true then
                    safeCall(c.Callback, v)
                end
            end
            function el:Get() return state end
            function el:SetDesc(t) R.setDesc(t) end
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- Slider --------------------------------------------------------------
        function TabMT:Slider(c)
            c = c or {}
            local vcfg = c.Value or {}
            local min, max = tonumber(vcfg.Min) or 0, tonumber(vcfg.Max) or 100
            if max <= min then
                max = min + 1
            end
            local step = tonumber(c.Step) or 1
            if step <= 0 then
                step = 1
            end
            local R = makeRow(self, { title = c.Title, desc = c.Desc })
            local ctrl = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 34), LayoutOrder = 2, Parent = R.body })
            local hit = new("TextButton", {
                Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Position = U2(0, 10, 0, 0), Size = U2(1, -86, 1, 0), Parent = ctrl,
            })
            local track = new("Frame", {
                AnchorPoint = V2(0, 0.5), Position = U2(0, 10, 0.5, -3), Size = U2(1, -86, 0, 6), BackgroundColor3 = C3(48, 48, 60), BorderSizePixel = 0, Parent = ctrl,
            })
            corner(track, 3)
            local fill = new("Frame", { Size = U2(0, 0, 1, 0), BorderSizePixel = 0, Parent = track })
            bind(fill, "BackgroundColor3", "Accent")
            corner(fill, 3)
            local knob = new("Frame", {
                AnchorPoint = V2(0.5, 0.5), Position = U2(0, 0, 0.5, 0), Size = U2(0, 14, 0, 14), BorderSizePixel = 0, Parent = track,
            })
            bind(knob, "BackgroundColor3", "Soft")
            corner(knob, 7)
            local vbox = new("TextBox", {
                AnchorPoint = V2(1, 0.5), Position = U2(1, -10, 0.5, -3), Size = U2(0, 58, 0, 24), BackgroundColor3 = FIELD, Text = "",
                TextColor3 = TXT, Font = FONT_B, TextSize = 12, ClearTextOnFocus = false, BorderSizePixel = 0, Parent = ctrl,
            })
            corner(vbox, 5)
            stroke(vbox, "Dark", 1, 0.5)
            local decimals = 0
            if step < 1 then
                local s = string.format("%.6f", step):gsub("0+$", "")
                decimals = #(s:match("%.(%d*)$") or "")
            end
            local function round(v)
                v = math.floor((v - min) / step + 0.5) * step + min
                v = math.clamp(v, min, max)
                return tonumber(string.format("%." .. decimals .. "f", v))
            end
            local value = round(tonumber(vcfg.Default) or min)
            local el = { Type = "Slider", Value = value }
            local function draw()
                local r = (value - min) / (max - min)
                fill.Size = U2(r, 0, 1, 0)
                knob.Position = U2(r, 0, 0.5, 0)
                vbox.Text = (decimals > 0) and string.format("%." .. decimals .. "f", value) or tostring(math.floor(value + 0.5))
            end
            draw()
            local function setValue(v, fire)
                v = round(v)
                if v == value then
                    draw()
                    return
                end
                value = v
                el.Value = v
                draw()
                if fire then
                    safeCall(c.Callback, v)
                end
            end
            local dragging = false
            local function fromX(x)
                local w = track.AbsoluteSize.X
                if w <= 0 then
                    return
                end
                local r = math.clamp((x - track.AbsolutePosition.X) / w, 0, 1)
                setValue(min + r * (max - min), true)
            end
            hit.InputBegan:Connect(function(i)
                if isPointer(i) then
                    dragging = true
                    self._page.ScrollingEnabled = false
                    fromX(i.Position.X)
                    i.Changed:Connect(function()
                        if i.UserInputState == Enum.UserInputState.End then
                            dragging = false
                            self._page.ScrollingEnabled = true
                        end
                    end)
                end
            end)
            UIS.InputChanged:Connect(function(i)
                if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                    fromX(i.Position.X)
                end
            end)
            vbox.FocusLost:Connect(function()
                local n = tonumber(vbox.Text)
                if n then
                    setValue(n, true)
                end
                draw()
            end)
            function el:Set(v)
                v = tonumber(v)
                if v then
                    setValue(v, true)
                end
            end
            function el:SetValue(v) el:Set(v) end
            function el:Get() return value end
            function el:SetDesc(t) R.setDesc(t) end
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- Input ---------------------------------------------------------------
        function TabMT:Input(c)
            c = c or {}
            local R = makeRow(self, { title = c.Title, desc = c.Desc })
            local ctrl = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 38), LayoutOrder = 2, Parent = R.body })
            local box = new("TextBox", {
                Position = U2(0, 10, 0, 0), Size = U2(1, -20, 0, 30), BackgroundColor3 = FIELD, Text = tostring(c.Value or ""),
                PlaceholderText = tostring(c.Placeholder or ""), PlaceholderColor3 = C3(120, 120, 132), TextColor3 = TXT, Font = FONT_M,
                TextSize = 13, TextXAlignment = LEFT, ClearTextOnFocus = false, BorderSizePixel = 0, Parent = ctrl,
            })
            corner(box, 5)
            new("UIPadding", { PaddingLeft = UD(0, 8), PaddingRight = UD(0, 8), Parent = box })
            local st = stroke(box, "Dark", 1, 0.5)
            box.Focused:Connect(function() st.Transparency = 0 end)
            local el = { Type = "Input", Value = box.Text }
            box.FocusLost:Connect(function()
                st.Transparency = 0.5
                el.Value = box.Text
                safeCall(c.Callback, box.Text)
            end)
            function el:Set(v)
                box.Text = tostring(v or "")
                el.Value = box.Text
                safeCall(c.Callback, box.Text)
            end
            function el:SetPlaceholder(t) box.PlaceholderText = tostring(t or "") end
            function el:SetDesc(t) R.setDesc(t) end
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- Dropdown ------------------------------------------------------------
        function TabMT:Dropdown(c)
            c = c or {}
            local multi = c.Multi == true
            local values = c.Values or {}
            local R = makeRow(self, { title = c.Title, desc = c.Desc })
            local ctrl = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 2, Parent = R.body })
            new("UIPadding", { PaddingLeft = UD(0, 10), PaddingRight = UD(0, 10), PaddingBottom = UD(0, 9), Parent = ctrl })
            new("UIListLayout", { Padding = UD(0, 4), SortOrder = ORDER, Parent = ctrl })
            local selBtn = new("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = FIELD, Size = U2(1, 0, 0, 30), LayoutOrder = 1, BorderSizePixel = 0, Parent = ctrl,
            })
            corner(selBtn, 5)
            stroke(selBtn, "Dark", 1, 0.5)
            local selLbl = label(selBtn, { Text = "", Position = U2(0, 9, 0, 0), Size = U2(1, -34, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd })
            local arrow = label(selBtn, { Text = "▾", Font = FONT_B, TextSize = 14, TextXAlignment = CENTER, Position = U2(1, -24, 0, 0), Size = U2(0, 20, 1, 0) })
            bind(arrow, "TextColor3", "Accent")
            local listFrame = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 2, Visible = false, Parent = ctrl })
            new("UIListLayout", { Padding = UD(0, 4), SortOrder = ORDER, Parent = listFrame })
            local fbox = new("TextBox", {
                Size = U2(1, 0, 0, 26), BackgroundColor3 = FIELD, Text = "", PlaceholderText = "Search...", PlaceholderColor3 = C3(120, 120, 132),
                TextColor3 = TXT, Font = FONT_M, TextSize = 12, TextXAlignment = LEFT, ClearTextOnFocus = false, LayoutOrder = 1, BorderSizePixel = 0, Parent = listFrame,
            })
            corner(fbox, 5)
            new("UIPadding", { PaddingLeft = UD(0, 8), Parent = fbox })
            local scroll = new("ScrollingFrame", {
                BackgroundTransparency = 1, Size = U2(1, 0, 0, 28), CanvasSize = U2(0, 0, 0, 0), AutomaticCanvasSize = AUTO_Y,
                ScrollBarThickness = 3, BorderSizePixel = 0, LayoutOrder = 2, ScrollingDirection = Enum.ScrollingDirection.Y, Parent = listFrame,
            })
            bind(scroll, "ScrollBarImageColor3", "Accent")
            new("UIListLayout", { Padding = UD(0, 2), SortOrder = ORDER, Parent = scroll })

            local current = nil
            local chosen = {}
            if multi then
                if type(c.Value) == "table" then
                    for _, v in ipairs(c.Value) do
                        chosen[v] = true
                    end
                end
            else
                current = c.Value
            end
            local el = { Type = "Dropdown", Value = current }
            local function chosenList()
                local out = {}
                for _, v in ipairs(values) do
                    if chosen[v] then
                        out[#out + 1] = v
                    end
                end
                return out
            end
            local function refreshLabel()
                if multi then
                    local l = chosenList()
                    selLbl.Text = (#l > 0) and table.concat(l, ", ") or "None"
                    el.Value = l
                else
                    selLbl.Text = (current ~= nil) and tostring(current) or "Select..."
                    el.Value = current
                end
                selLbl.TextColor3 = ((multi and next(chosen) ~= nil) or (not multi and current ~= nil)) and TXT or DESC
            end
            local open = false
            local function setOpen(v)
                open = v
                listFrame.Visible = v
                arrow.Text = v and "▴" or "▾"
            end
            local function pick(v)
                if multi then
                    if chosen[v] then
                        chosen[v] = nil
                    else
                        chosen[v] = true
                    end
                    refreshLabel()
                    safeCall(c.Callback, chosenList())
                else
                    current = v
                    refreshLabel()
                    setOpen(false)
                    safeCall(c.Callback, v)
                end
            end
            local build
            local function isSel(v)
                if multi then
                    return chosen[v] == true
                end
                return current == v
            end
            build = function()
                for _, ch in ipairs(scroll:GetChildren()) do
                    if ch:IsA("TextButton") then
                        ch:Destroy()
                    end
                end
                local q = string.lower(fbox.Text or "")
                local shown = 0
                for idx, v in ipairs(values) do
                    local name = tostring(v)
                    if q == "" or string.find(string.lower(name), q, 1, true) then
                        shown = shown + 1
                        local b = new("TextButton", {
                            Text = "", AutoButtonColor = false, Size = U2(1, 0, 0, 26), LayoutOrder = idx, BackgroundColor3 = PANEL,
                            BackgroundTransparency = 0.3, BorderSizePixel = 0, Parent = scroll,
                        })
                        corner(b, 5)
                        local tl = label(b, { Text = name, Position = U2(0, 9, 0, 0), Size = U2(1, -34, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd })
                        local ck = label(b, { Text = "✓", Font = FONT_B, TextSize = 14, TextXAlignment = CENTER, Position = U2(1, -24, 0, 0), Size = U2(0, 20, 1, 0) })
                        local on = isSel(v)
                        ck.Visible = on
                        ck.TextColor3 = T.Accent
                        tl.TextColor3 = on and T.Accent or TXT
                        b.MouseButton1Click:Connect(function()
                            pick(v)
                            if multi then
                                local on2 = isSel(v)
                                ck.Visible = on2
                                tl.TextColor3 = on2 and T.Accent or TXT
                            else
                                build()
                            end
                        end)
                    end
                end
                fbox.Visible = #values > 8
                scroll.Size = U2(1, 0, 0, math.clamp(shown * 28, 28, 168))
            end
            fbox:GetPropertyChangedSignal("Text"):Connect(build)
            selBtn.MouseButton1Click:Connect(function()
                setOpen(not open)
                if open then
                    build()
                end
            end)
            refreshLabel()

            function el:Select(v)
                if multi then
                    chosen = {}
                    if type(v) == "table" then
                        for _, x in ipairs(v) do
                            chosen[x] = true
                        end
                    elseif v ~= nil then
                        chosen[v] = true
                    end
                    refreshLabel()
                    safeCall(c.Callback, chosenList())
                else
                    current = v
                    refreshLabel()
                    safeCall(c.Callback, v)
                end
                if open then
                    build()
                end
            end
            function el:Refresh(list)
                values = list or {}
                if not multi and current ~= nil and not table.find(values, current) then
                    current = nil
                end
                refreshLabel()
                if open then
                    build()
                end
            end
            function el:SetDesc(t) R.setDesc(t) end
            function el:SetTitle(t) R.setTitle(t) end
            function el:Destroy() R.row:Destroy() end
            return el
        end

        -- search ----------------------------------------------------------------
        local function flash(row)
            pcall(function()
                local st = row:FindFirstChildOfClass("UIStroke")
                if st then
                    st.Transparency = 0
                    st.Thickness = 2
                    task.delay(1.4, function()
                        st.Transparency = 0.6
                        st.Thickness = 1
                    end)
                end
            end)
        end
        local function jumpTo(tab, row)
            tab:Select()
            task.defer(function()
                task.wait(0.05)
                pcall(function()
                    local p = tab._page
                    local y = row.AbsolutePosition.Y - p.AbsolutePosition.Y + p.CanvasPosition.Y - 6
                    p.CanvasPosition = V2(0, math.max(0, y))
                end)
                flash(row)
            end)
        end
        local function runSearch()
            local q = string.lower(searchBox.Text or "")
            for _, ch in ipairs(ResultsPage:GetChildren()) do
                if ch:IsA("TextButton") or ch:IsA("TextLabel") then
                    ch:Destroy()
                end
            end
            if q == "" then
                showPage(currentTab and currentTab._page or nil)
                return
            end
            showPage(ResultsPage)
            local n = 0
            for _, e in ipairs(registry) do
                if n < 40 and e.row.Parent ~= nil then
                    local t = plain(e.title())
                    if t ~= "" and string.find(string.lower(t), q, 1, true) then
                        n = n + 1
                        local b = new("TextButton", {
                            Text = "", AutoButtonColor = false, BackgroundColor3 = PANEL, BackgroundTransparency = 0.2, Size = U2(1, 0, 0, 40),
                            LayoutOrder = n, BorderSizePixel = 0, Parent = ResultsPage,
                        })
                        corner(b, 6)
                        stroke(b, "Dark", 1, 0.6)
                        local tl = label(b, { Text = e.tab.Title, TextSize = 11, Position = U2(0, 10, 0, 4), Size = U2(1, -20, 0, 14) })
                        bind(tl, "TextColor3", "Accent")
                        label(b, { Text = t, Font = FONT_B, TextSize = 13, Position = U2(0, 10, 0, 19), Size = U2(1, -20, 0, 18), TextTruncate = Enum.TextTruncate.AtEnd })
                        b.MouseButton1Click:Connect(function()
                            jumpTo(e.tab, e.row)
                        end)
                    end
                end
            end
            if n == 0 then
                label(ResultsPage, { Text = "No results", TextColor3 = DESC, Size = U2(1, 0, 0, 30), TextXAlignment = CENTER })
            end
        end
        searchBox:GetPropertyChangedSignal("Text"):Connect(runSearch)

        -- floating toggle button -------------------------------------------------
        local fab = new("TextButton", {
            Name = "LeakDToggle", Text = "L", Font = FONT_B, TextSize = 22, TextColor3 = C3(30, 22, 4), AutoButtonColor = false,
            AnchorPoint = V2(0, 1), Position = U2(0, 14, 1, -90), Size = U2(0, 46, 0, 46), BorderSizePixel = 0, ZIndex = 60, Parent = Gui,
        })
        bind(fab, "BackgroundColor3", "Accent")
        corner(fab, 23)
        local fst = new("UIStroke", { Thickness = 2, Transparency = 0.2, Parent = fab })
        bind(fst, "Color", "Soft")
        do
            local down, moved, sp, sPos = false, false, nil, nil
            fab.InputBegan:Connect(function(i)
                if isPointer(i) then
                    down, moved, sp, sPos = true, false, i.Position, fab.Position
                    i.Changed:Connect(function()
                        if i.UserInputState == Enum.UserInputState.End then
                            down = false
                            if not moved then
                                Win:Toggle()
                            end
                        end
                    end)
                end
            end)
            UIS.InputChanged:Connect(function(i)
                if down and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                    local d = i.Position - sp
                    if d.Magnitude > 8 then
                        moved = true
                    end
                    if moved then
                        fab.Position = U2(sPos.X.Scale, sPos.X.Offset + d.X, sPos.Y.Scale, sPos.Y.Offset + d.Y)
                    end
                end
            end)
        end

        -- window control -----------------------------------------------------------
        local userScale = nil
        local function fit()
            if userScale then
                return
            end
            local cam = workspace.CurrentCamera
            if not cam then
                return
            end
            local vp = cam.ViewportSize
            if vp.X < 50 or vp.Y < 50 then
                return
            end
            local w, h = Main.Size.X.Offset, Main.Size.Y.Offset
            if Win.IsFullscreen then
                scale.Scale = 1
                return
            end
            scale.Scale = math.clamp(math.min(vp.X * 0.92 / w, vp.Y * 0.82 / h), 0.3, 1)
        end
        pcall(function()
            local cam = workspace.CurrentCamera
            cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)
        end)
        fit()
        task.delay(1, fit)

        function Win:SetUIScale(k)
            k = tonumber(k)
            if k and k > 0 then
                userScale = k
                scale.Scale = k
            end
        end
        function Win:GetUIScale()
            return scale.Scale
        end
        function Win:Open()
            Win.Closed = false
            Holder.Visible = true
        end
        function Win:Close()
            Win.Closed = true
            Holder.Visible = false
        end
        function Win:Toggle()
            if Win.Closed then
                Win:Open()
            else
                Win:Close()
            end
        end
        function Win:ToggleFullscreen()
            Win.IsFullscreen = not Win.IsFullscreen
            if Win.IsFullscreen then
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or V2(1280, 720)
                Holder.Position = U2(0.5, 0, 0.5, 0)
                scale.Scale = 1
                Main.Size = U2(0, math.floor(vp.X - 24), 0, math.floor(vp.Y - 24))
            else
                Main.Size = U2(0, W, 0, H)
                fit()
            end
        end
        function Win:Destroy()
            Win.Destroyed = true
            pcall(function() Holder:Destroy() end)
            pcall(function() fab:Destroy() end)
        end
        function Win:Dialog(d)
            d = d or {}
            local overlay = new("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = C3(0, 0, 0), BackgroundTransparency = 0.4, Size = U2(1, 0, 1, 0), ZIndex = 50, Parent = Main,
            })
            corner(overlay, 8)
            local card = new("Frame", {
                AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0, 0.5, 0), Size = U2(0, 330, 0, 0), AutomaticSize = AUTO_Y,
                BackgroundColor3 = C3(22, 22, 29), BorderSizePixel = 0, Parent = overlay,
            })
            corner(card, 8)
            stroke(card, "Accent", 1.2, 0.2)
            new("UIPadding", { PaddingTop = UD(0, 14), PaddingBottom = UD(0, 14), PaddingLeft = UD(0, 14), PaddingRight = UD(0, 14), Parent = card })
            new("UIListLayout", { Padding = UD(0, 8), SortOrder = ORDER, Parent = card })
            local tl = label(card, { Text = tostring(d.Title or ""), Font = FONT_B, TextSize = 16, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 1, TextWrapped = true })
            bind(tl, "TextColor3", "Accent")
            label(card, { Text = tostring(d.Content or ""), TextSize = 13, TextColor3 = DESC, Size = U2(1, 0, 0, 0), AutomaticSize = AUTO_Y, LayoutOrder = 2, TextWrapped = true })
            local brow = new("Frame", { BackgroundTransparency = 1, Size = U2(1, 0, 0, 30), LayoutOrder = 3, Parent = card })
            new("UIListLayout", {
