    local Rec = {}
    Rec.__index = Rec
    function Rec:SetDesc(t)
        t = (t == nil) and "" or tostring(t)
        if self._desc == t then
            return
        end
        self._desc = t
        local e = self.Element
        if e and e.SetDesc then
            pcall(e.SetDesc, e, t)
        end
    end
    Rec.SetContent = Rec.SetDesc
    function Rec:SetTitle(t)
        t = tostring(t or "")
        if self._title == t then
            return
        end
        self._title = t
        local e = self.Element
        if e and e.SetTitle then
            pcall(e.SetTitle, e, t)
        end
    end
    function Rec:SetValue(v)
        self.Value = v
        local e = self.Element
        if not e then
            return
        end
        pcall(function()
            if self.Type == "Toggle" then
                e:Set(v, true)
            elseif self.Type == "Dropdown" then
                e:Select(v)
            else
                e:Set(v)
            end
        end)
    end
    function Rec:SetValues(list)
        local e = self.Element
        if self.Type == "Dropdown" and e and e.Refresh then
            pcall(e.Refresh, e, list)
        end
    end
    function Rec:OnChanged(fn)
        self._onChanged = fn
    end
    function Rec:Destroy()
        local e = self.Element
        if e and e.Destroy then
            pcall(e.Destroy, e)
        end
    end
    local function newRec(id, kind, value)
        local rec = setmetatable({ Id = id, Type = kind, Value = value, _fired = false }, Rec)
        if id then
            Options[id] = rec
        end
        return rec
    end
    local function initFire(rec, cb, v)
        if not cb or v == nil then
            return
        end
        task.delay(0.15, function()
            if not rec._fired then
                task.spawn(pcall, cb, v)
            end
        end)
    end
    local function mkCallback(rec, cb)
        return function(v)
            rec._fired = true
            rec.Value = v
            rec._fires = (rec._fires or 0) + 1
            if rec._onChanged then
                task.spawn(pcall, rec._onChanged, v)
            end
            if cb then
                return cb(v)
            end
        end
    end
