          return nil
        end
      end
    end
        local rec = newRec(id, "Toggle", c.Default == true or c.Value == true)
        rec.TabTitle = tabTitle(tab)
        rec.Title, rec._cb = tostring(c.Title or id or "Toggle"), c.Callback
        local cb = c.Callback
        rec.Element = tab:Toggle({
            Title = tostring(c.Title or id or "Toggle"),
            Desc = descOf(c),
            Value = rec.Value,
            Callback = mkCallback(rec, cb),
