          return nil
        end
      end
    end
        local min, max = c.Min or 0, c.Max or 100
        local def = c.Default or c.Value or min
        local step = 1
        if type(c.Rounding) == "number" and c.Rounding > 0 then
            step = 10 ^ (-c.Rounding)
        end
        local rec = newRec(id, "Slider", def)
        rec.TabTitle = tabTitle(tab)
        rec.Title, rec.Min, rec.Max, rec._cb = tostring(c.Title or id or "Slider"), min, max, c.Callback
        local cb = c.Callback
        rec.Element = tab:Slider({
            Title = tostring(c.Title or id or "Slider"),
            Desc = descOf(c),
            Step = step,
            Value = { Min = min, Max = max, Default = def },
            Callback = mkCallback(rec, function(v)
                v = tonumber(v) or v
                rec.Value = v
                if cb then
                    return cb(v)
                end
            end),
        })
        initFire(rec, function(v)
            if cb then
                return cb(v)
            end
        end, def)
        return rec
    end
    function UIX.Dropdown(tab, id, c)
        c = c or {}
    do local _fxg = _G.FARMX
      if not (_fxg and _fxg.Enable and _fxg.Enable.UIXGuard == false) then
        if tab == UIX or type(id) == "table" then
