;(function()
    if _G.QM_FpsBoost == false then
        return
    end
    local Lighting = game:GetService("Lighting")
    local function lite(v)
        local cn = v.ClassName
        if cn == "Trail" or cn == "Beam" or cn == "Explosion" or cn == "SurfaceAppearance" then
            v:Destroy()
        elseif cn == "ParticleEmitter" then
            v.Enabled = false
            v.LightEmission = 0
            v.Rate = 0
            v.Lifetime = NumberRange.new(0.05)
        elseif cn == "Fire" or cn == "Smoke" or cn == "Sparkles" or cn == "PointLight" or cn == "SpotLight" or cn == "SurfaceLight" then
            v.Enabled = false
        elseif cn == "Decal" or cn == "Texture" then
            v.Transparency = 1
        elseif v:IsA("BasePart") then
            local nm = v.Name
            if nm ~= "Head" and nm ~= "HumanoidRootPart" then
                v.Material = Enum.Material.SmoothPlastic
                v.CastShadow = false
                v.Reflectance = 0
            end
        end
    end
    local function lighting()
        pcall(function()
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 1e10
            Lighting.Brightness = 1
            Lighting.ClockTime = 14
            Lighting.EnvironmentDiffuseScale = 0
            Lighting.EnvironmentSpecularScale = 0
            Lighting.OutdoorAmbient = Color3.fromRGB(110, 110, 110)
        end)
        pcall(function() Lighting.ShadowSoftness = 0 end)
        for _, v in ipairs(Lighting:GetChildren()) do
            pcall(function()
                if v:IsA("PostEffect") then
                    v.Enabled = false
                elseif v:IsA("Atmosphere") then
                    v.Density = 0
                end
            end)
        end
        pcall(function()
            local t = workspace:FindFirstChildOfClass("Terrain")
            if t then
                t.WaterWaveSize = 0
                t.WaterWaveSpeed = 0
                t.WaterReflectance = 0
                t.WaterTransparency = 0.9
            end
        end)
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        pcall(function() settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04 end)
    end
    local function run()
        task.spawn(function()
            lighting()
            local list = workspace:GetDescendants()
            for i = 1, #list do
                pcall(lite, list[i])
                if i % 500 == 0 then
                    task.wait()
                end
            end
            list = nil
            _G.QM_FpsBoostDone = os.clock()
            local FXc = _G.FARMX
            if FXc and FXc.Clean then
                pcall(FXc.Clean, false)
            end
        end)
    end
    _G.QM_FpsBoostRun = run
    run()
    if _G.QM_FpsConn then
        pcall(function() _G.QM_FpsConn:Disconnect() end)
    end
    _G.QM_FpsConn = workspace.DescendantAdded:Connect(function(v)
        pcall(lite, v)
    end)
end)()
