end
Attack.Kill = function(model, Succes)
    if not model then return end
    if not model.Parent then return end
    if not model:FindFirstChild("HumanoidRootPart") or not model:FindFirstChildOfClass("Humanoid") then return end
    if not Attack.Alive(model) then return end
    if not model:GetAttribute("Locked") then
        model:SetAttribute("Locked", model.HumanoidRootPart.CFrame)
    end
    local PosMon = model:GetAttribute("Locked").Position
    local targetName = model.Name
    local BoneMobs = {["Reborn Skeleton"]=true,["Living Zombie"]=true,["Demonic Soul"]=true,["Possessed Mummy"]=true,["Posessed Mummy"]=true}
    local isBone = BoneMobs[targetName] == true
    local startFarm = _G.ActiveFarm
    local fx = _G.FARMX
    local ownedTarget = nil
    local _ep = fx and fx.Epoch
    local stopOn = fx and fx.Enable.KillStopOnSwitch
    local startOwner = stopOn and fx.FH and fx.FH.Owner or nil
    while _G.SelectWeapon and model.Parent and Attack.Alive(model) do
        if fx and fx.On and fx.Enable.HookE and _ep ~= fx.Epoch then break end
        if stopOn then
            if startFarm ~= nil and _G.ActiveFarm ~= startFarm then break end
            if startOwner ~= nil and fx.On and fx.Enable.EnableHandler and fx.FH.Owner ~= startOwner then break end
        end
        if targetName == "Cake Prince" and fx and fx.Enable.KatakuriDodge and fx.Enable.KatakuriDodgeV3 and fx.IsKatakuriDangerV3 and fx.IsKatakuriDangerV3() then break end
        if not plr.Character or not plr.Character:FindFirstChild("HumanoidRootPart") or not plr.Character:FindFirstChildOfClass("Humanoid") then
            task.wait(0.3)
            break
        end
        if not Attack.Alive(plr.Character) then
            task.wait(0.5)
            break
        end
        if isBone then
            local otherOwner = fx and fx.Enable.BoneOther and Succes == true and not _G.AutoFarm_Bone
                and (_G.AutoKillMob == true or _G.AutoMaterial == true or (getgenv and getgenv().AutoMaterial == true))
            if not _G.AutoFarm_Bone and not otherOwner then break end
            if _G.ActiveFarm and _G.ActiveFarm ~= "Bone" and not otherOwner then break end
        else
            if _G.ActiveFarm == "Bone" and not isBone then break end
            if _G.ActiveFarm and _G.ActiveFarm ~= "Bone" then
                if _G.ActiveFarm == "Level" and not _G.Level then break end
                if _G.ActiveFarm == "Near" and not _G.AutoFarmNear then break end
                if _G.ActiveFarm == "Island" and not _G.AutoFarmIsland then break end
            end
            if type(Succes) == "function" then
            local guardOk, guardAllowed = pcall(Succes)
            if not guardOk or guardAllowed ~= true then break end
        elseif type(Succes) == "boolean" and not Succes then
            break
        end
        end
        local current = nil
        local minDist = math.huge
        for _, e in ipairs(workspace.Enemies:GetChildren()) do
            if e.Name == targetName and Attack.Alive(e) and e:FindFirstChild("HumanoidRootPart") then
                local d = (e.HumanoidRootPart.Position - PosMon).Magnitude
                if d <= 450 and d < minDist then
                    minDist = d
                    current = e
                end
            end
        end
        if not current then break end
        if fx then
            fx.AttackingMob = current
            ownedTarget = current
        end
        pcall(function() BringEnemy(current) end)
        EquipWeapon(_G.SelectWeapon)
        local offset = GetFarmOffset()
        pcall(function() _tp(GetSpinCFrame(current.HumanoidRootPart, offset)) end)
        task.wait(_G.Seriality and 0.01 or (_G.QF_AttackDelay or 0.01))
    end
    -- Clear only the target this invocation last owned; never erase another loop's target.
    if fx and ownedTarget and fx.AttackingMob == ownedTarget then
        fx.AttackingMob = nil
    end
end
