function Convert_CFrame(x)
    if not x then return end
    if typeof(x) == "Vector3" then
        return CFrame.new(x)
    elseif typeof(x) == "CFrame" then
        return x
    elseif typeof(x) == "Model" then
        return x:GetPivot()
    elseif x.CFrame then
        return x.CFrame
    end
    return nil
end
function GetDistance(POS_1, POS_2, NO_Y)
    if POS_1 == nil then return 9e9 end
    local Character = LocalPlayer.Character
    if not Character then return 9e9 end
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Humanoid or Humanoid.Health <= 0 then
        return 9e9
    end
    if POS_2 == nil then
        POS_2 = Character:FindFirstChild("HumanoidRootPart")
        if not POS_2 then return 9e9 end
    end
    local pos1 = Convert_CFrame(POS_1)
    local pos2 = Convert_CFrame(POS_2)
    if NO_Y then
        return (Vector3.new(pos1.X, 0, pos1.Z) - Vector3.new(pos2.X, 0, pos2.Z)).Magnitude
    else
        return (pos1.Position - pos2.Position).Magnitude
    end
end
function InArea(POS)
    local WorldOrigin = workspace:FindFirstChild("_WorldOrigin")
    if not WorldOrigin then return {Name = ""} end
    local pos = Convert_CFrame(POS)
    for i,v in next, WorldOrigin.Locations:GetChildren() do
        if v:FindFirstChild("Mesh") and (pos.Position - v.Position).Magnitude <= v.Mesh.Scale.X then
            return v
        end
    end
    return {Name = ""}
end
function GetSpawnPoint(x)
    local Spawns = workspace:FindFirstChild("_WorldOrigin")
        and workspace._WorldOrigin:FindFirstChild("PlayerSpawns")
        and workspace._WorldOrigin.PlayerSpawns:FindFirstChild("Pirates")
    if not Spawns then return end
    for i,v in next, Spawns:GetChildren() do
        if v:FindFirstChild("Part") and (v.Part.Position - x.Position).Magnitude <= 2500 then
            return v
        end
    end
end
function totopofgreattree()
    if getdis(CFrame.new(28310.0234, 14895.1123, 109.456741)) > 1500 then
        ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", Vector3.new(28310.0234, 14895.1123, 109.456741))
        wait(0.3)
    end
    local targetCF = CFrame.new(28607.5352, 14896.5449, 106.011726)
    _tp(targetCF)
    do local _qmT = os.clock()
    repeat
        wait()
    until getdis(targetCF) <= 5 or os.clock() - _qmT > 15
    if _G.FARMX and _G.FARMX.Log and os.clock() - _qmT > 15 then _G.FARMX.Log("repeat-timeout", "dòng cũ 1481") end end
    wait(0.5)
    for i = 1, 4 do
        ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "TeleportBack")
    end
end
function requestentrance(pos)
    local tb = {}
    local targetPos = pos
    if typeof(pos) == "CFrame" then
        targetPos = pos.Position
    end
    if sea1 then
        tb = {
            ["Sky3"] = Vector3.new(-7894, 5547, -380),
            ["Sky3Exit"] = Vector3.new(-4607, 874, -1667),
            ["UnderWater"] = Vector3.new(61163, 11, 1819),
            ["Underwater City"] = Vector3.new(61165.19140625, 0.18704631924629211, 1897.379150390625),
            ["Pirate Village"] = Vector3.new(-1242.4625244140625, 4.787059783935547, 3901.282958984375),
            ["UnderwaterExit"] = Vector3.new(4050, -1, -1814)
        }
    elseif sea2 then
        tb = {
            ["Swan Mansion"] = Vector3.new(-390, 332, 673),
            ["Swan Room"] = Vector3.new(2285, 15, 905),
            ["Cursed Ship"] = Vector3.new(923, 126, 32852),
            ["Zombie Island"] = Vector3.new(-6509, 83, -133)
        }
    else
        tb = {
            ["Hydra Island"] = Vector3.new(5657.88623046875, 1013.0790405273438, -335.4996337890625),
            ["Mansion"] = Vector3.new(-12462, 375, -7552),
            ["Castle"] = Vector3.new(-5036, 315, -3179),
            ["Temple of Time"] = Vector3.new(28286, 14897, 103),
            ["Greate Tree"] = Vector3.new(3024.1709, 2280.69434, -7325.12793)
        }
        if not checkinventory("Valkyrie Helm") then
            return
        end
    end
    local x, y = nil, math.huge
    for i, v in pairs(tb) do
        local distance = (typeof(v) == "Vector3" and (v - targetPos).Magnitude) or (v.Position - targetPos).Magnitude
        if distance < y then
            y = distance
            x = v
        end
    end
    if x and y and y < getdis(pos) then
        pcall(function ()
            if _G.TweenCache then
                _G.TweenCache:Cancel()
            end
        end)
        if typeof(x) == "Vector3"
            and x.X == 3024.1709 and x.Y == 2280.69434 and x.Z == -7325.12793
            and ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Check") >= 2 then
            totopofgreattree()
            wait(1)
        elseif y < getdis(pos) then
            local requestPos = typeof(x) == "Vector3" and x or x.Position
            ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", requestPos)
            wait(1)
        end
    end
end
if not checkinventory then
    function checkinventory(v)
        if v then
            local _inv = replicated.Remotes.CommF_:InvokeServer("getInventory")
            if type(_inv) ~= "table" then return false end
            for i, vl in pairs(_inv) do
                if vl.Name == v then
                    return true
                end
            end
        end
        return false
    end
end
if not getdis then
    function getdis(a, b)
        b = b or plr.Character.HumanoidRootPart.CFrame
        local _a = CFrame.new(a.X, b.Y, a.Z)
        local _b = CFrame.new(b.X, b.Y, b.Z)
        return (_a.Position - _b.Position).Magnitude
    end
end
_tp = function(target)
  local character = plr.Character
  if not character or not character:FindFirstChild("HumanoidRootPart") then return end
  local fxAtStart = _G.FARMX
  -- BodyVelocity/BodyGyro own the character only during the short dodge impulse.
  if fxAtStart and fxAtStart.MobDodge and fxAtStart.MobDodge.bodyActive then return end
  do
    local fxn = _G.FARMX
    if fxn and fxn.Nav and fxn.Nav.Auto then pcall(fxn.Nav.Auto, target) end
  end
  do
      local fxS = _G.FARMX
      if fxS and fxS.Enable and fxS.Enable.SafeModeOwner and fxS.SafeMode and fxS.SafeMode.state == "PANIC_UP" and not fxS.SafeMode.own then return end
  end
  do
      local fxD = _G.FARMX
      if fxD and fxD.Enable and typeof(target) == "CFrame" then
          local dodgeOffset = 0
          -- Merge dedicated Sea Beast/Terrorshark and mob-skill dodges; keep the highest safe offset.
          if type(fxD.DodgeOffset) == "function" then
              local okDodge, combinedOffset = pcall(fxD.DodgeOffset)
              if okDodge and type(combinedOffset) == "number" then
                  dodgeOffset = math.max(dodgeOffset, combinedOffset)
              end
          else
              if fxD.Enable.SeaDodgeV3 and type(fxD.SeaDodgeOffset) == "function" then
                  local okSea, seaOffset = pcall(fxD.SeaDodgeOffset)
                  if okSea and type(seaOffset) == "number" then dodgeOffset = math.max(dodgeOffset, seaOffset) end
              end
              if fxD.Enable.MobDodge and type(fxD.MobDodgeOffset) == "function" then
                  local okMob, mobOffset = pcall(fxD.MobDodgeOffset)
                  if okMob and type(mobOffset) == "number" then dodgeOffset = math.max(dodgeOffset, mobOffset) end
              end
          end
          if dodgeOffset > 0 then target = target + Vector3.new(0, dodgeOffset, 0) end
      end
  end
  local rootPart = character.HumanoidRootPart
  local distance = (target.Position - rootPart.Position).Magnitude
  -- User-requested fixed profile: >10 studs = 200; <=10 studs = 210.
  local requestedSpeed = distance <= 10 and 210 or 200
  local tweenSpeed = requestedSpeed
  local fx = _G.FARMX
  do
    local fx0 = fx
    if fx0 then fx0.SeaLastTarget = typeof(target) == "CFrame" and target or nil end
    local seaM = fx0 and fx0.SeaMode and fx0.SeaMode()
    if fx0 then fx0.SeaPath = seaM and "BLOCK" or "FLY/BLOCK" end
    if not seaM and fx0 and fx0.Enable and fx0.Enable.LinearVelocityFly and fx0.FlyTo and typeof(target) == "CFrame" then
      cancelMaruTargetTween()
      if fx0.FlyTo(target, tweenSpeed) then return end
    end
  end
  if fx and fx.Enable and fx.Enable.NearTween and distance <= ((fx.Cfg and fx.Cfg.NearDist) or 10) then
    tweenSpeed = math.max(tweenSpeed, (fx.Cfg and fx.Cfg.NearSpeed) or 210)
  end
  local _p26n250 = fx and distance <= ((fx.Cfg and fx.Cfg.FlyNearDist) or 10)
  if _p26n250 then
    tweenSpeed = math.max(tweenSpeed, (fx.Cfg and fx.Cfg.FlyNearSpeed) or 210)
  end
  -- Do not let the UI slider or a secondary cap silently reduce this safety profile.
  tweenSpeed = distance <= 10 and 210 or 200
  local activeTween = getgenv().__MaruActiveTargetTween
  local activeGoal = getgenv().__MaruActiveTargetTweenGoal
  local activeSpeed = getgenv().__MaruActiveTargetTweenSpeed
  if activeTween and activeGoal and activeSpeed == tweenSpeed
      and activeTween.PlaybackState == Enum.PlaybackState.Playing
      and (activeGoal.Position - target.Position).Magnitude <= 1.5 then
      return
  end
  cancelMaruTargetTween()
  local tweenInfo = TweenInfo.new(math.max(distance / tweenSpeed, 0.001), Enum.EasingStyle.Linear)
  local tween = game:GetService("TweenService"):Create(block, tweenInfo, {CFrame = target})
  getgenv().__MaruActiveTargetTween = tween
  getgenv().__MaruActiveTargetTweenGoal = target
  getgenv().__MaruActiveTargetTweenSpeed = tweenSpeed
  if (function() local _h = Attack.Hum(plr.Character); return _h and _h.Sit end)() == true then
    block.CFrame = CFrame.new(block.Position.X, target.Y, block.Position.Z)
  end
  tween:Play()
  task.spawn(function()
    -- This 10-stud transition is mandatory; it is not disabled by the optional UI NearWatch switch.
    local switched = distance <= 10
    while tween.PlaybackState == Enum.PlaybackState.Playing do
      if not shouldTween then tween:Cancel() break end
      if not switched then
        local remain = (target.Position - block.Position).Magnitude
        if remain <= 10 then
          switched = true
          local nearSpeed = 210
          tween:Cancel()
          tween = game:GetService("TweenService"):Create(block, TweenInfo.new(math.max(remain / nearSpeed, 0.001), Enum.EasingStyle.Linear), {CFrame = target})
          getgenv().__MaruActiveTargetTween = tween
          getgenv().__MaruActiveTargetTweenGoal = target
          getgenv().__MaruActiveTargetTweenSpeed = nearSpeed
          tween:Play()
        end
      end
      task.wait()
    end
    if getgenv().__MaruActiveTargetTween == tween then
      getgenv().__MaruActiveTargetTween = nil
      getgenv().__MaruActiveTargetTweenGoal = nil
      getgenv().__MaruActiveTargetTweenSpeed = nil
    end
  end)
end
