    FX.IsSeabeastDanger = function()
        local now = os.clock()
        local gap = (FX.Cfg and FX.Cfg.SeaDodgeGap) or 0.1
        if gap < 0.05 then gap = 0.05 end
        if now - FX.Seabeast._lastCheck < gap then return FX.Seabeast._lastV end
        FX.Seabeast._lastCheck = now
        local ok, v = pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            if not wo then return false end
            local names  = FX.Seabeast.Danger.names
            local colors = FX.Seabeast.Danger.colors
            for _, child in ipairs(wo:GetChildren()) do
                if child:IsA("BasePart") then
                    local bc = child.BrickColor
                    if bc then
                        for _, c in ipairs(colors) do
                            if bc.Name == c then return true end
                        end
                    end
                end
                local cname = (child.Name or ""):lower()
                for _, m in ipairs(names) do
                    if cname:find(m, 1, true) then return true end
                end
            end
            return false
        end)
        FX.Seabeast._lastV = (ok and v) and true or false
        return FX.Seabeast._lastV
    end
    FX.IsTerrorDanger = function()
        local now = os.clock()
        local gap = (FX.Cfg and FX.Cfg.SeaDodgeGap) or 0.1
        if gap < 0.05 then gap = 0.05 end
        if now - FX.Terror._lastCheck < gap then return FX.Terror._lastV end
        FX.Terror._lastCheck = now
        local ok, v = pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            if not wo then return false end
            local names = FX.Terror.Danger.names
