    FX.DIM.Acts = function()
        local out = {}
        local t, w = FX.DIM.Timer, FX.DIM.Watch
        if t.state ~= "idle" then
            out[#out + 1] = { kind = "timer", icon = "hourglass", text = FX.DIM.Fmt(FX.DIM.TimerLeft()), ring = FX.DIM.TimerLeft() / math.max(t.total, 1) }
        end
