            local dd = (mh and hr) and (hr.Position - mh.Position).Magnitude or -1
            if FX.TraceAdd then FX.TraceAdd("KILL_STALL", mob.Name, dd) end
            if mh and dd > 60 then _tp(mh.CFrame * CFrame.new(0, 20, 0)) end
        end)
        return os.clock()
    end
