        if (_G.FarmBoss or e.masked["_G.FarmBoss"]) and sn.bossName and (sn.en[sn.bossName] or sn.rep[sn.bossName]) then return true end
        if (_G.AutoFarmAllBoss or e.masked["_G.AutoFarmAllBoss"]) and BossList then
            for i = 1, #BossList do
                if sn.en[BossList[i]] then return true end
            end
        end
        return false
    end
