        table.sort(names, function(a, b)
            local ea, eb = FH.Reg[a], FH.Reg[b]
            if ea.tier ~= eb.tier then return ea.tier < eb.tier end
            return ea.seq < eb.seq
        end)
        local seen = {}
        for _, n in ipairs(names) do
