    FH.On = function() return FX.On and FX.Enable.EnableHandler and not FH.Disabled end
    FX.NotOwner = function(name)
        if not FH.On() then return false end
        local o = FH.Owner
        return o ~= nil and o.name ~= name
    end
    FH.OptVal = function(id)
        local opts = Library.Options
        local o = opts and opts[id]
        return o ~= nil and o.Value == true
    end
    FH.UiOn = function(e)
        if e.mode and _G.SelectedFarmMode == e.mode then return true end
        local ui = e.ui
        for i = 1, #ui do
            local ok, v = pcall(FH.OptVal, ui[i])
            if ok and v then return true end
        end
        return false
    end
    FH.DelegatorUi = {"Quests_AutoSanguineArt", "Prehistoric_AutoDojoTrainer"}
    FH.DelegatorOn = function(e)
        for _, n in ipairs(FH.Order) do
            local d = FH.Reg[n]
            if d ~= e and d.tier >= 8 and not (d.deleg == false and FX.Enable.SQDelegGuard) and FH.UiOn(d) then return true end
        end
        local ui = FH.DelegatorUi
        for i = 1, #ui do
            local ok, v = pcall(FH.OptVal, ui[i])
            if ok and v then return true end
        end
        return false
    end
    FH.Intent = function(e)
        if FH.UiOn(e) then return true end
        for _, origin in pairs(e.masked) do
            if origin == "deleg" and FH.DelegatorOn(e) then return true end
        end
        for _, f in ipairs(e.flags) do
            if FH.GetFlag(f) then return true end
        end
        return false
    end
    FH.Mask = function(e)
        local origin
        for _, f in ipairs(e.flags) do
            if FH.GetFlag(f) then
                origin = origin or (FH.UiOn(e) and "ui" or "deleg")
                e.masked[f] = origin
                FH.SetFlag(f, false)
            end
        end
    end
    FH.Restore = function(e)
        if next(e.masked) == nil then return end
        local saved = e.masked
        e.masked = {}
        for f, origin in pairs(saved) do
            local ok = (origin == "ui" and FH.UiOn(e)) or (origin == "deleg" and FH.DelegatorOn(e))
            if ok and not FH.GetFlag(f) then FH.SetFlag(f, true) end
        end
    end
    FH.RestoreAll = function()
        for _, n in ipairs(FH.Order) do
            local ok, err = pcall(FH.Restore, FH.Reg[n])
            if not ok then FX.Log("restoreall", err) end
        end
    end
    FX.IsTop = function(name)
        if not FH.On() then return true end
        local e = FH.Reg[name]
        if e == nil or FH.ClassOf(e) ~= "exclusive" then return true end
        return FH.Owner == e
    end
    FX.Own = function(name)
        if not FX.Enable.OwnExit then return true end
        return FX.IsTop(name)
    end
    FH.ShouldYield = function(name)
        if not FH.On() then return false end
        local e = FH.Reg[name]
        return e ~= nil and FH.ClassOf(e) == "exclusive" and FH.Owner ~= e
    end
    FH.Mirror = function()
        local o = FH.Owner
        _G.ActiveFarm = o and o.label or nil
    end
    FH.CoRun = function(o, e)
        if not o or o == e then return false end
        if o.controls then
            for _, c in ipairs(o.controls) do
                if c == e.name then return true end
            end
        end
        if e.controls then
            for _, c in ipairs(e.controls) do
                if c == o.name then return true end
            end
        end
        return false
    end
    FH.Snapshot = function()
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        return { cf = hrp.CFrame, place = game.PlaceId, char = char }
    end
    FH.ReturnHome = function(e)
        local s = e.saved
        e.saved = nil
        if not (FX.Enable.PositionReturn and s) then return end
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if char ~= s.char or s.place ~= game.PlaceId or not hrp then return end
        if (hrp.Position - s.cf.Position).Magnitude <= FX.Cfg.ReturnMinDist then return end
        local ok, err = pcall(_tp, s.cf)
        if not ok then FX.Log("return", err) end
    end
    FH.Grant = function(e)
        local now = os.clock()
        FX.Epoch = FX.Epoch + 1
        local prevO = FH.Owner
        if prevO == nil and now - FH.ReleasedAt < 3 then prevO = FH.LastOwner end
        pcall(FX.Boost.Switch, e, prevO, "grant")
        FH.Owner = e
        e.grantedAt = now
        e.sleepUntil = nil
        e.lostAt = nil
        e.lastPos, e.lastMoveAt = nil, now
        if e.releasedAt and now - e.releasedAt < FX.Cfg.FlapWindow then
            e.flaps = math.min((e.flaps or 0) + 1, 6)
        else
            e.flaps = 0
        end
        FH.Mirror()
        FH.Restore(e)
        if e.saved then FH.ReturnHome(e) end
        FX.Log("grant", e.name)
    end
    FH.Release = function(o, why)
        FX.Epoch = FX.Epoch + 1
        if FH.Owner == o then FH.Owner = nil end
        FH.ReleasedAt = os.clock()
        FH.LastOwner = o
        o.releasedAt = FH.ReleasedAt
        o.grantedAt = nil
        o.lostAt = nil
        FH.Mirror()
        -- Cleanup full khi release owner: stop fly + stop mob dodge + destroy body clip
        pcall(function()
            if FX.FlyStop then FX.FlyStop() end
            if FX.StopMobDodge then FX.StopMobDodge() end
            if FX.MobDodgeCleanupBody then FX.MobDodgeCleanupBody() end
        end)
        FX.Log("release", o.name .. " (" .. tostring(why) .. ")")
    end
    FX.Boost = { Active = false }
    FX.Boost.Switch = function(e, prev, why)
        local B = FX.Boost
        if not FX.Enable.SwitchBoost or e == nil or prev == nil or prev == e then return end
        local nm = e.name
        if nm ~= "CakePrince" and nm ~= "Bone" and nm ~= "Tyrant" then return end
        local cur = Settings["Tween Speed"] or 180
        if not B.Active then B.orig = cur end
        local orig = B.orig or cur
        local boost = math.clamp(math.max(orig, FX.Cfg.SwitchSpeed), 100, math.min(FX.Cfg.FlyBoostSpeed, FX.SpeedCap and FX.SpeedCap() or FX.Cfg.FlyBoostSpeed))
        if orig >= boost then return end
        Settings["Tween Speed"] = boost
        B.Active, B.boosted, B.t0, B.to = true, boost, os.clock(), nm
        B.lastPos, B.stillSince = nil, nil
        FX.Log("boost", tostring(prev.name) .. " -> " .. nm .. " (" .. tostring(why) .. ") " .. tostring(orig) .. " -> " .. tostring(boost))
    end
    FX.Boost.End = function(why)
        local B = FX.Boost
        if not B.Active then return end
        B.Active = false
        if B.orig and Settings["Tween Speed"] == B.boosted then Settings["Tween Speed"] = B.orig end
        FX.Log("boost", "end " .. tostring(why) .. " -> " .. tostring(Settings["Tween Speed"]))
        B.orig, B.boosted = nil, nil
    end
    FX.Boost.Check = function()
        local B = FX.Boost
        if not B.Active then return end
        local now = os.clock()
        local o = FH.Owner
        if not FX.Enable.SwitchBoost or FH.Disabled or o == nil or o.name ~= B.to then FX.Boost.End("owner") return end
        if now - B.t0 >= FX.Cfg.SwitchBoostSec then FX.Boost.End("timeout") return end
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then
            if B.lastPos and (hrp.Position - B.lastPos).Magnitude <= FX.Cfg.MoveEps then
                B.stillSince = B.stillSince or now
                if now - B.t0 >= 1.5 and now - B.stillSince >= 0.6 then FX.Boost.End("arrived") return end
            else
                B.stillSince = nil
            end
            B.lastPos = hrp.Position
        end
    end
    FX.Fly = { lv = nil, vf = nil, att = nil, hb = nil, target = nil, speed = 200, serial = 0, smVel = Vector3.zero, saved = nil }
    FX.FlyOn = false
    FX.FlyDestroy = function()
        local F = FX.Fly
        F.serial = F.serial + 1
        if F.hb then pcall(function() F.hb:Disconnect() end) F.hb = nil end
        for _, k in ipairs({ "lv", "vf", "att" }) do
            if F[k] then pcall(function() F[k]:Destroy() end) F[k] = nil end
        end
        F.target = nil
        F.smVel = Vector3.zero
    end
    FX.FlyStop = function()
        local F = FX.Fly
        local hadSaved = F.saved
        FX.FlyOn = false
        pcall(function() getgenv().SHX_ShouldFly = false end)
        if F.lv then pcall(function() F.lv.VectorVelocity = Vector3.zero end) end
        if F.vf then pcall(function() F.vf.Force = Vector3.zero end) end
        FX.FlyDestroy()
        local char = plr.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and hadSaved then
            pcall(function() hum.WalkSpeed = hadSaved.ws or 16 hum.JumpPower = hadSaved.jp or 50 end)
        end
        F.saved = nil
        do
            local c0 = plr.Character
            local h0 = c0 and c0:FindFirstChild("HumanoidRootPart")
            local clip = h0 and h0:FindFirstChild("BodyClip")
            if clip and clip:IsA("BodyVelocity") then pcall(function() clip.MaxForce = Vector3.new(100000, 100000, 100000) end) end
        end
    end
    FX.FlyEnsure = function()
        local F = FX.Fly
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        if F.lv and F.vf and F.att and F.lv.Parent == hrp and F.vf.Parent == hrp then return hrp end
        FX.FlyDestroy()
        local att = Instance.new("Attachment")
        att.Name = "NXV_MoveAtt"
        att.Parent = hrp
        local lv = Instance.new("LinearVelocity")
        lv.Name = "NXV_LinearVelocity"
        lv.Attachment0 = att
        lv.RelativeTo = Enum.ActuatorRelativeTo.World
        lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
        lv.MaxForce = FX.Cfg.FlyMaxForce
        lv.VectorVelocity = Vector3.zero
        lv.Parent = hrp
        local vf = Instance.new("VectorForce")
        vf.Name = "NXV_VectorForce"
        vf.Attachment0 = att
        vf.RelativeTo = Enum.ActuatorRelativeTo.World
        vf.ApplyAtCenterOfMass = true
        vf.Force = Vector3.zero
        vf.Parent = hrp
        F.att, F.lv, F.vf = att, lv, vf
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and not F.saved then F.saved = { ws = hum.WalkSpeed, jp = hum.JumpPower } end
        return hrp
    end
    FX.FlyLoop = function()
        local F = FX.Fly
        if F.hb then return end
        local my = F.serial
        F.hb = game:GetService("RunService").Heartbeat:Connect(function(dt)
            if F.serial ~= my then return end
            dt = math.clamp(dt or 0.016, 0.001, 0.05)
            local ok = pcall(function()
                if not shouldTween or not FX.Enable.LinearVelocityFly or not F.target then FX.FlyStop() return end
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum or hum.Health <= 0 then FX.FlyStop() return end
                if not F.lv or not F.vf or F.lv.Parent ~= hrp then
                    local keepT, keepS = F.target, F.speed
                    if not FX.FlyEnsure() then return end
                    F.target, F.speed = keepT, keepS
                    FX.FlyLoop()
                    return
                end
                F.vf.Force = Vector3.new(0, hrp.AssemblyMass * workspace.Gravity, 0)
                hum.WalkSpeed = 0
                hum.JumpPower = 0
                hrp.AssemblyAngularVelocity = Vector3.zero
                local clip = hrp:FindFirstChild("BodyClip")
                if clip and clip:IsA("BodyVelocity") and clip.MaxForce ~= Vector3.zero then clip.MaxForce = Vector3.zero end
                local delta = F.target.Position - hrp.Position
                local d = delta.Magnitude
                if d <= FX.Cfg.FlyArriveDist then
                    F.smVel = Vector3.zero
                    F.lv.VectorVelocity = Vector3.zero
                    hrp.CFrame = CFrame.new(F.target.Position) * (hrp.CFrame - hrp.CFrame.Position)
                    return
                end
                local spd = d <= 10 and 210 or 200
                F.smVel = F.smVel:Lerp(delta.Unit * spd, math.clamp(dt * FX.Cfg.FlySmooth, 0, 1))
                F.lv.VectorVelocity = F.smVel
            end)
            if not ok then FX.FlyStop() end
        end)
    end
    FX.FlyTo = function(targetCF, speed)
        if not FX.Enable.LinearVelocityFly or not shouldTween then return false end
        if FX.SeaMode and FX.SeaMode() then return false end
        if typeof(targetCF) ~= "CFrame" then return false end
        local ok, res = pcall(function()
            if not FX.FlyEnsure() then return false end
            local F = FX.Fly
            F.target = targetCF
            F.speed = math.clamp(tonumber(speed) or 200, FX.Cfg.FlyMinSpeed, 210)
            FX.FlyOn = true
            pcall(function() getgenv().SHX_ShouldFly = true end)
            FX.FlyLoop()
            return true
        end)
        return ok and res == true
    end
    FH.Preempt = function(o, best)
        o.saved = FH.Snapshot()
        o.grantedAt = nil
        o.waitSince = nil
        FH.Mask(o)
        FX.Epoch = FX.Epoch + 1
        FX.Log("preempt", o.name .. " <- " .. best.name)
        FH.Grant(best)
    end
    local function ISL()
        local ok, isl = pcall(function() return Library.WindUI.Island end)
        if ok then return isl end
        return nil
    end
    FH.Island = { track = nil, farm = nil, trackOwner = nil, farmOwner = nil, Skip = { Level = true } }
    local FI = FH.Island
    local function stopTrack()
        if FI.track then
            local h = FI.track
            pcall(function() h:Stop() end)
            FI.track, FI.trackOwner = nil, nil
        end
    end
    local function stopFarm()
        if FI.farm then
            local h = FI.farm
            pcall(function() h:Stop() end)
            FI.farm, FI.farmOwner = nil, nil
        end
    end
    FH.Detect = function(name, d)
        local isl = ISL()
        if not isl then return end
        d = d or {}
        stopFarm()
        local data = {
            Title = d.Title or ("Going to " .. tostring(name)),
            Content = d.Content,
            Icon = d.Icon or "navigation",
            Color = d.Color,
            Unit = d.Unit or "studs away",
        }
        if d.Distance ~= nil then
            data.Value = isl:FormatNumber(d.Distance)
        else
            data.Value = d.Value
        end
        data.Compact = data.Value
        FI.track = isl:Detect(data)
        FI.trackOwner = name
        return FI.track
    end
    FH.FarmData = function(name, d)
        local isl = ISL()
        if not isl then return end
        d = d or {}
        stopTrack()
        local data = {
            Title = d.Title or ("Farming " .. tostring(name)),
            Content = d.Content, Value = d.Value, Unit = d.Unit, Left = d.Left, Right = d.Right,
            Progress = d.Progress, Icon = d.Icon or "swords", Color = d.Color, Compact = d.Compact or d.Value,
        }
        FI.farm = isl:Farm(data)
        FI.farmOwner = name
        return FI.farm
    end
    FH.Finish = function(name, d)
        local isl = ISL()
        if not isl then return end
        d = d or {}
        local res = isl:Finish({
            Title = d.Title or "Done", Content = d.Content or tostring(name),
            Success = d.Success, Color = d.Color, Duration = d.Duration,
        })
        if FX.Enable.FinishModes and FX.Enable.StatusPill and isl.StatusPill then
            local okF = d.Success ~= false
            local txt = tostring(d.Title or "Done") .. "  ·  " .. tostring(d.Content or name)
            FI.finTok = (FI.finTok or 0) + 1
            local finTok = FI.finTok
            task.delay((d.Duration or 2.6) + 0.3, function()
                if FI.finTok ~= finTok then return end
                pcall(isl.StatusPill, isl, okF and "green" or "red", { Text = txt, Duration = FX.Cfg.FinishPillSec, Keep = true })
            end)
        end
        return res
    end
    FH.Notify = function(title, content, opts)
        local isl = ISL()
        if not isl then return end
        opts = opts or {}
        return isl:Notify({
            Title = title, Content = content, Value = opts.Value, Unit = opts.Unit,
            Icon = opts.Icon, Color = opts.Color, Duration = opts.Duration,
        })
    end
    FH.NotifyRed = function(d)
        local isl = ISL()
        if isl and isl.StatusPill then return pcall(isl.StatusPill, isl, "red", d) end
    end
    FH.NotifyYellow = function(d)
        local isl = ISL()
        if isl and isl.StatusPill then return pcall(isl.StatusPill, isl, "yellow", d) end
    end
    FH.NotifyGreen = function(d)
        local isl = ISL()
        if isl and isl.StatusPill then return pcall(isl.StatusPill, isl, "green", d) end
    end
    FH._DotDebounce = { key = nil, t = -1e9 }
    FH.NotifyDot = function(color, content, duration)
        local lvF = ({ g = "green", green = "green", y = "yellow", yellow = "yellow", r = "red", red = "red" })[string.lower(tostring(color))] or "green"
        -- Debounce: skip nếu cùng color+content trong 1.5s (tránh spam notification)
        local key = lvF .. "|" .. tostring(content or "")
        local now = os.clock()
        if FH._DotDebounce.key == key and now - FH._DotDebounce.t < 1.5 then return end
        FH._DotDebounce.key = key
        FH._DotDebounce.t = now
        local isl = ISL()
        if isl and isl.StatusPill then
            return pcall(isl.StatusPill, isl, lvF, { Text = tostring(content or ""), Duration = tonumber(duration) or FX.Cfg.DotDefaultDuration, Keep = true })
        end
    end
    FX.NotifyDot = FH.NotifyDot
    FH.IslandStop = function(name)
        if name == nil or FI.trackOwner == name then stopTrack() end
        if name == nil or FI.farmOwner == name then stopFarm() end
    end
    FX.Nav = { t = -1e9, label = nil }
    FX.Nav.Update = function(kind, label, pos)
        if not FX.Enable.Nav or pos == nil then return end
        local now = os.clock()
        if now - FX.Nav.t < 0.25 then return end
        FX.Nav.t = now
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        FX.Nav.label = label
        pcall(FH.Detect, label, { Title = "Going to " .. tostring(label), Distance = math.floor((hrp.Position - pos).Magnitude) })
    end
    FX.Nav.Clear = function(why)
        local l = FX.Nav.label
        if l then
            FX.Nav.label = nil
            pcall(FH.IslandStop, l)
        end
    end
    FX.Nav.IsActive = function()
        return FX.Nav.label ~= nil and os.clock() - FX.Nav.t <= (FX.Cfg.NavStale or 3)
    end
    FX.Nav.Idx = nil
    FX.Nav.IdxT = -1e9
    FX.Nav.tAuto = -1e9
    FX.Nav.Allow = {
        MeleeBlackLeg = true, MeleeElectro = true, MeleeFishmanKarate = true, MeleeDragonClaw = true, MeleeSuperhuman = true, MeleeDeathStep = true, MeleeSharkman = true, MeleeElectric = true, MeleeDragonTalon = true, MeleeGodhuman = true,
        ItemQuests = true, Sea2 = true, Sea3 = true, Bartilo = true, CDK = true, Yama = true, Tushita = true, SoulGuitar = true, SummonBoss = true,
    }
    FX.Nav.Build = function()
        local now = os.clock()
        if FX.Nav.Idx and now - FX.Nav.IdxT < FX.Cfg.NavNpcRefresh then return FX.Nav.Idx end
        local idx = {}
        pcall(function()
            local folders = { game:GetService("ReplicatedStorage"):FindFirstChild("NPCs"), workspace:FindFirstChild("NPCs") }
            for _, folder in ipairs(folders) do
                if folder then
                    for _, v in ipairs(folder:GetChildren()) do
                        local r = v:FindFirstChild("HumanoidRootPart")
                        if r and r:IsA("BasePart") then
                            idx[#idx + 1] = { name = (string.gsub(v.Name, "%s+$", "")), pos = r.Position }
                        end
                    end
                end
            end
        end)
        FX.Nav.Idx, FX.Nav.IdxT = idx, now
        return idx
    end
    FX.Nav.Auto = function(target)
        if not FX.Enable.NavAuto or not FX.Enable.Nav or typeof(target) ~= "CFrame" then return end
        local now = os.clock()
        if now - FX.Nav.tAuto < 0.2 then return end
        FX.Nav.tAuto = now
        local pos = target.Position
        local o = FH.Owner
        local on = o and o.name
        if on == "RandomFruit" then
            FX.Nav.Update("fruit", "collect fruit", pos)
            return
        end
        if on ~= nil and not FX.Nav.Allow[on] then return end
        local idx = FX.Nav.Build()
        local best, bd = nil, FX.Cfg.NavNpcRadius
        for i = 1, #idx do
            local d = (idx[i].pos - pos).Magnitude
            if d <= bd then best, bd = idx[i], d end
        end
        if best then FX.Nav.Update("npc", best.name, best.pos) end
    end
    do
        local IH = { Probe = {}, tNext = 0, shown = nil, qc = nil }
        FX.IH = IH
        IH.NotifyDot = FH.NotifyDot
        IH.Excluded = { Level = true, SeaEvent = true, RandomFruit = true, Redeem = true, Chest = true, ItemQuests = true, SecretQuest = true, NearIsland = true }
        IH.ReadQuest = function()
            local now = os.clock()
            local c = IH.qc
            if c and now - c.t < 0.5 then return c end
            c = { t = now }
            IH.qc = c
            pcall(function()
                local useTracked = (not FX.Enable) or FX.Enable.IslandQuestRead
                if useTracked then
                    local pg = plr.PlayerGui
                    local tq = pg and pg:FindFirstChild("TrackedQuestFrame")
                    if tq then
                        local frame = tq:FindFirstChild("Frame", true)
                        local header = frame and frame:FindFirstChild("header", true)
                        local tl1 = header and header:FindFirstChild("textLabel", true)
                        local tl2 = tl1 and tl1:FindFirstChild("textLabel", true)
                        local txt = tl2 and tl2.Text
                        if type(txt) == "string" and txt ~= "" then
                            local a, b = string.match(txt, "(%d+)%s*/%s*(%d+)")
                            if a then c.cur, c.need = tonumber(a), tonumber(b) end
                            if not c.cur then
                                local a2, b2 = string.match(txt, "%((%d+)%s*/%s*(%d+)%)")
                                if a2 then c.cur, c.need = tonumber(a2), tonumber(b2) end
                            end
                            local n, nm = string.match(txt, "[Dd]efeat%s+(%d+)%s+(.+)$")
                            if n then
                                c.defeat = tonumber(n)
                                c.mob = string.gsub(nm, "s$", "")
                            end
                            if c.cur and c.need then return end
                        end
                    end
                end
                local q = plr.PlayerGui.Main.Quest
                if not q.Visible then return end
                local texts = {}
                for _, d in ipairs(q:GetDescendants()) do
                    if d:IsA("TextLabel") or d:IsA("TextButton") then
                        local tx = d.Text
                        if type(tx) == "string" and tx ~= "" then texts[#texts + 1] = tx end
                    end
                end
                for _, tx in ipairs(texts) do
                    local a, b = string.match(tx, "^%s*(%d+)%s*/%s*(%d+)%s*$")
                    if a then c.cur, c.need = tonumber(a), tonumber(b) break end
                end
                if not c.cur then
                    for _, tx in ipairs(texts) do
                        local a, b = string.match(tx, "%((%d+)%s*/%s*(%d+)%)")
                        if a then c.cur, c.need = tonumber(a), tonumber(b) break end
                    end
                end
                for _, tx in ipairs(texts) do
                    local n, nm = string.match(tx, "[Dd]efeat%s+(%d+)%s+(.+)$")
                    if n then
                        c.defeat = tonumber(n)
                        c.mob = string.gsub(nm, "s$", "")
                        break
                    end
                end
            end)
            return c
        end
        local function questProbe(fallback)
            return function()
                local q = IH.ReadQuest()
                if q.cur == nil or q.need == nil or q.need <= 0 then return nil end
                local lvl
                pcall(function() lvl = plr.Data.Level.Value end)
                local pr = math.clamp(q.cur / q.need, 0, 1)
                return {
                    Title = "Farming " .. tostring(q.mob or fallback),
                    Content = (lvl and ("Lv " .. tostring(lvl) .. "  ·  ") or "") .. "Defeat " .. tostring(q.defeat or q.need),
                    Value = tostring(q.cur) .. "/" .. tostring(q.need), Unit = "kills",
                    Left = lvl and ("Lv " .. tostring(lvl)) or nil,
                    Right = tostring(math.floor(100 * pr)) .. "%", Progress = pr,
                }
            end
        end
        IH.Probe.CakePrince = questProbe("Cake")
        IH.Probe.Bone = questProbe("Bone")
        IH.Probe.Tyrant = questProbe("Tyrant")
        IH.baseCake, IH.baseBone = IH.Probe.CakePrince, IH.Probe.Bone
        IH.Probe.CakePrince = function()
            local fxP = _G.FARMX
            local useV2 = fxP and fxP.Enable and fxP.Enable.StageV2
            local useV3 = fxP and fxP.Enable and fxP.Enable.CakeQuestStage
            if useV2 or useV3 then
                local killed = tonumber(fxP._CakeKillLast) or 0
                local bossAlive = false
                pcall(function()
                    local enemies = workspace:FindFirstChild("Enemies")
                    if enemies then
                        local b = enemies:FindFirstChild("Cake Prince")
                        if b and Attack.Alive(b) then bossAlive = true end
                    end
                end)
                fxP._CakeBossAlive = bossAlive
                local stage = 0
                if useV2 then
                    stage = fxP.Stage and fxP.Stage(killed, bossAlive) or 0
                else
                    if bossAlive then stage = 5
                    elseif killed >= 500 then stage = 5
                    elseif killed >= 400 then stage = 4
                    elseif killed >= 300 then stage = 3
                    elseif killed >= 200 then stage = 2
                    elseif killed >= 100 then stage = 1
                    end
                end
                if stage > 0 then
                    local pr
                    local contentStr
                    local valueStr
                    if useV2 then
                        pr = math.clamp(killed / 500, 0, 1)
                        valueStr = tostring(killed)
                        contentStr = bossAlive and "Cake Prince spawned" or "CakePrince killed"
                    else
                        local threshold = stage * 100
                        pr = math.clamp(threshold / 500, 0, 1)
                        valueStr = tostring(threshold)
                        contentStr = "CakePrince killed"
                    end
                    return {
                        Title = "Data Quest " .. tostring(stage),
                        Content = contentStr,
                        Value = valueStr,
                        Unit = "/ 500",
                        Right = tostring(math.floor(100 * pr)) .. "%",
                        Progress = pr,
                    }
                end
            end
            local d = IH.baseCake()
            if d then
                local c = FX.Cache and FX.Cache["CakePrinceSpawner"]
                local n = c and type(c.v) == "string" and tonumber(string.match(c.v, "%d+"))
                if n then d.Content = d.Content .. "  ·  Prince " .. tostring(500 - n) .. "/500" end
            end
            return d
        end
        IH.Probe.Bone = function()
            local d = IH.baseBone()
            if d then
                local c = FX.Cache and FX.Cache["BonesCheck"]
                if c and c.v ~= nil then d.Content = d.Content .. "  ·  Bones " .. tostring(c.v) end
            end
            return d
        end
        IH.baseTyrant = IH.Probe.Tyrant
        IH.Probe.Tyrant = function()
            local fxP = _G.FARMX
            if fxP and fxP.Enable and fxP.Enable.StageV2 then
                local bossAlive = false
                pcall(function()
                    local enemies = workspace:FindFirstChild("Enemies")
                    if enemies then
                        local b = enemies:FindFirstChild("Tyrant of the Skies")
                        if b and Attack.Alive(b) then bossAlive = true end
                    end
                end)
                if bossAlive then
                    fxP._TyrantBossSeen = true
                    return {
                        Title = "Data Quest 5",
                        Content = "Tyrant  ·  Boss alive",
                        Value = "Boss",
                        Unit = "/ 4",
                        Right = "100%",
                        Progress = 1.0,
                    }
                end
                -- R16: dùng centralized reader + UNKNOWN state khi hierarchy lỗi
                local eyeInfo = FX.ReadTyrantEyes and FX.ReadTyrantEyes() or { count = 0, ok = false }
                local eyes = eyeInfo.count or 0
                if not eyeInfo.ok then
                    return {
                        Title = "Data Quest ?",
                        Content = "Tyrant  ·  UNKNOWN",
                        Value = "?",
                        Unit = "/ 4",
                        Right = "—",
                        Progress = 0,
                    }
                end
                if eyes >= 1 and eyes <= 4 then
                    local pr = math.clamp(eyes / 4, 0, 1)
                    return {
                        Title = "Data Quest " .. tostring(eyes),
                        Content = "Tyrant",
                        Value = tostring(eyes),
                        Unit = "/ 4",
                        Right = tostring(math.floor(100 * pr)) .. "%",
                        Progress = pr,
                    }
                end
            end
            return IH.baseTyrant()
        end
        IH.dn = {}
        IH.questDone = function()
            local q = IH.ReadQuest()
            if q.cur ~= nil and q.need ~= nil and q.need > 0 and q.cur >= q.need then
                return true, "Quest complete / " .. tostring(q.mob or "quest") .. " x" .. tostring(q.need)
            end
            return false
        end
        -- R17: IH.Done.Tyrant — boss seen rồi defeat = done
        IH.Done = {
            CakePrince = IH.questDone,
            Bone = IH.questDone,
            Tyrant = function()
                local fxP = _G.FARMX
                if not (fxP and fxP._TyrantBossSeen) then return false end
                local enemies = workspace:FindFirstChild("Enemies")
                if not enemies then return true, "Tyrant defeated" end
                local b = enemies:FindFirstChild("Tyrant of the Skies")
                if not b or not Attack.Alive(b) then
                    return true, "Tyrant defeated"
                end
                return false
            end,
        }
        IH.Probe.Elite = function()
            local c = FX.Cache and FX.Cache["EliteProgress"]
            local n = c and tonumber(c.v)
            if n == nil then return nil end
            local pr = math.clamp(n / 30, 0, 1)
            return {
                Title = "Elite Hunter", Content = "Elite Hunter  ·  Defeat 30 elites",
                Value = tostring(n) .. "/30", Unit = "elites",
                Right = tostring(math.floor(100 * pr)) .. "%", Progress = pr,
            }
        end
        IH.Tick = function()
            local now = os.clock()
            if now < IH.tNext then return end
            IH.tNext = now + FX.Cfg.IHTick
            local o = FH.Owner
            local nm = o and o.name
            local pf = nil
            if FX.Nav and FX.Nav.label and now - FX.Nav.t > FX.Cfg.NavStale then FX.Nav.Clear("stale") end
            local skipProbe = false
            if FX.Enable and FX.Enable.IslandStateV2 and nm and (nm == "CakePrince" or nm == "Tyrant") then
                local okSt, st = pcall(FX.IslandState, nm)
                if okSt and (st == "TRAVEL_NPC" or st == "QUEST_PENDING" or st == "IDLE") then
                    skipProbe = true
                end
            end
            if FX.Nav and FX.Nav.IsActive and FX.Nav.IsActive() then skipProbe = true end
            if not skipProbe and nm and FX.Enable.IslandHandler and FH.On() then
                pf = IH.Probe[nm]
                if pf == nil and FX.Enable.IHGeneric and not IH.Excluded[nm] then
                    pf = questProbe(nm)
                end
            end
            if FX.Enable.SuccessAlert and nm and IH.Done[nm] then
                local okD, done, txt = pcall(IH.Done[nm])
                local st = IH.dn[nm]
                if okD and done then
                    if not st then
                        IH.dn[nm] = { t = now, fired = false }
                    elseif not st.fired and now - st.t >= 0.45 then
                        st.fired = true
                        pcall(FH.Finish, nm, { Title = txt or (tostring(nm) .. " Complete"), Content = tostring(nm), Success = true })
                    end
                else
                    IH.dn[nm] = nil
                end
            end
            if not pf then
                if IH.shown then
                    FH.IslandStop(IH.shown)
                    IH.shown = nil
                end
                return
            end
            local ok, d = pcall(pf)
            if ok and type(d) == "table" then
                if IH.shown and IH.shown ~= nm then FH.IslandStop(IH.shown) end
                FH.FarmData(nm, d)
                IH.shown = nm
            elseif IH.shown then
                FH.IslandStop(IH.shown)
                IH.shown = nil
            end
        end
    end
    do
        local oGrant, oRelease = FH.Grant, FH.Release
        FH.Grant = function(e)
            oGrant(e)
            pcall(function()
                if FI.Skip[e.name] then return end
                if not FX.Cfg.OwnerToasts then return end
                local n = e.label or e.name
                if FX.Enable.StatusPill then
                    local isl0 = ISL()
                    if isl0 and isl0.StatusPill then
                        FI.statusOwner = n
                        isl0:StatusPill("green", { Text = tostring(n), Title = tostring(n), Description = "Function Handler  ·  tier " .. tostring(e.tier) })
                        return
                    end
                end
                FH.FarmData(n, {
                    Title = "Farming " .. tostring(n),
                    Content = "Function Handler  ·  tier " .. tostring(e.tier),
                    Value = "T" .. tostring(e.tier), Unit = "tier",
                })
            end)
        end
        FH.Release = function(o, why)
            oRelease(o, why)
            pcall(function() FH.IslandStop(o.label or o.name) end)
            pcall(function()
                local n = o.label or o.name
                if FI.statusOwner == n then
                    FI.statusOwner = nil
                    local isl0 = ISL()
                    if isl0 and isl0.StatusStop then isl0:StatusStop() end
                end
            end)
        end
    end
    FH.OnDisabled = function(e)
        e.saved = nil
        e.sleepUntil = nil
        e.lostAt = nil
        e.masked = {}
        if e.name == "SelectedMob" and FX.SelReset then
            FX.SelReset()
            if FX.Sel then FX.Sel.name = nil end
        elseif e.name == "Chest" and FX.ChestState then
            FX.ChestState.list, FX.ChestState.goal = nil, nil
        end
        if FH.Owner == e then FH.Release(e, "tắt") end
    end
    FH.CachedWant = function(e)
        return e.want() and true or false
    end
    FH.IdleCheck = function(o, now)
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then o.lastMoveAt = now return false end
        if (not o.lastPos) or (hrp.Position - o.lastPos).Magnitude > FX.Cfg.MoveEps then
            o.lastPos, o.lastMoveAt = hrp.Position, now
            return false
        end
        return now - (o.lastMoveAt or now) > FX.Cfg.TargetLostTimeout
    end
    FH.Tick = function()
        local now = os.clock()
        local cfg = FX.Cfg
        pcall(FX.Boost.Check)
        for _, n in ipairs(FH.Order) do
            local e = FH.Reg[n]
            if FH.ClassOf(e) == "exclusive" then
                local on = FH.Intent(e)
                if e.was and not on then FH.OnDisabled(e) end
                e.was = on
                e.on = on
            else
                e.on = false
            end
        end
        local o = FH.Owner
        if o then
            local keep = o.on and FH.ClassOf(o) == "exclusive"
            if keep and o.want then
                if FH.CachedWant(o) then
                    o.lostAt = nil
                else
                    o.lostAt = o.lostAt or now
                    if now - o.lostAt >= cfg.WantLossGrace * (1 + 4 * (o.flaps or 0)) then keep = false end
                end
            end
            if keep and FX.Enable.IdleRelease and o.idle and FH.IdleCheck(o, now) then
                o.sleepUntil = now + cfg.SleepTime
                keep = false
            end
            if not keep then
                FH.Release(o, "xong/không còn want/idle")
                o = nil
            end
        end
        local best
        for _, n in ipairs(FH.Order) do
            local e = FH.Reg[n]
            if e.on and not FH.CoRun(o, e) and not (e.sleepUntil and now < e.sleepUntil) then
                if (not e.want) or FH.CachedWant(e) then best = e break end
            end
        end
        if o then
            -- R18: SummonBoss → Tyrant handoff khi eyes all open (4/4)
            -- SummonBoss tier 7 < Tyrant tier 12, nên bình thường Tyrant không preempt được
            -- Force release SummonBoss khi eyes mở, sleep 30s để Tyrant grab owner
            if o.name == "SummonBoss" and FX.Enable and FX.Enable.TyrantMove then
                local eyeInfo = FX.ReadTyrantEyes and FX.ReadTyrantEyes() or nil
                if eyeInfo and eyeInfo.ok and eyeInfo.count >= 4 then
                    o.sleepUntil = now + 30
                    FH.Release(o, "tyrant-eyes-open-handoff")
                    o = nil
                end
            end
            if o then
                if best and best ~= o and best.tier < o.tier then
                    o.waitSince = o.waitSince or now
                    local hold = o.grantedAt and (now - o.grantedAt) or math.huge
                    local atomicHold = o.atomic and o.atomic() and (now - o.waitSince) < (o.atomicMax or cfg.AtomicTimeout)
                    if hold >= cfg.HoldMin and not atomicHold then FH.Preempt(o, best) end
                else
                    o.waitSince = nil
                end
            end
        elseif best then
            if not (best.saved and now - FH.ReleasedAt < cfg.GraceAfterDone) then FH.Grant(best) end
        end
        for _, n in ipairs(FH.Order) do
            local e = FH.Reg[n]
            local lingering = (e == FH.LastOwner) and (FH.Owner == nil) and (now - FH.ReleasedAt < cfg.GraceAfterDone)
            if e ~= FH.Owner and FH.ClassOf(e) == "exclusive" and not FH.CoRun(FH.Owner, e) and not lingering then FH.Mask(e) end
        end
    end
    FH.Degrade = function(err)
        FH.Warn("degrade", "[Handler] tắt do lỗi, quay về hành vi cũ: " .. tostring(err))
        FH.Disabled = true
        pcall(FX.Boost.End, "degrade")
        FX.On = false
        FH.RestoreAll()
        FH.Owner = nil
        _G.ActiveFarm = FX.Modes[_G.SelectedFarmMode]
    end
    FH.Status = function()
        local paused = {}
        for _, n in ipairs(FH.Order) do
            local e = FH.Reg[n]
            if e.saved or next(e.masked) ~= nil then paused[#paused + 1] = n end
        end
        return { owner = FH.Owner and FH.Owner.name or nil, paused = paused, disabled = FH.Disabled, epoch = FX.Epoch }
    end
    FX.OnModeChosen = function(value)
        FX.ModeGen = FX.ModeGen + 1
        for _, nm in pairs(FX.Modes) do
            local e = FH.Reg[nm]
            if e then e.saved = nil e.masked = {} end
        end
        if FX.ApplyMode then FX.ApplyMode(value) end
        if FH.On() then FH.Mirror() end
    end
    FX.Start = function()
        FX.Token = FX.Token + 1
        local tok = FX.Token
        task.spawn(function()
            while FX.Token == tok and task.wait(FX.Cfg.HandlerTick) do
                if FH.On() then
                    local ok, err = pcall(FH.Tick)
                    if not ok then FH.Degrade(err) end
                end
                if FX.IH and FX.IH.Tick then pcall(FX.IH.Tick) end
            end
        end)
    end
    FX.Stop = function()
        FX.Token = FX.Token + 1
        if FX.CharConn then FX.CharConn:Disconnect() FX.CharConn = nil end
        if FX.StopMobDodge then pcall(FX.StopMobDodge) end
        cancelMaruTargetTween()
        if FX.FlyStop then pcall(FX.FlyStop) end
        pcall(FH.RestoreAll)
        FX.On = false
    end
    FX.CachedInvoke = function(key, ttl, ...)
        local now = os.clock()
        local c = FX.Cache[key]
        if c and now - c.t < ttl then return c.v end
        local args = table.pack(...)
        local ok, r = pcall(function()
            return replicated.Remotes.CommF_:InvokeServer(table.unpack(args, 1, args.n))
        end)
        if not ok then FX.Log("remote-" .. tostring(key), r) r = nil end
        FX.Cache[key] = { t = now, v = r }
        return r
    end
    FX.RStat = { calls = 0, hits = 0, stale = 0, waits = 0 }
    FX.Bucket = {}
    FX.Take = function(name, rate, burst)
        local now = os.clock()
        local b = FX.Bucket[name]
        if not b then b = { n = burst, t = now } FX.Bucket[name] = b end
        b.n = math.min(burst, b.n + (now - b.t) * rate)
        b.t = now
        if b.n >= 1 then b.n = b.n - 1 return true end
        return false
    end
    FX.QRead = function(...)
        local args = table.pack(...)
        if not (FX.Enable and FX.Enable.RemoteLimit) then
            return replicated.Remotes.CommF_:InvokeServer(table.unpack(args, 1, args.n))
        end
        local parts = {}
        for i = 1, args.n do parts[i] = tostring(args[i]) end
        local key = "QR:" .. table.concat(parts, "|")
        local c = FX.Cache[key]
        if c and os.clock() - c.t < (FX.Cfg.QReadTTL or 0.5) then
            FX.RStat.hits = FX.RStat.hits + 1
            return c.v
        end
        local tries = 0
        while not FX.Take("remote", FX.Cfg.RemoteRate or 10, FX.Cfg.RemoteBurst or 15) do
            FX.RStat.waits = FX.RStat.waits + 1
            if c then FX.RStat.stale = FX.RStat.stale + 1 return c.v end
            tries = tries + 1
            if tries > 20 then break end
            task.wait(0.1)
        end
        FX.RStat.calls = FX.RStat.calls + 1
        local r = replicated.Remotes.CommF_:InvokeServer(table.unpack(args, 1, args.n))
        FX.Cache[key] = { t = os.clock(), v = r }
        return r
    end
    FX.MaterialCount = function(name)
        local inv = FX.CachedInvoke("getInventory", FX.Cfg.MaterialInvTTL, "getInventory")
        if type(inv) ~= "table" then return 0 end
        for _, tab in pairs(inv) do
            if type(tab) == "table" and tab.Type == "Material" and tab.Name == name then
                return tonumber(tab.Count) or 0
            end
        end
        return 0
    end
    FX.MaterialEnough = function()
        if not FX.Enable.MaterialTarget then return false end
        local goal = tonumber(getgenv().MaterialTarget) or 0
        local pick = getgenv().SelectMaterial
        if goal <= 0 or type(pick) ~= "string" then return false end
        for part in string.gmatch(pick, "[^%+]+") do
            local nm = part:gsub("^%s+", ""):gsub("%s+$", "")
            if FX.MaterialCount(nm) < goal then return false end
        end
        getgenv().AutoMaterial = false
        pcall(function() Library.Options["Main_AutoFarmMaterials"]:SetValue(false) end)
        FX.Log("material-done", pick .. " >= " .. goal)
        return true
    end
    FX.OnRespawn = function(char)
        if not FX.Enable.Respawn then return end
        task.wait(FX.Cfg.RespawnSettle)
        local hrp = char:WaitForChild("HumanoidRootPart", 5)
        if not hrp then return end
        if FX.SelReset then FX.SelReset() end
        if FX.StopMobDodge then pcall(FX.StopMobDodge) end
        if FX.ChestState then FX.ChestState.goal = nil end
        for _, e in pairs(FX.FH.Reg) do e.saved = nil end
        pcall(function()
            block.CFrame = hrp.CFrame
            game:GetService("TweenService"):Create(block, TweenInfo.new(0), { CFrame = hrp.CFrame }):Play()
        end)
        if FX.FlyStop then FX.FlyStop() end
        FX.Log("respawn", "đã nhả tween/mục tiêu cũ")
    end
    if FX.CharConn then FX.CharConn:Disconnect() end
    FX.CharConn = plr.CharacterAdded:Connect(function(char) FX.OnRespawn(char) end)
    FX.Info = function(key, ...)
        if FX.Enable.InfoThrottle then
            return FX.CachedInvoke(key, FX.Cfg.InfoRemoteInterval, ...)
        end
        return replicated.Remotes.CommF_:InvokeServer(...)
    end
    FX.Gates = {}
    FX.Gate = function(key, interval)
        local now = os.clock()
        local last = FX.Gates[key]
        if last and now - last < interval then return false end
        FX.Gates[key] = now
        return true
    end
    FX.Debounce = function(key)
        if not FX.Enable.PassiveDebounce then return true end
        return FX.Gate(key, FX.Cfg.RedeemDebounce)
    end
    FX.Start()
end
