                    questTitle = (trText ~= "" and trText) or (questGui and questGui:FindFirstChild("Container") and questGui.Container:FindFirstChild("QuestTitle") and questGui.Container.QuestTitle:FindFirstChild("Title") and questGui.Container.QuestTitle.Title.Text) or ""
                    questVisible = (trText ~= "") or (questGui and questGui.Visible == true) or false
                else
                    questGui = plr.PlayerGui.Main.Quest
                    questTitle = questGui.Container.QuestTitle.Title.Text
                    questVisible = questGui.Visible
                end
                if not questVisible then
                    local result = replicated.Remotes.CommF_:InvokeServer("EliteHunter")
                    local isCooldown = type(result) == "string" and string.find(result, "Cooldown", 1, true) ~= nil
                    if result == nil or isCooldown then
                        wait(10)
                        return
                    end
                    task.wait(1)
                else
                    local eliteName = nil
                    for _, name in pairs({"Diablo", "Urban", "Deandre"}) do
                        if type(questTitle) == "string" and string.find(questTitle, name, 1, true) then
                            eliteName = name
                            break
                        end
                    end
                    if eliteName then
                        local boss = nil
                        for _, v in pairs(replicated:GetChildren()) do
                            if v.Name == eliteName and v:FindFirstChild("HumanoidRootPart") then
                                boss = v
                                break
                            end
                        end
                        for _, v in pairs(Enemies:GetChildren()) do
                            if v.Name == eliteName and Attack.Alive(v) then
                                boss = v
                                break
                            end
                        end
                        if boss and boss:FindFirstChild("HumanoidRootPart") then
                            pcall(function() if AutoHaki then AutoHaki() end end)
                            pcall(function() if EquipWeapon and _G.SelectWeapon then EquipWeapon(_G.SelectWeapon) end end)
                            _tp(boss.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                            repeat
                                wait()
                                Attack.Kill(boss, _G.FarmEliteHunt)
                            until not _G.FarmEliteHunt or not boss.Parent or not Attack.Alive(boss) or (useFix and false) or (not useFix and not questGui.Visible)
                        else
                            wait(5)
                        end
                    else
                        replicated.Remotes.CommF_:InvokeServer("AbandonQuest")
                    end
                end
            end
        end)
    end
end)
