    SQ.Key = function(e) return "Sea1/" .. e.island .. "/" .. e.name end
    SQ.IsDone = function(p, key)
        local v = p[key]
        if v == true then return true end
        return type(v) == "table" and v.Completed == true
    end
    SQ.Sea1 = function() return game.PlaceId == 2753915549 or game.PlaceId == 85211729168715 end
    SQ.Log = function(k, m) if FX.Log then pcall(FX.Log, "secret-" .. k, m) end end
    SQ.Note = function(key, text, level)
        local now = os.clock()
        if now - (SQ.Notified[key] or -1e9) < FX.Cfg.SQNotifyGap then return end
        SQ.Notified[key] = now
        local fh = FX.FH
        if not fh then return end
        if level == "red" and fh.NotifyRed then fh.NotifyRed({ Text = text })
        elseif level == "yellow" and fh.NotifyYellow then fh.NotifyYellow({ Text = text })
        elseif fh.NotifyGreen then fh.NotifyGreen({ Text = text }) end
    end
    SQ.Recount = function()
        local p = SQ.Prog
        if type(p) ~= "table" then return end
        local n, fresh = 0, nil
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            if SQ.IsDone(p, SQ.Key(e)) then
                n = n + 1
                if not SQ.DoneSet[e.name] then
                    SQ.DoneSet[e.name] = true
                    if SQ.Counted then fresh = e end
                end
            end
        end
        SQ.Done = math.min(n, #SQ.List)
        SQ.Counted = true
        if fresh then SQ.Fresh = fresh end
        if not SQ.ShapeLogged then
            SQ.ShapeLogged = true
            local k1
            for k, v in pairs(p) do k1 = k SQ.Log("shape", tostring(k) .. " -> " .. typeof(v)) break end
            if k1 == nil then SQ.Log("shape", "bang tien do rong") end
        end
    end
    SQ.Progress = function(force)
        local now = os.clock()
        if not force and now - SQ.ProgT < FX.Cfg.SQProgressTTL then return SQ.Prog end
        if now < SQ.ProgNext then return SQ.Prog end
        SQ.ProgT = now
        SQ.ProgNext = now + FX.Cfg.SQProgressGap
        local ok, res = pcall(function()
            return game:GetService("ReplicatedStorage").Modules.Net["RF/RequestBonusMomentReplication"]:InvokeServer({ Type = "GetMomentProgress" })
        end)
        if not ok then
            SQ.ProgFail = SQ.ProgFail + 1
            SQ.Status = "REMOTE_FAILED"
            SQ.ProgNext = now + math.min(60, FX.Cfg.SQProgressGap * (2 ^ SQ.ProgFail))
            SQ.Log("progress", tostring(res))
            return SQ.Prog
        end
        if type(res) ~= "table" or type(res.Data) ~= "table" then
            SQ.ProgFail = SQ.ProgFail + 1
            SQ.Status = "MALFORMED"
            SQ.ProgNext = now + math.min(60, FX.Cfg.SQProgressGap * (2 ^ SQ.ProgFail))
            SQ.Log("progress", "response khong phai bang co Data")
            return SQ.Prog
        end
        SQ.ProgFail = 0
        SQ.Status = "OK"
        SQ.Prog = res.Data
        SQ.Recount()
        return SQ.Prog
    end
    SQ.Moment = function(name)
        if SQ.CtlErrT and os.clock() - SQ.CtlErrT < 30 then return nil end
        local ok, r = pcall(function()
            local c = SQ.Ctl
            if c == nil then
                c = require(game:GetService("ReplicatedStorage").Controllers.BonusMomentsController)
                SQ.Ctl = c
            end
            return c:GetLoadedMoments()[name]
        end)
        if ok then SQ.CtlErrT = nil return r end
        SQ.CtlErrT = os.clock()
        SQ.Log("moment", tostring(r))
        return nil
    end
    SQ.IslandPos = function(island)
        if SQ.Isl[island] then return SQ.Isl[island] end
        local ok, r = pcall(function()
            local map = require(game:GetService("ReplicatedStorage").Definitions.Map).findCurrentMap()
            local islands = map and map.Islands or {}
            for _, isl in pairs(islands) do
                if isl.Index.Key == island then
                    local pos, bd = isl.TeleportPoints[1].Position, nil
                    for _, ch in ipairs(workspace._WorldOrigin.Locations:GetChildren()) do
                        if ch.Name == isl.Reference.Location then
                            local m = (ch.Position - isl.World.Position).Magnitude
                            if not bd or m < bd then pos, bd = ch.Position, m end
                        end
                    end
                    return pos + Vector3.new(0, 30, 0)
                end
            end
            return nil
        end)
        if ok and r then SQ.Isl[island] = r return r end
        return nil
    end
    SQ.Go = function(pos, r)
