        if _G.FarmPhaBinh then
            pcall(function()
                if not (plr and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") and Attack.Alive(plr.Character)) then return end
                for _, point in ipairs(PhaBinhPoints) do
                    if not _G.FarmPhaBinh then break end
                    _tp(point)
                    local arrived = false
                    local start = tick()
                    while tick() - start < 12 and not arrived and _G.FarmPhaBinh do
                        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
