UIX.Paragraph(Tabs.Settings, "Para_46", {Title = "Settings / Configure", Content = ""})
do
  local _fxA = _G.FARMX
  if not (_fxA and _fxA.Enable and _fxA.Enable.UIThemeDropdown == false) then
    local _wui = Library and Library.WindUI
    if _wui then
      local _themeNames = {}
      local _okGT, _themes = pcall(function() return _wui:GetThemes() end)
      if _okGT and type(_themes) == "table" then
        for _name in pairs(_themes) do
          _themeNames[#_themeNames + 1] = _name
        end
      end
      table.sort(_themeNames)
      local _darkIdx = table.find(_themeNames, "Dark")
      if _darkIdx and _darkIdx > 1 then
        table.remove(_themeNames, _darkIdx)
        table.insert(_themeNames, 1, "Dark")
      end
      if #_themeNames == 0 then
        _themeNames = {"Dark","Light","Rose","Plant","Red","Indigo","Sky","Violet","Amber","Emerald","Midnight","Crimson"}
      end
      local _curTheme = "Dark"
      local _okCT, _ct = pcall(function() return _wui:GetCurrentTheme() end)
      if _okCT and type(_ct) == "string" and _ct ~= "" then
        _curTheme = _ct
      end
      if not table.find(_themeNames, _curTheme) then
        _curTheme = _themeNames[1] or "Dark"
      end
      local _themeSync = false
      local _lastThemeSet = 0
      UIX.Dropdown(Tabs.Settings, "Settings_UITheme", {
        Title = "Mau UI",
        Description = "Doi giao dien WindUI (Dark, Light, ...)",
        Values = _themeNames,
        Default = _curTheme,
        Callback = function(Value)
          if _themeSync then return end
          local now = os.clock()
          if now - _lastThemeSet < 0.3 then return end
          _lastThemeSet = now
          local _okS, _res = pcall(function() return _wui:SetTheme(Value) end)
          if not _okS or _res == nil then
            if _fxA and _fxA.FH and _fxA.FH.NotifyDot then
              pcall(_fxA.FH.NotifyDot, "r", "Theme khong ton tai: " .. tostring(Value), 1.5)
            end
          else
            if _fxA and _fxA.FH and _fxA.FH.NotifyDot then
              pcall(_fxA.FH.NotifyDot, "g", "Theme: " .. tostring(Value), 1.5)
            end
          end
        end,
      })
      local _origOTC = _wui.OnThemeChangeFunction
      _wui.OnThemeChangeFunction = function(name)
        if _origOTC then pcall(_origOTC, name) end
        _themeSync = true
        pcall(function()
          local _opt = Library.Options["Settings_UITheme"]
          if _opt and _opt.Element then
            pcall(function() _opt.Element:Select(name) end)
          end
        end)
        _themeSync = false
      end
    end
  end
end
