UIX.Toggle(Tabs.Settings, "Settings_AutoDodgeSkillMobs", {
    Title = "Auto Dodge Skill Mobs (ưu tiên cao nhất)",
    Description = "Né kỹ năng bằng BodyVelocity + BodyGyro ngắn hạn, đồng thời nhận diện BodyMover/KiBlast và animation của mob. Cake Prince, Tyrant of the Skies, Terrorshark và Sea Beast được ưu tiên né cao hơn.",
    Default = getgenv().__MaruInitialMobDodge == true,
    Callback = function(v)
        local enabled = v == true
        Settings["Auto Dodge Skill Mobs"] = enabled
        local fxd = _G.FARMX
        if fxd and fxd.Enable then fxd.Enable.MobDodge = enabled end
        if not enabled and fxd and fxd.StopMobDodge then pcall(fxd.StopMobDodge) end
    end,
})

do
    getgenv().__MaruMobDodgeWatchToken = (getgenv().__MaruMobDodgeWatchToken or 0) + 1
    local watcherToken = getgenv().__MaruMobDodgeWatchToken
    if getgenv().__MaruMobDodgeDescConn then
        pcall(function() getgenv().__MaruMobDodgeDescConn:Disconnect() end)
        getgenv().__MaruMobDodgeDescConn = nil
    end
    local enemiesFolder = workspace:FindFirstChild("Enemies") or workspace:WaitForChild("Enemies", 30)
    local lpDodge = game:GetService("Players").LocalPlayer
    local function isAliveMob(mob)
        if not mob or not mob.Parent then return false end
        local hum = mob:FindFirstChildOfClass("Humanoid")
        return hum ~= nil and hum.Health > 0 and mob:FindFirstChild("HumanoidRootPart") ~= nil
    end

    local function isSkillEffect(obj)
        if not obj then return false end
        local name = string.lower(tostring(obj.Name or ""))
        if name == "kiblastfireshort" or name:find("kiblast", 1, true) ~= nil
            or name:find("skill", 1, true) ~= nil or name:find("attack", 1, true) ~= nil
            or name:find("charge", 1, true) ~= nil then
            return true
        end
        -- Preserve Claude's BodyGyro/BodyPosition signal classes. BodyVelocity
        -- is accepted only when it carries a meaningful impulse, to avoid treating
        -- a mob's idle movement controller as an attack cue.
        if obj:IsA("BodyGyro") or obj:IsA("BodyPosition") then return true end
        if obj:IsA("BodyVelocity") then
            local ok, velocity, force = pcall(function()
                return obj.Velocity, obj.MaxForce
            end)
            return ok and velocity.Magnitude >= 30 and force.Magnitude > 0
        end
        return false
    end

    local function owningMob(effect)
        local node = effect
        while node and node.Parent and node.Parent ~= enemiesFolder do
            node = node.Parent
        end
        if node and node.Parent == enemiesFolder then return node end
        return nil
    end

    local function isBossDodgeMob(mob)
        local fxd = _G.FARMX
        return mob ~= nil and fxd and fxd.BossDodgeNames and fxd.BossDodgeNames[mob.Name] == true
    end

    local function beginMobDodge(effect)
        local fxd = _G.FARMX
        if not (fxd and fxd.Enable and fxd.Enable.MobDodge and fxd.MobDodgeTrigger and effect and effect.Parent) then return end
        if not isSkillEffect(effect) then return end
        local st = fxd.MobDodge
        if not st then return end
        st.handled = st.handled or setmetatable({}, { __mode = "k" })
        if st.handled[effect] then return end

        local mob = owningMob(effect)
        if not isAliveMob(mob) then return end
        local target = fxd.AttackingMob
        local root = mob:FindFirstChild("HumanoidRootPart")
        local char = lpDodge.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        if not (root and myRoot) then return end
        if mob ~= target and (root.Position - myRoot.Position).Magnitude > 70 then return end

        st.handled[effect] = true
        local boss = isBossDodgeMob(mob)
        if fxd.TraceAdd then pcall(fxd.TraceAdd, "MOB_DODGE_START", mob.Name, effect.Name) end
        task.spawn(function()
            local started = os.clock()
            local maxHold = (fxd.Cfg and tonumber(fxd.Cfg.MobDodgeMaxHold)) or 14
            local minHold = (fxd.Cfg and tonumber(fxd.Cfg.MobDodgeMinHold)) or 0.5
            repeat
                if _G.FARMX ~= fxd or not (fxd.Enable and fxd.Enable.MobDodge and isAliveMob(mob)) then break end
                fxd.MobDodgeTrigger(0.4, boss, mob, effect)
                task.wait(0.14)
            until not effect.Parent or os.clock() - started >= maxHold

            local elapsed = os.clock() - started
            if elapsed < minHold and fxd.Enable and fxd.Enable.MobDodge then
                fxd.MobDodgeTrigger(minHold - elapsed, boss, mob, effect)
            end
            if fxd.TraceAdd then pcall(fxd.TraceAdd, "MOB_DODGE_END", mob.Name, effect.Name) end
        end)
    end

    if enemiesFolder then
        getgenv().__MaruMobDodgeDescConn = enemiesFolder.DescendantAdded:Connect(beginMobDodge)
    end

    -- The mob may already be using a BodyMover before Attack.Kill selects it.
    task.spawn(function()
        while getgenv().__MaruMobDodgeWatchToken == watcherToken and task.wait(0.12) do
            local fxd = _G.FARMX
            if not (fxd and fxd.Enable and fxd.Enable.MobDodge) then continue end
            local target = fxd.AttackingMob
            local char = lpDodge.Character
            local myRoot = char and char:FindFirstChild("HumanoidRootPart")
            if not (myRoot and enemiesFolder) then continue end
            for _, mob in ipairs(enemiesFolder:GetChildren()) do
                if isAliveMob(mob) then
                    local root = mob:FindFirstChild("HumanoidRootPart")
                    if root and (mob == target or (root.Position - myRoot.Position).Magnitude <= 70) then
                        for _, descendant in ipairs(mob:GetDescendants()) do
                            if isSkillEffect(descendant) then beginMobDodge(descendant) end
                        end
                    end
                end
            end
        end
    end)

    -- AnimationPlayed supplements BodyMover detection; length/loop checks and per-ID
    -- cooldown suppress idle loops and repeated notifications for the same attack animation.
    local animConn, animMob, animFx
    local animLastById = {}
    local function hookMobAnimations(mob)
        local fxd = _G.FARMX
        animFx = fxd
        if animConn then pcall(function() animConn:Disconnect() end) animConn = nil end
        animMob = mob
        table.clear(animLastById)
        if not isAliveMob(mob) then return end
        local hum = mob:FindFirstChildOfClass("Humanoid")
        local animator = hum and hum:FindFirstChildOfClass("Animator")
        if not animator then return end

        local boss = isBossDodgeMob(mob)
        local function considerTrack(track)
            if not track then return end
            task.spawn(function()
                task.wait(0.05)
                local ok, looped, length, speed, playing, animationId = pcall(function()
                    return track.Looped, track.Length, track.Speed, track.IsPlaying,
                        track.Animation and track.Animation.AnimationId or ""
                end)
                if not ok or looped or not playing then return end
                local minLength = boss and 0.6 or 0.9
                local cfgLength = fxd and fxd.Cfg and (boss and fxd.Cfg.MobDodgeBossAnimMinLength or fxd.Cfg.MobDodgeAnimMinLength)
                if type(cfgLength) == "number" then minLength = cfgLength end
                if type(length) ~= "number" or length < minLength then return end

                animationId = tostring(animationId or "")
                if animationId == "" then return end
                local now = os.clock()
                local cooldown = boss and 0.65 or 0.9
                if now - (animLastById[animationId] or 0) < cooldown then return end
                animLastById[animationId] = now
                task.wait(0.05)
                local stillOk, stillPlaying = pcall(function() return track.IsPlaying end)
                if not stillOk or not stillPlaying then return end

                local fxdNow = _G.FARMX
                if not (fxdNow and fxdNow.Enable and fxdNow.Enable.MobDodge and fxdNow.MobDodgeTrigger)
                    or fxdNow.AttackingMob ~= mob or not isAliveMob(mob) then return end
                local playback = math.max(math.abs(tonumber(speed) or 1), 0.1)
                local activeFor = math.clamp(length / playback + 0.25, 0.6, 2.5)
                fxdNow.MobDodgeTrigger(activeFor, boss, mob) -- AnimationPlayed cooldown is per ID; allow cached tracks to trigger again on a later swing.
            end)
        end

        animConn = animator.AnimationPlayed:Connect(considerTrack)
        local okTracks, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
        if okTracks and type(tracks) == "table" then
            for _, track in ipairs(tracks) do considerTrack(track) end
        end
    end

    task.spawn(function()
        while getgenv().__MaruMobDodgeWatchToken == watcherToken and task.wait(0.2) do
            local fxd = _G.FARMX
            local target = fxd and fxd.Enable and fxd.Enable.MobDodge and fxd.AttackingMob or nil
            local hum = target and target:FindFirstChildOfClass("Humanoid")
            local animatorReady = hum and hum:FindFirstChildOfClass("Animator") ~= nil
            if target ~= animMob or fxd ~= animFx or (target and not animConn and animatorReady) then
                pcall(hookMobAnimations, target)
            end
        end
        if animConn then pcall(function() animConn:Disconnect() end) animConn = nil end
    end)
end
-- [QM-HW] P81 Halloween event: Pumpkin Snowman + Trick Or Treat + Gacha | nguon: main1.lua 12084-12175, 12255-12915, 21671-21719 | gan tai: sau Jack o' Lantern
do
    local lp = game:GetService("Players").LocalPlayer
    local hwTab = Tabs.Halloween
    local function getRoot()
        local c = lp.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end
    local function normName(s)
        return (string.lower(tostring(s or "")):gsub("[^%w]", ""))
    end
    local function pivotOf(o)
        if not o or not o.Parent then return nil end
        if o:IsA("Model") then return o:GetPivot() elseif o:IsA("BasePart") then return o.CFrame end
        local part = o:FindFirstChildWhichIsA("BasePart", true)
        return part and part.CFrame or nil
    end
    local function owned(name)
        local f = _G.FARMX
        return not (f and f.NotOwner and f.NotOwner(name))
    end
    pcall(function()
        local FHx = _G.FARMX and _G.FARMX.FH
        if FHx and FHx.Register then
            FHx.Register({ name = "HWPumpkinSnowman", tier = 11, cls = "exclusive", flags = {"_G.AutoPumpkinSnowman"}, ui = {"Quests_AutoPumpkinSnowman"}, idle = true })
            FHx.Register({ name = "HWTrickTreat", tier = 13, cls = "exclusive", flags = {"_G.AutoTrickOrTreat"}, ui = {"Quests_AutoTrickOrTreat"}, idle = true })
            FHx.Register({ name = "HWDapperJack", tier = 13, cls = "exclusive", flags = {"_G.AutoDapperJack"}, ui = {"Quests_AutoDapperJack"}, idle = true })
        end
    end)
    UIX.Paragraph(hwTab, "Para_HW", { Title = "Sự kiện Halloween (Full)", Content = "Pumpkin Snowman (đập PumpkinPatch), Trick Or Treat (cửa thường + cửa cảnh, đánh mob/Hellfire Gas, 10 phút đầu mỗi giờ), Gacha và boss Dapper Jack." })

    -- ===== Pumpkin Snowman =====
    local SNOW_SEARCH_RADIUS = 2400
    local snowScanAt, snowScanTarget = 0, nil
    local function findSnow()
        local h = getRoot()
        local en = workspace:FindFirstChild("Enemies")
        if not h or not en then snowScanTarget = nil return nil end
        local now = os.clock()
        if now - snowScanAt < 0.25 then
            if not snowScanTarget then return nil end
            if snowScanTarget.Parent then
                local cachedHum = snowScanTarget:FindFirstChildOfClass("Humanoid")
                local cachedRoot = snowScanTarget:FindFirstChild("HumanoidRootPart")
                if cachedHum and cachedHum.Health > 0 and cachedRoot
                    and (cachedRoot.Position - h.Position).Magnitude <= SNOW_SEARCH_RADIUS then
                    return snowScanTarget
                end
            end
        end
        snowScanAt, snowScanTarget = now, nil
        local best, bd = nil, SNOW_SEARCH_RADIUS
        local seen = setmetatable({}, { __mode = "k" })
        local function consider(m)
            if not m or seen[m] or not m:IsA("Model") then return end
            seen[m] = true
            if normName(m.Name) ~= "pumpkinsnowman" then return end
            local hum = m:FindFirstChildOfClass("Humanoid")
            local r = m:FindFirstChild("HumanoidRootPart")
            if hum and hum.Health > 0 and r then
                local d = (r.Position - h.Position).Magnitude
                if d <= bd then best, bd = m, d end
            end
        end
        for _, m in ipairs(en:GetChildren()) do consider(m) end
        if not best then
            for _, m in ipairs(en:GetDescendants()) do
                if m:IsA("Model") then consider(m) end
            end
        end
        snowScanTarget = best
        return best
    end
    local PATCH_SEARCH_RADIUS = 4000
    local patchScanAt, patchScanTarget = 0, nil
    local function findPumpkinPatch()
        local h = getRoot()
        if not h then patchScanTarget = nil return nil end
        local now = os.clock()
        if now - patchScanAt < 0.5 then
            if patchScanTarget and patchScanTarget.Parent then
                local cachedCF = pivotOf(patchScanTarget)
                if cachedCF and (cachedCF.Position - h.Position).Magnitude <= PATCH_SEARCH_RADIUS then
                    return patchScanTarget
                end
            elseif not patchScanTarget then
                return nil
            end
        end
        patchScanAt, patchScanTarget = now, nil
        local map = workspace:FindFirstChild("Map")
        local hunt = workspace:FindFirstChild("PumpkinHunt")
        local roots = { workspace }
        if hunt then roots[#roots + 1] = hunt end
        if map then roots[#roots + 1] = map end
        local seen = setmetatable({}, { __mode = "k" })
        local best, bestD
        local function consider(obj)
            if not obj or seen[obj] then return end
            seen[obj] = true
            if obj.Name ~= "PumpkinPatch" or not (obj:IsA("Model") or obj:IsA("BasePart") or obj:IsA("Folder")) then return end
            local cf = pivotOf(obj)
            if not cf then return end
            local d = (cf.Position - h.Position).Magnitude
            if d <= PATCH_SEARCH_RADIUS and (not bestD or d < bestD) then
                best, bestD = obj, d
            end
        end
        -- Direct children are checked first across the known event roots.
        for _, root in ipairs(roots) do
            if root then
                if root.Name == "PumpkinPatch" then consider(root) end
                consider(root:FindFirstChild("PumpkinPatch"))
            end
        end
        -- Then search nested descendants only in the event/map roots, not the entire workspace tree.
        local deepRoots = {}
        if hunt then deepRoots[#deepRoots + 1] = hunt end
        if map then deepRoots[#deepRoots + 1] = map end
        for _, root in ipairs(deepRoots) do
            if root then
                for _, obj in ipairs(root:GetDescendants()) do
                    if obj.Name == "PumpkinPatch" then consider(obj) end
                end
            end
        end
        patchScanTarget = best
        return best
    end
    local function patchHit(patch)
        local h = getRoot()
        if not (h and patch and patch.Parent) then return end
        local now = os.clock()
        if now - (getgenv().__MaruPatchHitAt or 0) < 0.1 then return end
        getgenv().__MaruPatchHitAt = now
        pcall(EquipWeapon, _G.SelectWeapon)
        local hits, first = {}, nil
        local function add(o)
            if o:IsA("BasePart") and (o.Position - h.Position).Magnitude <= 120 then
                first = first or o
                hits[#hits + 1] = { o:FindFirstAncestorOfClass("Model") or o, o }
            end
        end
        add(patch)
        for _, o in ipairs(patch:GetDescendants()) do add(o) end
        if first then
            pcall(function()
                local net = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
                net = net and net:FindFirstChild("Net")
                local regAtk = net and net:FindFirstChild("RE/RegisterAttack")
                local regHit = net and net:FindFirstChild("RE/RegisterHit")
                if regAtk and regHit then
                    regAtk:FireServer(0)
                    regHit:FireServer(first, hits)
                end
            end)
        end
        pcall(function()
            local tool = lp.Character and lp.Character:FindFirstChildOfClass("Tool")
            if tool then tool:Activate() end
        end)
    end
