    -- ===== Trick Or Treat =====
    local ttVisited = {}
    local doorCache, doorCacheAt = nil, 0
    local function inWindow()
        return (tonumber(os.date("%M")) or 0) < 10
    end
    local function collectDoors()
        local now = tick()
        if doorCache and now - doorCacheAt < 1 then
            local cached = {}
            for _, door in ipairs(doorCache) do
                if door and door.Parent then cached[#cached + 1] = door end
            end
            if #cached == #doorCache then return cached end
        end
        local list, seen = {}, setmetatable({}, { __mode = "k" })
        local map = workspace:FindFirstChild("Map")
        if not map then doorCache, doorCacheAt = list, now return list end
        local function addDoor(d)
            if d and not seen[d] and d.Name == "HalloweenDoor"
                and (d:IsA("Model") or d:IsA("BasePart")) then
                seen[d] = true
                list[#list + 1] = d
            end
        end
        for _, d in ipairs(map:GetDescendants()) do addDoor(d) end
        local extraRoots = { { "Turtle", "IslandModel", "HalloweenHotel" }, { "Dressrosa", "Dressrosa" } }
        for _, path in ipairs(extraRoots) do
            local node = map
            for _, nm in ipairs(path) do node = node and node:FindFirstChild(nm) end
            if node then
                if node.Name == "HalloweenDoor" then addDoor(node) end
                for _, d in ipairs(node:GetDescendants()) do addDoor(d) end
            end
        end
        doorCache, doorCacheAt = list, now
        return list
    end
    local function nearestDoor()
        local h = getRoot()
        if not h then return nil end
        local best, bd = nil, math.huge
        for _, d in ipairs(collectDoors()) do
            if (ttVisited[d] or 0) < tick() then
                local cf = pivotOf(d)
                if cf then
                    local dist = (cf.Position - h.Position).Magnitude
                    if dist < bd then best, bd = d, dist end
                end
            end
        end
        return best
    end
    local lastE = 0
    local function pressE(door)
        if os.clock() - lastE < 0.6 then return end
        lastE = os.clock()
        local vim = game:GetService("VirtualInputManager")
        local prompt = door:FindFirstChildWhichIsA("ProximityPrompt", true)
        local hold = prompt and prompt.HoldDuration or 0
        if prompt then
            pcall(function() prompt.RequiresLineOfSight = false end)
            if fireproximityprompt and prompt.Enabled then
                pcall(fireproximityprompt, prompt, hold > 0 and (hold + 0.1) or 1)
            end
        end
        vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
        task.wait(0.05 + hold)
        vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
    end
    local function promptShown(door)
        local prompt = door and door:FindFirstChildWhichIsA("ProximityPrompt", true)
        if not prompt then return false end
        pcall(function() prompt.RequiresLineOfSight = false end)
        return prompt.Enabled
    end
    local function getDialogue()
        local pg = lp:FindFirstChild("PlayerGui")
        local dg = pg and pg:FindFirstChild("DialogueGui")
        if not dg or (dg:IsA("ScreenGui") and not dg.Enabled) then return nil end
        local fallbackSc
        for _, ol in ipairs(dg:GetDescendants()) do
            if ol.Name == "optionsList" then
                local sc = ol:FindFirstChild("scroller")
                if sc then
                    fallbackSc = fallbackSc or sc
                    for _, o in ipairs(sc:GetChildren()) do
                        if o:IsA("GuiObject") and string.find(o.Name, "option1", 1, true) and not string.find(o.Name, "option1%d")
                            and o.Visible and o.AbsoluteSize.X > 0 and o.AbsoluteSize.Y > 0 then
                            return sc, o
                        end
                    end
                end
            end
        end
        return fallbackSc, nil
    end
    local function getDialogueFrame()
        local pg = lp:FindFirstChild("PlayerGui")
        local dg = pg and pg:FindFirstChild("DialogueGui")
        if not dg or (dg:IsA("ScreenGui") and not dg.Enabled) then return nil end
        for _, c in ipairs(dg:GetChildren()) do
            if string.sub(c.Name, 1, 6) == "table:" and (not c:IsA("GuiObject") or c.Visible) then
                return c
            end
        end
        return nil
    end
    local function clickGui(o)
        local btn = o:IsA("GuiButton") and o or o:FindFirstChildWhichIsA("GuiButton", true)
        if btn and firesignal then
            for _, sig in ipairs({ "MouseButton1Click", "Activated" }) do
                pcall(function() firesignal(btn[sig]) end)
            end
        end
        local vim = game:GetService("VirtualInputManager")
        local pos = o.AbsolutePosition + o.AbsoluteSize / 2
        local sg = o:FindFirstAncestorWhichIsA("ScreenGui")
        if sg and not sg.IgnoreGuiInset then
            pos = pos + game:GetService("GuiService"):GetGuiInset()
        end
        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 1)
        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 1)
    end
    local TT = {
        tok = 0, busyAt = 0, realmAt = -1e9, realmVal = false, busyConn = nil,
        ignore = setmetatable({}, { __mode = "k" }),
        sceneSkip = setmetatable({}, { __mode = "k" }),
        BUSY = { "still busy with another door", "nobody is home" },
        REVISIT = 120, STAND = 3, SIDE_SWITCH = 3, MOB_RANGE = 500, MOB_TIMEOUT = 60,
        SCENE_FAR = 1000, SCENE_KNOCK = 6, SCENE_RETRY = 6, CLICK = 0.25, SPACE = 0.1,
    }

    function TT.alive(m)
        if not m or not m.Parent then return false end
        local hum = m:FindFirstChildOfClass("Humanoid")
        return hum ~= nil and hum.Health > 0 and m:FindFirstChild("HumanoidRootPart") ~= nil
    end

    -- bao cho FH biet TT dang ban (khong bi idle-release khi dung doi thoai / danh trong canh)
    function TT.pulse()
        local f = _G.FARMX
        local o = f and f.FH and f.FH.Owner
        if o and o.name == "HWTrickTreat" then o.lastMoveAt = os.clock() end
    end

    -- cua thuong: chi trong 10 phut dau gio; canh / realm / mob: khong cat giua tran
    function TT.valid(tok)
        return _G.AutoTrickOrTreat == true and TT.tok == tok and inWindow() and owned("HWTrickTreat")
    end
    function TT.fightValid(tok)
        return _G.AutoTrickOrTreat == true and TT.tok == tok and owned("HWTrickTreat")
    end

    -- thong bao "ban / khong co nha": chi nghe khi TT dang bat
    function TT.isBusyText(txt)
        if type(txt) ~= "string" then return false end
        local low = string.lower(txt)
        for _, p in ipairs(TT.BUSY) do
            if string.find(low, p, 1, true) then return true end
        end
        return false
    end
    function TT.hookLabel(o)
        if not o:IsA("TextLabel") then return end
        if TT.isBusyText(o.Text) then TT.busyAt = os.clock() end
        o:GetPropertyChangedSignal("Text"):Connect(function()
            if _G.AutoTrickOrTreat and TT.isBusyText(o.Text) then TT.busyAt = os.clock() end
        end)
    end
    function TT.setBusyHook(on)
        if TT.busyConn then
            pcall(function() TT.busyConn:Disconnect() end)
            TT.busyConn = nil
        end
        if not on then return end
        local pg = lp:FindFirstChild("PlayerGui")
        if pg then
            TT.busyConn = pg.DescendantAdded:Connect(function(o) pcall(TT.hookLabel, o) end)
        end
    end

    -- mob quanh cua: Hellfire Gas uu tien (khong gioi han tam), bo Jack o' Lantern / Pumpkin Snowman (farm rieng)
    function TT.findHellfireGas()
        local now = tick()
        local cached = TT.GAS_CACHE
        if now - (TT.GAS_CACHE_AT or -1e9) < 0.75 then
            if cached and TT.alive(cached) then return cached end
            return nil
        end
        TT.GAS_CACHE, TT.GAS_CACHE_AT = nil, now
        local en = workspace:FindFirstChild("Enemies")
        local map = workspace:FindFirstChild("Map")
        local roots = {}
        if en then roots[#roots + 1] = en end
        roots[#roots + 1] = workspace
        if map then roots[#roots + 1] = map end
        local function direct(root)
            if not root then return nil end
            local exact = root:FindFirstChild("Hellfire Gas")
            if TT.alive(exact) then return exact end
            for _, child in ipairs(root:GetChildren()) do
                if normName(child.Name) == "hellfiregas" and TT.alive(child) then return child end
            end
            return nil
        end
        -- Direct folders/children first for fast event detection.
        for _, root in ipairs(roots) do
            local found = direct(root)
            if found then TT.GAS_CACHE = found return found end
        end
        -- Fallback: nested model scan with normalized names and deduplication.
        local best, bestD
        local h = getRoot()
        local seen = setmetatable({}, { __mode = "k" })
        local deepRoots = {}
        if en then deepRoots[#deepRoots + 1] = en end
        if map then deepRoots[#deepRoots + 1] = map end
        deepRoots[#deepRoots + 1] = workspace
        for _, root in ipairs(deepRoots) do
            if root then
                for _, obj in ipairs(root:GetDescendants()) do
                    if not seen[obj] then
                        seen[obj] = true
                        if obj:IsA("Model") and normName(obj.Name) == "hellfiregas" and TT.alive(obj) then
                            local r = obj:FindFirstChild("HumanoidRootPart")
                            local d = h and r and (r.Position - h.Position).Magnitude or 0
                            if not h or (r and d <= 6000) then
                                if not bestD or d < bestD then best, bestD = obj, d end
                            end
                        end
                    end
                end
            end
        end
        TT.GAS_CACHE = best
        return best
    end
    function TT.findMob()
        if not _G.SelectWeapon then return nil end
        local h = getRoot()
        local en = workspace:FindFirstChild("Enemies")
        if not h then TT.MOB_CACHE = nil return nil end
        local now = tick()
        if TT.MOB_CACHE and now - TT.MOB_CACHE_AT < 0.2 and TT.alive(TT.MOB_CACHE) then
            local cachedRoot = TT.MOB_CACHE:FindFirstChild("HumanoidRootPart")
            local cachedName = normName(TT.MOB_CACHE.Name)
            local notIgnored = (TT.ignore[TT.MOB_CACHE] or 0) < now
            if cachedRoot and notIgnored and cachedName ~= "jackolantern" and cachedName ~= "pumpkinsnowman"
                and (cachedName == "hellfiregas" or (cachedRoot.Position - h.Position).Magnitude <= TT.MOB_RANGE) then
                return TT.MOB_CACHE
            end
        end
        TT.MOB_CACHE, TT.MOB_CACHE_AT = nil, now
        local gas = TT.findHellfireGas()
        if TT.alive(gas) then TT.MOB_CACHE = gas return gas end
        if not en then return nil end
        local best, bd = nil, TT.MOB_RANGE
        local seen = setmetatable({}, { __mode = "k" })
        local function consider(m)
            if not m or seen[m] or not m:IsA("Model") then return end
            seen[m] = true
            local n = normName(m.Name)
            if (TT.ignore[m] or 0) >= now or n == "jackolantern" or n == "pumpkinsnowman" or not TT.alive(m) then return end
            local root = m:FindFirstChild("HumanoidRootPart")
            local d = root and (root.Position - h.Position).Magnitude
            if d and d <= bd then best, bd = m, d end
        end
        for _, m in ipairs(en:GetChildren()) do consider(m) end
        if not best then
            for _, m in ipairs(en:GetDescendants()) do
                if m:IsA("Model") then consider(m) end
            end
        end
        TT.MOB_CACHE = best
        return best
    end

    function TT.pressSpace()
        local vim = game:GetService("VirtualInputManager")
        vim:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
        task.wait(0.03)
        vim:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
    end

    function TT.fight(mob, tok, spam, noRange)
        local boss = mob.Name == "Hellfire Gas"
        noRange = noRange or boss
        local t0, lastSpace = tick(), 0
        pcall(Attack.Kill, mob, function()
            if not TT.fightValid(tok) then return false end
            TT.pulse()
            if spam and tick() - lastSpace >= TT.SPACE then
                lastSpace = tick()
                task.spawn(pcall, TT.pressSpace)
            end
            if not boss and tick() - t0 > TT.MOB_TIMEOUT then
                TT.ignore[mob] = tick() + 30
                return false
            end
            local h, r = getRoot(), mob:FindFirstChild("HumanoidRootPart")
            if not (h and r) then return false end
            if not noRange and (r.Position - h.Position).Magnitude > TT.MOB_RANGE then return false end
            return true
        end)
        -- Attack.Kill thoat ngay ma mob van song (khong danh duoc) -> bo qua mot luc, tranh quay vong
        if not boss and tick() - t0 < 0.3 and TT.alive(mob) and TT.fightValid(tok) then
            TT.ignore[mob] = tick() + 5
        end
    end

    -- 4 huong quanh cua, xep theo raycast: it tran + khong bi chan truoc
    function TT.standDirs(door, cf, h)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { lp.Character, door }
        params.IgnoreWater = true
        local raw = { cf.LookVector, -cf.LookVector, cf.RightVector, -cf.RightVector }
        local cands = {}
        for _, v in ipairs(raw) do
            local d = Vector3.new(v.X, 0, v.Z)
            if d.Magnitude > 0.1 then
                d = d.Unit
                local dup = false
                for _, c in ipairs(cands) do
                    if c.dir:Dot(d) > 0.99 then dup = true break end
                end
                if not dup then
                    local pos = cf.Position + d * TT.STAND
                    local score = 0
                    pcall(function()
                        local up = workspace:Raycast(pos + Vector3.new(0, 2, 0), Vector3.new(0, 60, 0), params)
                        if up and up.Instance.Transparency < 1 then score = score + 2 end
                        if workspace:Raycast(pos, (cf.Position - pos) * 0.8, params) then score = score + 3 end
                    end)
                    score = score + (h.Position - pos).Magnitude * 0.001
                    cands[#cands + 1] = { dir = d, score = score }
                end
            end
        end
        table.sort(cands, function(a, b) return a.score < b.score end)
        local out = {}
        for _, c in ipairs(cands) do out[#out + 1] = c.dir end
        if #out == 0 then out[1] = Vector3.new(0, 0, 1) end
        return out
    end

    -- nhan vat co nam trong khung bao cua obj (Model:GetBoundingBox hoac gop BasePart) khong
    function TT.boxHas(obj)
        local h = getRoot()
        if not (h and obj) then return false end
        local ok, inside = pcall(function()
            local cf, size
            if obj:IsA("Model") then
                cf, size = obj:GetBoundingBox()
            else
                local mn, mx
                for _, d in ipairs(obj:GetDescendants()) do
                    if d:IsA("BasePart") then
                        local lo, hi = d.Position - d.Size / 2, d.Position + d.Size / 2
                        mn = mn and Vector3.new(math.min(mn.X, lo.X), math.min(mn.Y, lo.Y), math.min(mn.Z, lo.Z)) or lo
                        mx = mx and Vector3.new(math.max(mx.X, hi.X), math.max(mx.Y, hi.Y), math.max(mx.Z, hi.Z)) or hi
                    end
                end
                if not mn then return false end
                cf, size = CFrame.new((mn + mx) / 2), mx - mn
            end
            local rel = cf:PointToObjectSpace(h.Position)
            return math.abs(rel.X) <= size.X / 2 + 100 and math.abs(rel.Y) <= size.Y / 2 + 180 and math.abs(rel.Z) <= size.Z / 2 + 100
        end)
        return ok and inside == true
    end
    function TT.inRealm()
        local now = os.clock()
        if now - TT.realmAt < 0.25 then return TT.realmVal end
        TT.realmAt = now
        local map = workspace:FindFirstChild("Map")
        TT.realmVal = TT.boxHas(map and map:FindFirstChild("HellfireBossRealm"))
        return TT.realmVal
    end

    function TT.findScene()
        for _, d in ipairs(collectDoors()) do
            local sw = d:FindFirstChild("SceneWindow")
            if sw and (TT.sceneSkip[d] or 0) < tick() and pivotOf(sw) then return d, sw end
        end
        return nil
    end

    function TT.flyBack(pos, tok)
        local t0 = tick()
        while TT.fightValid(tok) and tick() - t0 < 15 do
            task.wait()
            local h = getRoot()
            if not h or (h.Position - pos).Magnitude <= 8 then return end
            pcall(_tp, CFrame.new(pos))
        end
    end

    function TT.sceneFight(oldPos, tok)
        while TT.fightValid(tok) do
            task.wait(0.1)
            TT.pulse()
            local h = getRoot()
            if h then
                if not TT.inRealm() and (h.Position - oldPos).Magnitude < TT.SCENE_FAR then return end
                local mob = TT.findMob()
                if mob then TT.fight(mob, tok, true) end
            end
        end
    end

    function TT.runScene(door, sw, tok)
        local h0, swCf = getRoot(), pivotOf(sw)
        if not (h0 and swCf) then return end
        local oldPos = h0.Position
        local pressTarget = sw:FindFirstChildWhichIsA("ProximityPrompt", true) and sw or door
        for _ = 1, TT.SCENE_RETRY do
            if not TT.fightValid(tok) then return end
            local teleported = false
            local t0, arrived = tick(), nil
            local lastE, lastScreen, lastOpt = 0, 0, 0
            local stand
            while TT.fightValid(tok) do
                task.wait()
                TT.pulse()
                local exit = false
                repeat
                    local h, cf = getRoot(), pivotOf(sw)
                    if not h then exit = true break end
                    if TT.inRealm() or (h.Position - oldPos).Magnitude > TT.SCENE_FAR then
                        teleported, exit = true, true
                        break
                    end
                    if not cf then exit = true break end
                    local gate = TT.findHellfireGas()
                    if TT.alive(gate) then
                        TT.fight(gate, tok, nil, true)
                        t0, arrived = tick(), nil
                        break
                    end
                    local mob = TT.findMob()
                    if mob then
                        TT.fight(mob, tok)
                        t0, arrived = tick(), nil
                        break
                    end
                    if not stand then
                        local dir = h.Position - cf.Position
                        dir = Vector3.new(dir.X, 0, dir.Z)
                        dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.new(0, 0, 1)
                        stand = CFrame.lookAt(cf.Position + dir * 3, cf.Position)
                    end
                    pcall(_tp, stand)
                    local _, o1 = getDialogue()
                    if o1 then
                        if os.clock() - lastOpt >= TT.CLICK then
                            lastOpt = os.clock()
                            pcall(clickGui, o1)
                        end
                    else
                        local fr = getDialogueFrame()
                        if fr and os.clock() - lastScreen >= TT.CLICK then
                            lastScreen = os.clock()
                            pcall(clickGui, fr)
                        end
                    end
                    if (h.Position - stand.Position).Magnitude <= 8 then
                        arrived = arrived or os.clock()
                        if TT.busyAt >= arrived then exit = true break end
                        if os.clock() - lastE >= TT.CLICK and promptShown(pressTarget) then
                            lastE = os.clock()
                            task.spawn(pcall, pressE, pressTarget)
                        end
                        if os.clock() - arrived > TT.SCENE_KNOCK then exit = true break end
                    elseif tick() - t0 > 40 then
                        exit = true
                    end
                until true
                if exit then break end
            end
            if teleported then
                TT.sceneFight(oldPos, tok)
                TT.sceneSkip[door] = tick() + TT.REVISIT
                return
            end
            if not pivotOf(sw) then return end
            TT.flyBack(oldPos, tok)
        end
        TT.sceneSkip[door] = tick() + TT.REVISIT
    end

    -- cua thuong: bay toi, dung huong tot nhat, bam E, chon option1; ban / im lang 3s thi doi huong
    function TT.visitDoor(door, tok)
        local list, idx, switches, arrived, goneAt
        local sawDialogue = false
        local lastE, lastClick, lastScreen = 0, 0, 0
        local startT = os.clock()
        while TT.valid(tok) and os.clock() - startT < 60 do
            task.wait()
            TT.pulse()
            local h, cf = getRoot(), pivotOf(door)
            if not (h and cf) then return end
            local mob = TT.findMob()
            if mob then
                TT.fight(mob, tok)
                arrived, startT = nil, os.clock()
            else
                if not list then list, idx, switches = TT.standDirs(door, cf, h), 1, 0 end
                local stand = CFrame.lookAt(cf.Position + list[idx] * TT.STAND, cf.Position)
                local sc, opt = getDialogue()
                if not opt and os.clock() - lastScreen >= TT.CLICK then
                    local fr = getDialogueFrame()
                    if fr then
                        lastScreen = os.clock()
                        pcall(clickGui, fr)
                    end
                end
                if sc then
                    sawDialogue, goneAt = true, nil
                    pcall(_tp, stand)
                    if opt and os.clock() - lastClick >= TT.CLICK then
                        lastClick = os.clock()
                        pcall(clickGui, opt)
                    end
                elseif sawDialogue then
                    goneAt = goneAt or os.clock()
                    if os.clock() - goneAt > 1.5 then
                        local w0 = os.clock()
                        while TT.valid(tok) and os.clock() - w0 < 3 and not door:FindFirstChild("SceneWindow") do
                            task.wait(0.1)
                        end
                        return
                    end
                else
                    pcall(_tp, stand)
                    if (h.Position - stand.Position).Magnitude <= 8 then
                        arrived = arrived or os.clock()
                        if TT.busyAt >= arrived then return end
                        if os.clock() - lastE >= TT.CLICK and promptShown(door) then
                            lastE = os.clock()
                            task.spawn(pcall, pressE, door)
                        end
                        if os.clock() - arrived > TT.SIDE_SWITCH then
                            switches = switches + 1
                            if switches >= #list then return end
                            idx = idx % #list + 1
                            arrived = nil
                        end
                    else
                        arrived = nil
                    end
                end
            end
        end
    end

    function TT.ghost(tok)
        local function items()
            local list = {}
            local root = workspace:FindFirstChild("GhostChase")
            if root then
                for _, c in ipairs(root:GetChildren()) do
                    if c:IsA("Model") or c:IsA("BasePart") then list[#list + 1] = c end
                end
            end
            return list
        end
        if tick() < (_G.__TTGhostSkip or 0) or #items() == 0 then return false end
        local visited = setmetatable({}, { __mode = "k" })
        local startT = tick()
        while TT.valid(tok) and tick() - startT < 120 do
            task.wait()
            TT.pulse()
            local h = getRoot()
            if not h then return true end
            local list = items()
            if #list == 0 then return true end
            local best, bd
            for _ = 1, 2 do
                for _, c in ipairs(list) do
                    local cf = not visited[c] and pivotOf(c)
                    if cf then
                        local d = (cf.Position - h.Position).Magnitude
                        if not bd or d < bd then best, bd = c, d end
                    end
                end
                if best then break end
                table.clear(visited)
            end
            if not best then
                pcall(_tp, h.CFrame)
            else
                visited[best] = true
                local t1 = tick()
                while TT.valid(tok) and best.Parent and tick() - t1 < 0.2 do
                    local cf = pivotOf(best)
                    if not getRoot() or not cf then break end
                    pcall(_tp, CFrame.new(cf.Position))
                    task.wait()
                end
            end
        end
        if TT.valid(tok) and #items() > 0 then _G.__TTGhostSkip = tick() + 30 end
        return true
    end

    UIX.Toggle(hwTab, "Quests_AutoTrickOrTreat", {
        Title = "Auto Trick Or Treat",
        Description = "Bay tới HalloweenDoor gần nhất; tìm Hellfire Gas trực tiếp và lồng sâu trong Enemies/Map/workspace; xử lý realm, mob quanh cửa và GhostChase trong khung giờ event.",
        Default = false,
        Callback = function(v)
            _G.AutoTrickOrTreat = v
            TT.tok = TT.tok + 1
            TT.setBusyHook(v == true)
            if not v then return end
            local tok = TT.tok
            task.spawn(function()
                while _G.AutoTrickOrTreat and TT.tok == tok do
                    task.wait(0.1)
                    pcall(function()
                        if TT.fightValid(tok) and TT.inRealm() then
                            TT.pulse()
                            local rmob = TT.findMob()
                            if rmob then
                                TT.fight(rmob, tok)
                            else
                                local rh = getRoot()
                                if rh then pcall(_tp, rh.CFrame) end
                            end
                            return
                        end
                        if not TT.valid(tok) then return end
                        if TT.ghost(tok) then return end
                        local sceneDoor, sceneWin = TT.findScene()
                        local door = (not sceneDoor) and nearestDoor() or nil
                        if not sceneDoor and not door then
                            task.wait(1)
                            return
                        end
                        TT.pulse()
                        local mob = TT.findMob()
                        if mob then
                            TT.fight(mob, tok)
                            return
                        end
                        if sceneDoor then
                            TT.runScene(sceneDoor, sceneWin, tok)
                            return
                        end
                        ttVisited[door] = tick() + TT.REVISIT
                        TT.visitDoor(door, tok)
                    end)
                end
            end)
        end,
    })

    -- ===== Auto Summon + Farm Boss Dapper Jack =====
    local DJ_BOSS, DJ_GATE = "Dapper Jack", "Hellfire Gas"
    local djTok = 0
    local function alive(m)
        if not m or not m.Parent then return false end
        local hum = m:FindFirstChildOfClass("Humanoid")
        return hum ~= nil and hum.Health > 0 and m:FindFirstChild("HumanoidRootPart") ~= nil
    end
    local function djIslandCF()
        if World1 then
            return CFrame.new(-703.16748, 9.55188751, 1575.1864)
        elseif World2 then
            return CFrame.new(-385.250916, 73.0458984, 297.388397)
        elseif World3 then
            return CFrame.new(-12548, 337, -7481)
        end
        return nil
    end
    local DJ_SEARCH_RADIUS = 6000
    local DJ_ARENA_PAD_XZ, DJ_ARENA_PAD_Y = 100, 180
    local DJ_INTERACT_RANGE = 16
    local djScanCache = setmetatable({}, { __mode = "k" })
    local function djFindNested(root, name, maxDistance, requireAlive)
        if not root then return nil end
        local h = getRoot()
        local targetName = normName(name)
        local function inRange(obj)
            if not obj or (requireAlive and not alive(obj)) then return false end
            local cf = pivotOf(obj)
            if not cf then return false end
            if not h or not maxDistance then return true end
            return (cf.Position - h.Position).Magnitude <= maxDistance
        end
        local direct = root:FindFirstChild(name)
        if direct and inRange(direct) then return direct end
        for _, child in ipairs(root:GetChildren()) do
            if normName(child.Name) == targetName and inRange(child) then return child end
        end
        local now = os.clock()
        local perRoot = djScanCache[root]
        if not perRoot then perRoot = {}; djScanCache[root] = perRoot end
        local state = perRoot[name]
        if state and now - state.at < 0.75 then
            local cached = state.object
            if cached and cached.Parent and inRange(cached) then return cached end
            return nil
        end
        local best, bestD
        for _, obj in ipairs(root:GetDescendants()) do
            if normName(obj.Name) == targetName and (obj:IsA("Model") or obj:IsA("BasePart"))
                and inRange(obj) then
                local cf = pivotOf(obj)
                local d = h and cf and (cf.Position - h.Position).Magnitude or 0
                if not bestD or d < bestD then best, bestD = obj, d end
            end
        end
        perRoot[name] = { at = now, object = best }
        return best
    end
    local function djDirectNamed(root, name, requireAlive, maxDistance)
        if not root then return nil end
        local h = getRoot()
        local function valid(obj)
            if not obj or (requireAlive and not alive(obj)) then return false end
            local cf = pivotOf(obj)
            if not cf then return false end
            return not h or not maxDistance or (cf.Position - h.Position).Magnitude <= maxDistance
        end
        local direct = root:FindFirstChild(name)
        if valid(direct) then return direct end
        local target = normName(name)
        for _, child in ipairs(root:GetChildren()) do
            if normName(child.Name) == target and valid(child) then return child end
        end
        return nil
    end
    local function djFindNamed(name)
        local en = workspace:FindFirstChild("Enemies")
        local npcs = workspace:FindFirstChild("NPCs")
        local map = workspace:FindFirstChild("Map")
        local roots = {}
        if en then roots[#roots + 1] = en end
        if npcs then roots[#roots + 1] = npcs end
        if map then roots[#roots + 1] = map end
        roots[#roots + 1] = workspace
        -- First pass: direct children of the expected containers and workspace root.
        for _, root in ipairs(roots) do
            local direct = djDirectNamed(root, name, true, DJ_SEARCH_RADIUS)
            if direct then return direct end
        end
        local now = os.clock()
        local key = "named:" .. normName(name)
        local perRoot = djScanCache[workspace]
        if not perRoot then perRoot = {}; djScanCache[workspace] = perRoot end
        local state = perRoot[key]
        if state and now - state.at < 0.5 then
            if state.object and alive(state.object) then
                local r = state.object:FindFirstChild("HumanoidRootPart")
                local h = getRoot()
                if not h or (r and (r.Position - h.Position).Magnitude <= DJ_SEARCH_RADIUS) then return state.object end
            end
            return nil
        end
        local h = getRoot()
        local best, bestD
        local seen = setmetatable({}, { __mode = "k" })
        -- Recursive fallback searches the event containers first, then the full workspace once.
        local deepRoots = {}
        if en then deepRoots[#deepRoots + 1] = en end
        if npcs then deepRoots[#deepRoots + 1] = npcs end
        if map then deepRoots[#deepRoots + 1] = map end
        deepRoots[#deepRoots + 1] = workspace
        for _, root in ipairs(deepRoots) do
            if root then
                for _, obj in ipairs(root:GetDescendants()) do
                    if not seen[obj] then
                        seen[obj] = true
                        if obj:IsA("Model") and normName(obj.Name) == normName(name) and alive(obj) then
                            local r = obj:FindFirstChild("HumanoidRootPart")
                            local d = h and r and (r.Position - h.Position).Magnitude or 0
                            if not h or (r and d <= DJ_SEARCH_RADIUS) then
                                if not bestD or d < bestD then best, bestD = obj, d end
                            end
                        end
                    end
                end
            end
        end
        perRoot[key] = { at = now, object = best }
        return best
    end
    local function djFindGate() return djFindNamed(DJ_GATE) end
    local function djFindBoss() return djFindNamed(DJ_BOSS) or djFindNamed(DJ_GATE) end
    local function djHold()
        local h = getRoot()
        if h then pcall(_tp, h.CFrame) end
    end
    local function djWait(sec, valid)
        local t0 = tick()
        while tick() - t0 < sec and valid() do
            djHold()
            task.wait(0.1)
        end
        return valid()
    end
    local function djReachWitch(valid)
        local deadline = tick() + 180
        while valid() and tick() < deadline do
            task.wait(0.1)
            local h = getRoot()
            if not h then return false end
            local npcs = workspace:FindFirstChild("NPCs")
            local map = workspace:FindFirstChild("Map")
            local w = djDirectNamed(npcs, "Witch", false, DJ_SEARCH_RADIUS)
                or djDirectNamed(workspace, "Witch", false, DJ_SEARCH_RADIUS)
                or djDirectNamed(map, "Witch", false, DJ_SEARCH_RADIUS)
            local wcf = w and pivotOf(w)
            if not wcf then
                w = djFindNested(workspace, "Witch", DJ_SEARCH_RADIUS, false)
                wcf = w and pivotOf(w)
            end
            if wcf then
                if (h.Position - wcf.Position).Magnitude <= DJ_INTERACT_RANGE then
                    djHold()
                    return true
                end
                pcall(_tp, CFrame.new(wcf.Position))
            else
                local icf = djIslandCF()
                if not icf then return false end
                if (h.Position - icf.Position).Magnitude <= 40 then
                    djHold()
                else
                    pcall(_tp, icf)
                end
            end
        end
        return false
    end
    local function djSummon()
        return pcall(function()
            return game:GetService("ReplicatedStorage").Remotes.DapperJackRitual:InvokeServer("Summon")
        end)
    end
    local function djReachCompass(valid)
        local t0 = tick()
        while valid() and tick() - t0 < 60 do
            task.wait(0.1)
            local h = getRoot()
            if not h then return nil end
            local c = djFindNested(workspace, "GreatPumpkinCompass", DJ_SEARCH_RADIUS, false)
            local cf = c and pivotOf(c)
            if cf then
                if (h.Position - cf.Position).Magnitude <= DJ_INTERACT_RANGE then
                    djHold()
                    return c
                end
                pcall(_tp, CFrame.new(cf.Position))
            else
                djHold()
                if tick() - t0 > 10 then return nil end
            end
        end
        return nil
    end
    local function djHoldE(obj, valid)
        local prompt = obj:FindFirstChildWhichIsA("ProximityPrompt", true)
        local hold = prompt and prompt.HoldDuration or 0
        local dur = math.max(1, hold + 0.1)
        local vim = game:GetService("VirtualInputManager")
        if prompt then
            pcall(function() prompt.RequiresLineOfSight = false end)
            if fireproximityprompt and prompt.Enabled then
                pcall(fireproximityprompt, prompt, dur)
            end
            pcall(function() prompt:InputHoldBegin() end)
        end
        vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
        local t0 = tick()
        while tick() - t0 < dur and valid() do
            djHold()
            task.wait(0.1)
        end
        vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        if prompt then pcall(function() prompt:InputHoldEnd() end) end
    end
    local function djFarmBoss(boss, valid)
        while valid() and alive(boss) do
            pcall(Attack.Kill, boss, valid)
            task.wait(0.1)
        end
    end
    local function djCandyItems()
        local list = {}
        local root = workspace:FindFirstChild("CandySpillFx")
        if root then
            for _, c in ipairs(root:GetChildren()) do
                if c:IsA("Model") or c:IsA("BasePart") then list[#list + 1] = c end
            end
        end
        return list
    end
    local function djCollectCandy(valid)
        local visited = setmetatable({}, { __mode = "k" })
        local t0 = tick()
        while valid() and tick() - t0 < 10 and #djCandyItems() == 0 do
            djHold()
            task.wait(0.1)
        end
        local startT, lastSeen = tick(), tick()
        while valid() and tick() - startT < 90 do
            task.wait(0.1)
            local h = getRoot()
            if not h then return end
            local items = djCandyItems()
            local best, bestD
            for pass = 1, 2 do
                for _, c in ipairs(items) do
                    local cf = not visited[c] and pivotOf(c)
                    if cf then
                        local d = (cf.Position - h.Position).Magnitude
                        if not bestD or d < bestD then best, bestD = c, d end
                    end
                end
                if best or #items == 0 then break end
                table.clear(visited)
            end
            if not best then
                if tick() - lastSeen > 1.5 then return end
                djHold()
            else
                lastSeen = tick()
                visited[best] = true
                local t1 = tick()
                while valid() and best.Parent and tick() - t1 < 6 do
                    local h2 = getRoot()
                    local cf = pivotOf(best)
                    if not h2 or not cf then break end
                    if (h2.Position - cf.Position).Magnitude <= 4 then break end
                    pcall(_tp, CFrame.new(cf.Position))
                    task.wait(0.1)
                end
            end
        end
    end
    local function djResetPlayer(valid)
        local oldChar = lp.Character
        local hum = oldChar and oldChar:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.Health = 0 end) end
        if oldChar then pcall(function() oldChar:BreakJoints() end) end
        local t0 = tick()
        while valid() and tick() - t0 < 20 do
            task.wait(0.2)
            local c = lp.Character
            if c and c ~= oldChar and getRoot() then break end
        end
        if valid() then task.wait(1) end
    end
    local function djInArena()
        local h = getRoot()
        local map = workspace:FindFirstChild("Map")
        local arena = map and map:FindFirstChild("DapperJackArena")
        if not h or not arena then return false end
        local ok, inside = pcall(function()
            local cf, size
            if arena:IsA("Model") then
                cf, size = arena:GetBoundingBox()
            else
                local mn, mx
                for _, d in ipairs(arena:GetDescendants()) do
                    if d:IsA("BasePart") then
                        local lo, hi = d.Position - d.Size / 2, d.Position + d.Size / 2
                        mn = mn and Vector3.new(math.min(mn.X, lo.X), math.min(mn.Y, lo.Y), math.min(mn.Z, lo.Z)) or lo
                        mx = mx and Vector3.new(math.max(mx.X, hi.X), math.max(mx.Y, hi.Y), math.max(mx.Z, hi.Z)) or hi
                    end
                end
                if not mn then return false end
                cf, size = CFrame.new((mn + mx) / 2), mx - mn
            end
            local rel = cf:PointToObjectSpace(h.Position)
            return math.abs(rel.X) <= size.X / 2 + DJ_ARENA_PAD_XZ and math.abs(rel.Y) <= size.Y / 2 + DJ_ARENA_PAD_Y and math.abs(rel.Z) <= size.Z / 2 + DJ_ARENA_PAD_XZ
        end)
        return ok and inside == true
    end
    local function djWaitArenaBoss(valid, maxSec)
        local t0 = tick()
        while valid() and tick() - t0 < (maxSec or 90) do
            local g = djFindGate()
            if g then return g end
            if djInArena() then
                local b = djFindBoss()
                if b then return b end
            end
            djHold()
            task.wait(0.1)
        end
        return nil
    end
    local function djKill(boss, valid)
        local isGate = boss.Name == DJ_GATE
        djFarmBoss(boss, valid)
        if isGate then return end
        if valid() and not alive(boss) then
            djCollectCandy(valid)
            djResetPlayer(valid)
        end
    end
    local function djRound(valid)
        local gate = djFindGate()
        if gate then
            djKill(gate, valid)
            return
        end
        local inArena = djInArena()
        local boss = djFindBoss()
        if inArena then
            if boss then
                djKill(boss, valid)
                return
            end
            if #djCandyItems() > 0 then
                djCollectCandy(valid)
                djResetPlayer(valid)
                return
            end
            boss = djWaitArenaBoss(valid, 15)
            if not boss then
                if valid() and djInArena() then djResetPlayer(valid) end
                return
            end
        else
            local hasCompass = djFindNested(workspace, "GreatPumpkinCompass", DJ_SEARCH_RADIUS, false) ~= nil
            if not (boss and not hasCompass) then
                if not hasCompass then
                    if not djReachWitch(valid) then return end
                    djSummon()
                    if not djWait(15, valid) then return end
                end
                local compass = djReachCompass(valid)
                if not compass then
                    task.wait(3)
                    return
                end
                if not djWait(0.5, valid) then return end
                djHoldE(compass, valid)
            end
            boss = djWaitArenaBoss(valid)
            if not boss then
                if valid() and djInArena() then djResetPlayer(valid) end
                return
            end
        end
        djKill(boss, valid)
    end
    UIX.Toggle(hwTab, "Quests_AutoDapperJack", {
        Title = "Auto Summon + Farm Boss (Dapper Jack)",
        Description = "Tìm trực tiếp trước rồi quét lồng sâu Witch, GreatPumpkinCompass, Dapper Jack và Hellfire Gas trong 6000 stud; nhận diện arena, đánh boss và nhặt CandySpillFx.",
        Default = false,
        Callback = function(v)
            _G.AutoDapperJack = v
            djTok = djTok + 1
            if not v then return end
            local tok = djTok
            local function valid()
                return _G.AutoDapperJack and djTok == tok and owned("HWDapperJack")
            end
            task.spawn(function()
                while _G.AutoDapperJack and djTok == tok do
                    task.wait(0.2)
                    pcall(function()
                        if not owned("HWDapperJack") then return end
                        djRound(valid)
                    end)
                end
            end)
        end,
    })
end
end
