do
    local FX = _G.FARMX
    FX.Dun = { exit = nil, exitT = -1e9, tgt = nil, tgtT = -1e9, parts = nil, partsChar = nil, partsT = -1e9 }
    FX.DungeonExit = function(fn)
        local d, now = FX.Dun, os.clock()
        if now - d.exitT >= FX.Cfg.DungeonExitTTL then
            d.exit = fn()
            d.exitT = now
        end
        return d.exit
    end
    FX.DungeonTarget = function(fn)
        local d, now = FX.Dun, os.clock()
        local t = d.tgt
        local alive = t and t.Parent and t:FindFirstChildOfClass("Humanoid") and t:FindFirstChildOfClass("Humanoid").Health > 0
        if alive and now - d.tgtT < FX.Cfg.DungeonTargetTTL then return t end
        d.tgt = fn()
        d.tgtT = now
        return d.tgt
    end
    FX.DungeonNoclip = function(char)
        local d, now = FX.Dun, os.clock()
        if d.partsChar ~= char or not d.parts or now - d.partsT >= FX.Cfg.DungeonNoclipTTL then
            local list = {}
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then list[#list + 1] = p end
            end
            d.parts, d.partsChar, d.partsT = list, char, now
        end
        for _, p in ipairs(d.parts) do
            if p.Parent then p.CanCollide = false end
        end
    end
end
RunSer.Stepped:Connect(function()
    if not _G.AutoFarm_DungeonFix or not inDungeonPlace() then dungeonCombatActive = false; return end
    local char = plr.Character
    local h = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not (char and h and h.Health > 0 and root) then dungeonCombatActive = false; return end
    local FXd = _G.FARMX
    local target, exitFrame
    if FXd.Enable.DungeonThrottle then
        FXd.DungeonNoclip(char)
        root.AssemblyLinearVelocity = Vector3.zero
        target = FXd.DungeonTarget(getDungeonNearestMob)
        exitFrame = FXd.DungeonExit(getDungeonExitTeleporter)
    else
        for _, p in ipairs(char:GetDescendants()) do if p:IsA("BasePart") then p.CanCollide = false end end
        root.AssemblyLinearVelocity = Vector3.zero
        target = getDungeonNearestMob()
        exitFrame = getDungeonExitTeleporter()
    end
    if dungeonMustTouchTeleport and exitFrame then
        dungeonCombatActive = false; moveDungeonTo(exitFrame)
        if (root.Position - exitFrame.Position).Magnitude < 8 then
            if dungeonTweenObj then pcall(function() dungeonTweenObj:Cancel() end) end
            root.CFrame = exitFrame; dungeonMustTouchTeleport = false
        end; return
    end
    if target then
        dungeonWaitingForSpawn = false; dungeonCombatActive = true; equipDungeonWeapon()
        local tr = target:FindFirstChild("HumanoidRootPart")
        if tr then
            local tp = tr.CFrame * CFrame.new(0, 15, 0)
            if (root.Position - tp.Position).Magnitude > 10 then moveDungeonTo(tp)
            else
                if dungeonTweenObj then pcall(function() dungeonTweenObj:Cancel() end) end
                root.CFrame = CFrame.new(tp.Position, tr.Position)
            end
        end
    else
        dungeonCombatActive = false
        if not dungeonWaitingForSpawn and exitFrame then
            moveDungeonTo(exitFrame)
            if (root.Position - exitFrame.Position).Magnitude < 8 then
                if dungeonTweenObj then pcall(function() dungeonTweenObj:Cancel() end) end
                root.CFrame = exitFrame; dungeonWaitingForSpawn = true
            end
        elseif not exitFrame then
            if dungeonTweenObj then pcall(function() dungeonTweenObj:Cancel() end) end
        end
    end
end)
