task.spawn(function()
    local PlayersSvc = game:GetService("Players")
    while task.wait(((_G.FARMX and _G.FARMX.Cfg and _G.FARMX.Cfg.DungeonAttackGap) or 0.2)) do
        local FXk = _G.FARMX
        if not (FXk and FXk.Enable and FXk.Enable.DungeonAttackV2 and _G.FastAttack_Dungeon and _G.AutoFarm_DungeonFix and inDungeonPlace()) then continue end
