        pcall(function()
            local char = plr.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local folder = workspace:FindFirstChild("Enemies")
            local modules = replicated:FindFirstChild("Modules")
            local net = modules and modules:FindFirstChild("Net")
            local regHit = net and net:FindFirstChild("RE/RegisterHit")
            local regAtk = net and net:FindFirstChild("RE/RegisterAttack")
            if not (root and folder and regHit) then return end
            local range, maxN, n = FXk.Cfg.DungeonAttackRange or 60, FXk.Cfg.DungeonAttackMax or 8, 0
            for _, enemy in ipairs(folder:GetChildren()) do
                if n >= maxN then break end
                local h = enemy:FindFirstChildOfClass("Humanoid")
                local er = enemy:FindFirstChild("HumanoidRootPart")
                if enemy ~= char and h and h.Health > 0 and er and not PlayersSvc:GetPlayerFromCharacter(enemy)
                    and not isDungeonIgnored(enemy) and (er.Position - root.Position).Magnitude <= range then
                    n = n + 1
                    regHit:FireServer(er, { { enemy, er } })
                    if regAtk then regAtk:FireServer(0) end
                    if FXk.TraceAdd and n == 1 then pcall(FXk.TraceAdd, "DUNGEON_ATTACK", enemy.Name) end
                end
            end
        end)
    end
end)
do
    local FX = _G.FARMX
    local cs = { gui = nil, scanT = -1e9, clickT = -1e9, since = nil }
    local known = { "BuffSelectorMenu", "Interface", "DungeonUI", "CardSelector", "BuffMenu" }
    local function shown(g)
        if not g then return false end
        if g:IsA("LayerCollector") then return g.Enabled end
        if g:IsA("GuiObject") then return g.Visible end
        return false
    end
    local function isCardish(name)
        return name:find("card", 1, true) ~= nil or name:find("buff", 1, true) ~= nil or name:find("option", 1, true) ~= nil
    end
    local function clickObject(o)
        if not (VirtualInputManager and VirtualInputManager.SendMouseButtonEvent) then return end
        local x = o.AbsolutePosition.X + o.AbsoluteSize.X / 2
        local y = o.AbsolutePosition.Y + o.AbsoluteSize.Y / 2 + 58
        VirtualInputManager:SendMouseButtonEvent(x, y, 0, true, game, 1)
        task.wait(0.08)
        VirtualInputManager:SendMouseButtonEvent(x, y, 0, false, game, 1)
    end
    local function findGui(pg, now)
        local g = cs.gui
        if g and g.Parent and shown(g) then return g end
        g = nil
        for _, n in ipairs(known) do
            local c = pg:FindFirstChild(n)
            if shown(c) then g = c break end
        end
        if not g and now - cs.scanT >= FX.Cfg.CardRescan then
            cs.scanT = now
            for _, gui in ipairs(pg:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Enabled and gui.Name ~= "Main" then
                    for _, o in ipairs(gui:GetDescendants()) do
                        local nm = o.Name:lower()
                        if nm:find("card", 1, true) or nm:find("buff", 1, true) then g = gui break end
                    end
                end
                if g then break end
            end
        end
        cs.gui = g
        return g
    end
    FX.CardStep = function()
        if not (FX.Enable.Cards and _G.AutoSelectCard and inDungeonPlace()) then
            cs.gui, cs.since = nil, nil
            return
        end
        local now = os.clock()
        if now - cs.clickT < FX.Cfg.CardClickCooldown then return end
        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        local gui = findGui(pg, now)
        if not gui then
            cs.since = nil
            return
        end
        cs.since = cs.since or now
        local hasSelected = false
        for _, en in pairs(_G.SelectedCards) do
            if en then hasSelected = true break end
        end
        local first, match
        for _, o in ipairs(gui:GetDescendants()) do
            if o:IsA("GuiObject") and o.Visible and o.AbsoluteSize.X >= 40 and o.AbsoluteSize.Y >= 40 and isCardish(o.Name:lower()) then
                first = first or o
                if hasSelected then
                    local text = ""
                    if o:IsA("TextLabel") or o:IsA("TextButton") then text = tostring(o.Text):lower() .. " " end
                    for _, ch in ipairs(o:GetDescendants()) do
                        if ch:IsA("TextLabel") or ch:IsA("TextButton") then text = text .. tostring(ch.Text):lower() .. " " end
                    end
                    local nm = o.Name:lower()
                    for cardName, en in pairs(_G.SelectedCards) do
                        if en then
                            local l = cardName:lower()
                            if nm:find(l, 1, true) or text:find(l, 1, true) then match = o break end
                        end
                    end
                    if match then break end
                else
                    match = o
                    break
                end
            end
        end
        if not match and hasSelected and first and now - cs.since >= FX.Cfg.CardFallbackAfter then
            match = first
        end
        if match then
            cs.clickT = now
            cs.since = nil
            clickObject(match)
        end
    end
    task.spawn(function()
        while task.wait(FX.Cfg.CardPoll) do
            if _G.FARMX ~= FX then break end
            local ok, err = pcall(FX.CardStep)
            if not ok then FX.Log("card", err) end
        end
    end)
end
