do
    UIX.Button(Tabs.Misc, nil, {
    Title =  "Test Webhook",
    Description =  "Gửi embed test để kiểm tra URL có hoạt động không",
    Callback =  function()
        if not _G.WH_MasterURL or _G.WH_MasterURL == "" then
            Library:Notify({ Title = "Webhook", Content = "Master URL rỗng — nhập URL trước.", Duration = 3 })
            return
        end
        local req = (syn and syn.request) or (http and http.request) or http_request or request
        if not req then
            Library:Notify({ Title = "Webhook", Content = "Executor không hỗ trợ HTTP request.", Duration = 4 })
            return
        end
        local ok, err = pcall(function()
            req({
                Url = _G.WH_MasterURL,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = game:GetService("HttpService"):JSONEncode({
                    username = "Tiro Notifier",
                    embeds = {{
                        title = "🧪 Webhook Test",
                        color = 3447003,
                        description = "Nếu bạn thấy tin nhắn này, master webhook URL hoạt động tốt.",
                        footer = { text = "Tiro Notifier v2 (maru PHASE87)" },
                        timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
                    }}
                })
            })
        end)
        if ok then
            Library:Notify({ Title = "Webhook", Content = "Test đã gửi thành công.", Duration = 3 })
        else
            Library:Notify({ Title = "Webhook", Content = "Test thất bại: " .. tostring(err), Duration = 5 })
        end
    end
})
end
