    local t0 = os.clock()
    local ok, data = pcall(function() return game:HttpGet(u) end)
    local log = _G.FARMX.NetLog
    log[#log + 1] = { u, ok and "ok" or tostring(data), math.floor((os.clock() - t0) * 1000) }
    if #log > 40 then table.remove(log, 1) end
    if not ok and not _G.FARMX.NetSeen[u] then
      _G.FARMX.NetSeen[u] = true
      pcall(function() Library:Notify({ Title = "Maru", Content = "Tải thất bại: " .. string.sub(u, 1, 60), Duration = 3 }) end)
