Library.AudioB64 = {}
Library.AudioB64[1] = [==[]==]
Library.AudioB64[2] = [==[]==]
Library.AudioB64[3] = [==[]==]
Library.AudioB64[4] = [==[]==]
Library.AudioB64[5] = [==[]==]
Library.AudioB64[6] = [==[]==]
Library.AudioB64[7] = [==[]==]
Library.AudioB64[8] = [==[]==]
Library.AudioB64[9] = [==[]==]
Library.AudioGet = function(n)
    local s = Library.AudioB64[n]
    if type(s) ~= "string" then return nil end
    local want = math.floor(#s * 3 / 4)
    local fast = (crypt and (crypt.base64decode or (crypt.base64 and (crypt.base64.decode or crypt.base64.Decode)))) or base64_decode or (base64 and (base64.decode or base64.Decode)) or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
    if fast then
        local ok, r = pcall(fast, s)
        if ok and type(r) == "string" and math.abs(#r - want) <= 4 then return r end
    end
    local alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local DEC = {}
    for i = 1, 64 do DEC[string.byte(alpha, i)] = i - 1 end
    local pad = 0
    if string.sub(s, -2) == "==" then pad = 2 elseif string.sub(s, -1) == "=" then pad = 1 end
    local out, blk, nb = {}, {}, 0
    for i = 1, #s, 4 do
        local a, b, c, d = string.byte(s, i, i + 3)
        a, b, c, d = DEC[a] or 0, DEC[b] or 0, DEC[c] or 0, DEC[d] or 0
        local v = a * 262144 + b * 4096 + c * 64 + d
        blk[#blk + 1] = math.floor(v / 65536)
        blk[#blk + 1] = math.floor(v / 256) % 256
        blk[#blk + 1] = v % 256
        if #blk >= 3000 then
            out[#out + 1] = string.char(table.unpack(blk))
            blk = {}
            nb = nb + 1
            if nb % 80 == 0 then task.wait() end
        end
    end
    if #blk > 0 then out[#out + 1] = string.char(table.unpack(blk)) end
    local res = table.concat(out)
    if pad > 0 then res = string.sub(res, 1, #res - pad) end
    return res
end
