        pcall(function() Library:Notify({Title = "Music", Content = "ID không hợp lệ. Nhập dãy số, ví dụ 1837879082", Duration = 4}) end)
        return
    end
    for i, t in ipairs(MaruPlaylist) do
        if t.isId and t.asset == id then
            MaruPlayTrack(i)
            return
        end
    end
    local tr = {
        name = "ID " .. id, artist = "Roblox Audio", genre = "ID", url = "rbxassetid://" .. id, asset = id, isId = true,
        label = "ID " .. id .. " — Roblox Audio [ID]"
    }
    table.insert(MaruPlaylist, tr)
    table.insert(MaruFiltered, {index = #MaruPlaylist, track = tr})
    MaruPlayTrack(#MaruPlaylist)
end

