    TS:Create(menu, TweenInfo.new(0.34, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(132, 86) }):Play()
    local mine = menu
    task.delay(4.5, function() if menu == mine then closeMenu() end end)
