-- [WEBHOOK-LOGIC] P87 ===== Tiro Webhook Notifier v2 — config load + Post + main loop =====
do
    local _WH_Http = game:GetService("HttpService")
    local _WH_Players = game:GetService("Players")
    local _WH_RS = game:GetService("ReplicatedStorage")
    local _WH_CS = game:GetService("CollectionService")
    local _WH_Lighting = game:GetService("Lighting")
    local _WH_ws = workspace

    -- Default config
    _G.WH_MasterURL = _G.WH_MasterURL or ""
    _G.WH_Enabled = (_G.WH_Enabled ~= false)
    _G.WH_Cooldown = _G.WH_Cooldown or 120
    _G.WH_AllToMaster = _G.WH_AllToMaster or false

    -- Load saved config
    pcall(function()
        if isfile and isfile("webhook_config.txt") then
            local data = _WH_Http:JSONDecode(readfile("webhook_config.txt"))
            if type(data) == "table" then
                if type(data.URL) == "string" then _G.WH_MasterURL = data.URL end
                if type(data.Enabled) == "boolean" then _G.WH_Enabled = data.Enabled end
                if type(data.Cooldown) == "number" then _G.WH_Cooldown = data.Cooldown end
            end
        end
    end)

    -- Hardcoded per-event URLs (13 channels)
    local WH_URL = {
        Fruits    = "https://discord.com/api/webhooks/1568141144049717391/R2wy_fFgMMVqlV_dSMpZxbfAaQ2e6toRsR6ndMTCg9_ORq8xraF1P6X7ODa6Moqh9k-s",
        Events    = "https://discord.com/api/webhooks/1568135006948433962/kW5ZMHqpkQM46Xy98bcD64M-hIKSRhIbH8OMEzcB3FXWwN8KDPIQts51WwGZPdIyeFRp",
        FullMoon  = "https://discord.com/api/webhooks/1568141804434493530/I1Hg0NHJ3n63b_P329w2cgBMTv99X5hsgs8yDA9jsijDpwot-rI2WwggZ7V8S_DhsoCn",
        NearMoon  = "https://discord.com/api/webhooks/1568141602948382791/Xd2Yp0tZ7I8tW8ii8_eQTJAJvE_l063S4kJaEC3bNRs-j-3plasrRbajQbZg9Soqj6IA",
        Island    = "https://discord.com/api/webhooks/1568140704398704672/_GDvj3lpS-rPPqMfQ372sJgdp35BsUO4B2Ng1S0kkr1GXaFUVxwz8bLkvckKEcOkTZX-",
        Elite     = "https://discord.com/api/webhooks/1568140431747850380/WNKyepRP5-WT0Em9nmUoLRt9ZYTz3mq_akYmxJp_YAqyb7gMCoSq26l3j1fvTnHD0gkc",
        RipIndra  = "https://discord.com/api/webhooks/1568136332847349780/9RElYPN5OXPCwROSvH4i3uApeZMDmLrn2EAf_3uu0YjmGQWJBS1o14AhEsNEEy5oPrEX",
        Dough     = "https://discord.com/api/webhooks/1568140278659809312/GTHZPzPZdSsxdjhmVHRI-hDJQ7pOVEBqAT16PEi6S_SnKePfjC3hMlpduLASQkJhRQQV",
        Cake      = "https://discord.com/api/webhooks/1568140090176180334/dl14tz6eeNREy6uIUsqTLUtYvxC4F8Ytl1O5pf7HmGxqxAyJUwZ2Eqj6Y5mPXo6wT4Ie",
        Soul      = "https://discord.com/api/webhooks/1568134958571192420/2_UYGoHCZtQ-fVuctGLT_KP3gxYCWcIK4yHHJ-UP6eoSWoYVsPuDTk4MzXCJWb2chA28",
        Cursed    = "https://discord.com/api/webhooks/1568254230861586442/mykVovkVIbRUU5dR8o-rGwVtRggRkej-MKD5JDyQZEf9qcBq9zaOnc72lS0dByOpa9Bc",
        Tyrant    = "https://discord.com/api/webhooks/1568135543802433648/fOPw2WqOpka-s-uetfwDC4KFC4nrVV-I93QmZyq4vUnMBkglNWJuOyiHQP8EGhDFpf91",
        Darkbeard = "https://discord.com/api/webhooks/1568254394850349147/4HCnnk0ZVRBksQIyZMwf0Q4WPJ9BBUGS58aW-1zmY3hGyjvtNvKx6slBSnMF_3iWip2Y",
    }

    local WH_cooldowns = {}
    local function WH_canSend(key)
        if not _G.WH_Enabled then return false end
        local t = WH_cooldowns[key]
        if not t then return true end
        return (os.clock() - t) >= (_G.WH_Cooldown or 120)
    end
    local function WH_markSent(key)
        WH_cooldowns[key] = os.clock()
    end

    -- Sea detect
    local WH_sea = "Unknown"
    local _pid = game.PlaceId
    if _pid == 2753915549 or _pid == 85211729168715 then
        WH_sea = "First Sea"
    elseif _pid == 4442272183 or _pid == 79091703265657 then
        WH_sea = "Second Sea"
    elseif _pid == 7449423635 or _pid == 100117331123089 then
        WH_sea = "Third Sea"
    end

    -- Detectors
    local function WH_Mirage()
        local map = _WH_ws:FindFirstChild("Map")
        return map ~= nil and map:FindFirstChild("MysticIsland") ~= nil
    end
    local function WH_Mob(name)
        local en = _WH_ws:FindFirstChild("Enemies")
        local m = en and en:FindFirstChild(name)
        if m then
            local h = m:FindFirstChildOfClass("Humanoid")
            local hr = m:FindFirstChild("HumanoidRootPart")
            if h and hr and h.Health > 0 then return m end
        end
        local m2 = _WH_RS:FindFirstChild(name)
        if m2 then
            local h = m2:FindFirstChildOfClass("Humanoid")
            local hr = m2:FindFirstChild("HumanoidRootPart")
            if h and hr and h.Health > 0 then return m2 end
        end
    end
    local function WH_Fruits()
        for _, v in _WH_ws:GetChildren() do
            if string.find(v.Name, "Fruit") and (v:IsA("Tool") or v:IsA("Model")) and v.Name ~= "Fruit" then
                return v
            end
        end
    end
    local function WH_MoonPhase()
        local phase = _WH_Lighting:GetAttribute("MoonPhase")
        return phase
    end

    -- Build embed
    local function WH_buildEmbed(arg, seaStr)
        local t = arg.Type or "Notification"
        local title, fieldName, fieldValue, color
        if t == "RipIndra" then
            title, fieldName, fieldValue, color = "👿 Rip Indra True Form Spawned!", "Boss", "rip_indra True Form", 10038562
        elseif t == "RareBoss" then
            title, fieldName, fieldValue, color = "👹 Rare Boss: " .. tostring(arg.RareBoss), "Boss", tostring(arg.RareBoss), 15158332
        elseif t == "Elite" then
            title, fieldName, fieldValue, color = "⚔️ Elite Hunter: " .. tostring(arg.Elite), "Elite Boss", tostring(arg.Elite), 15105570
        elseif t == "Mirage" then
            title, fieldName, fieldValue, color = "🏝️ Mirage Island Spawned!", "Event", "Mirage Island (Mystic Island)", 10181046
        elseif t == "Fruits" then
            title, fieldName, fieldValue, color = "🍎 Fruit Spawned: " .. tostring(arg.Fruits), "Fruit", tostring(arg.Fruits), 3066993
        elseif t == "FullMoon" then
            title, fieldName, fieldValue, color = "🌕 Full Moon (100%) Active!", "Moon Phase", "Full Moon (Phase 5)", 15965202
        elseif t == "NearMoon" then
            title, fieldName, fieldValue, color = "🌖 Near Full Moon Active!", "Moon Phase", "Near Moon (Phase 4)", 13849600
        else
            title, fieldName, fieldValue, color = "Blox Fruits - " .. t, "Detail", "None", 3447003
        end
        local placeId = tostring(arg.PlaceId or game.PlaceId)
        local jobId = tostring(arg.JobId or game.JobId)
        local players = tostring(arg.Players or _WH_Players.NumPlayers .. "/" .. _WH_Players.MaxPlayers)
        local sea = tostring(arg.Sea or seaStr or "Unknown")
        local teleport = string.format(
            "game:GetService('TeleportService'):TeleportToPlaceInstance(%s, '%s', game.Players.LocalPlayer)",
            placeId, jobId
        )
        return {
            username = "Tiro Notifier",
            embeds = {{
                title = title, color = color,
                fields = {
                    { name = fieldName, value = "```"..fieldValue.."```", inline = true },
                    { name = "Sea", value = sea, inline = true },
                    { name = "Players", value = players, inline = true },
                    { name = "PlaceId", value = placeId, inline = true },
                    { name = "JobId", value = "```"..jobId.."```", inline = false },
                    { name = "Teleport Code", value = "```lua\n"..teleport.."\n```", inline = false },
                },
                footer = { text = "Tiro Notifier v2 (maru PHASE87)" },
                timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            }}
        }
    end

    -- Post function
    local function WH_Post(arg, hardcodedURL)
        task.spawn(function()
            local ok, err = pcall(function()
                if not _G.WH_Enabled then return end
                local url = hardcodedURL
                if _G.WH_AllToMaster or (not url or url == "") then
                    url = _G.WH_MasterURL
                end
                if (not url) or url == "" then return end
                local req = (syn and syn.request) or (http and http.request) or http_request or request
                if not req then return end
                req({
                    Url = url, Method = "POST",
                    Headers = { ["Content-Type"] = "application/json" },
                    Body = _WH_Http:JSONEncode(WH_buildEmbed(arg, WH_sea))
                })
            end)
            if not ok then
                warn("[Webhook] Post error: " .. tostring(err))
            end
        end)
    end

    -- Boss tables
    local ripIndra = "rip_indra True Form"
    local rareBosses = {
        "Dough King", "Cake Prince", "Soul Reaper", "Cursed Captain",
        "Tyrant of the Skies", "Darkbeard",
    }
    local bossWebhook = {
        ["Dough King"]          = WH_URL.Dough,
        ["Cake Prince"]         = WH_URL.Cake,
        ["Soul Reaper"]         = WH_URL.Soul,
        ["Cursed Captain"]      = WH_URL.Cursed,
        ["Tyrant of the Skies"] = WH_URL.Tyrant,
        ["Darkbeard"]           = WH_URL.Darkbeard,
    }
    local eliteBosses = { "Diablo", "Urban", "Deandre" }

    -- Main loop (30s scan)
    task.spawn(function()
        while true do
            local str3 = _WH_Players.NumPlayers .. "/" .. _WH_Players.MaxPlayers
            local str4 = tostring(game.JobId)
            local placeId = game.PlaceId

            -- Rip Indra (sea 3 only)
            if WH_sea == "Third Sea" then
                local key = "RareBoss_" .. ripIndra
                if WH_Mob(ripIndra) and WH_canSend(key) then
                    WH_markSent(key)
                    WH_Post({ Players = str3, JobId = str4, Sea = WH_sea, PlaceID = placeId, Type = "RipIndra" }, WH_URL.RipIndra)
                    task.wait(0.5)
                end
            end

            -- Rare bosses
            for _, name in ipairs(rareBosses) do
                local key = "RareBoss_" .. name
                if name == "Darkbeard" and WH_sea ~= "Second Sea" then
                    -- skip
                elseif WH_Mob(name) and WH_canSend(key) then
                    WH_markSent(key)
                    WH_Post({ Players = str3, RareBoss = name, JobId = str4, Sea = WH_sea, PlaceID = placeId, Type = "RareBoss" }, bossWebhook[name])
                    task.wait(0.5)
                end
            end

            -- Elite bosses
            for _, name in ipairs(eliteBosses) do
                local key = "Elite_" .. name
                if WH_Mob(name) and WH_canSend(key) then
                    WH_markSent(key)
                    WH_Post({ Players = str3, Elite = name, JobId = str4, Sea = WH_sea, PlaceID = placeId, Type = "Elite" }, WH_URL.Elite)
                    task.wait(0.5)
                end
            end

            -- Fruits
            local fruit = WH_Fruits()
            if fruit then
                local key = "Fruits_" .. tostring(fruit)
                if WH_canSend(key) then
                    WH_markSent(key)
                    WH_Post({ Players = str3, Fruits = tostring(fruit), JobId = str4, Sea = WH_sea, PlaceId = placeId, Type = "Fruits" }, WH_URL.Fruits)
                    task.wait(0.5)
                end
            end

            -- Mirage Island
            if WH_Mirage() and WH_canSend("Mirage") then
                WH_markSent("Mirage")
                WH_Post({ Players = str3, Mirage = true, JobId = str4, Sea = WH_sea, PlaceId = placeId, Type = "Mirage" }, WH_URL.Island)
                task.wait(0.5)
            end

            -- Moon
            local phase = WH_MoonPhase()
            if phase == 5 and WH_canSend("FullMoon") then
                WH_markSent("FullMoon")
                WH_Post({ Players = str3, Moon = "Full Moon", JobId = str4, Sea = WH_sea, PlaceId = placeId, Type = "FullMoon" }, WH_URL.FullMoon)
                task.wait(0.5)
            elseif phase == 4 and WH_canSend("NearMoon") then
                WH_markSent("NearMoon")
                WH_Post({ Players = str3, Moon = "Near Moon", JobId = str4, Sea = WH_sea, PlaceId = placeId, Type = "NearMoon" }, WH_URL.NearMoon)
                task.wait(0.5)
            end

            task.wait(30)
        end
    end)

    Library:Notify({ Title = "Tiro Webhook Notifier", Content = "v2 đã merge vào maru PHASE87. Mở tab Miscellaneous để cấu hình.", Duration = 5 })
end
